  ('a6701131-3cdf-520a-8077-fb3dd7628742', '47139ef4-9c94-5d32-a05b-03686b39cf39', 'Before Afrobeat, Fela Kuti led a highlife-jazz band called?', '["Koola Lobitos","Nigeria 70","Highlife Rakers","Africa 70"]'::jsonb, 0, 5, 'Koola Lobitos was formed in the early 1960s.', 'https://en.wikipedia.org/wiki/Fela_Kuti', 'live'),
