  ('9da1a786-396e-5c17-9dae-14d8e5c00856', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Victor Moses won the Premier League with which club?', '["Liverpool","Everton","Chelsea","West Ham"]'::jsonb, 2, 2, 'He was a regular wing-back for Chelsea in 2016–17.', 'https://en.wikipedia.org/wiki/Victor_Moses', 'live'),
  ('71343707-5007-59b3-98f6-4bb0fdaf272c', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which two Nigerians started for Leicester City in their 2021 FA Cup final win?', '["Victor Moses and Wilfred Ndidi","Wilfred Ndidi and Kelechi Iheanacho","Ahmed Musa and Kelechi Iheanacho","Wilfred Ndidi and Alex Iwobi"]'::jsonb, 1, 2, 'Leicester beat Chelsea 1–0 at Wembley.', 'https://en.wikipedia.org/wiki/2021_FA_Cup_final', 'live'),
  ('279f86d1-bb3a-58f9-b9ca-e359a9d34d4f', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Odion Ighalo joined which giant club on loan in January 2020?', '["Barcelona","Juventus","Real Madrid","Manchester United"]'::jsonb, 3, 2, 'Ighalo had grown up a Manchester United fan.', 'https://en.wikipedia.org/wiki/Odion_Ighalo', 'live'),
  ('b428f171-585d-5a05-acf3-28de01bf5dd6', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who did Nigeria lose to in the 2023 Africa Cup of Nations final?', '["South Africa","Egypt","Ivory Coast","Senegal"]'::jsonb, 2, 2, 'The hosts won 2–1 in Abidjan in February 2024.', 'https://en.wikipedia.org/wiki/2023_Africa_Cup_of_Nations_final', 'live'),
  ('9292c53c-6d5d-5cd3-b75c-b723d0639f8e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian defender was named Player of the Tournament at the 2023 AFCON?', '["William Troost-Ekong","Calvin Bassey","Ola Aina","Semi Ajayi"]'::jsonb, 0, 2, 'Troost-Ekong also scored in the final.', 'https://en.wikipedia.org/wiki/William_Troost-Ekong', 'live'),
  ('ca6d1290-8758-5b9d-8116-c6a8250ce389', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria won its first AFCON title in 1980 in which city?', '["Ibadan","Lagos","Kano","Abuja"]'::jsonb, 1, 2, 'Nigeria beat Algeria 3–0 in the final.', 'https://en.wikipedia.org/wiki/1980_African_Cup_of_Nations', 'live'),
  ('02da3672-5069-575f-9c5b-4be2ee3fb3e4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who captained Nigeria to the 1980 AFCON title?', '["Muda Lawal","Christian Chukwu","Stephen Keshi","Segun Odegbami"]'::jsonb, 1, 2, 'Chukwu was nicknamed ''Chairman''.', 'https://en.wikipedia.org/wiki/Christian_Chukwu', 'live'),
  ('1e305658-c229-56a9-a5d6-eff0ba411775', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which 1980 AFCON hero was nicknamed ''Mathematical''?', '["Felix Owolabi","Adokiye Amiesimaka","Segun Odegbami","Muda Lawal"]'::jsonb, 2, 2, 'Odegbami scored twice in the 1980 final.', 'https://en.wikipedia.org/wiki/Segun_Odegbami', 'live'),
  ('6c2c6dbb-dd42-5c63-8d53-b6d0e2a5c107', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which team knocked Nigeria out of the 1994 World Cup in the round of 16?', '["Argentina","Brazil","Bulgaria","Italy"]'::jsonb, 3, 3, 'Roberto Baggio scored twice as Italy won 2–1 after extra time.', 'https://en.wikipedia.org/wiki/Nigeria_at_the_FIFA_World_Cup', 'live'),
  ('b8426896-8add-5236-a667-ca18bf4b3334', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria topped its 1994 World Cup group ahead of which team?', '["Germany","Argentina","Brazil","Italy"]'::jsonb, 1, 3, 'Nigeria finished first in Group D.', 'https://en.wikipedia.org/wiki/1994_FIFA_World_Cup_Group_D', 'live'),
  ('02855dc2-c8e8-5731-9028-61e25610a189', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who scored Nigeria''s winning goal against Spain at the 1998 World Cup?', '["Garba Lawal","Sunday Oliseh","Victor Ikpeba","Mutiu Adepoju"]'::jsonb, 1, 3, 'Oliseh''s long-range strike sealed a 3–2 win.', 'https://en.wikipedia.org/wiki/Sunday_Oliseh', 'live'),
  ('07ce6344-00b4-5ae8-b764-2ca944483ea2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian scored twice against Argentina at the 2014 World Cup?', '["Ahmed Musa","Emmanuel Emenike","Peter Odemwingie","Victor Moses"]'::jsonb, 0, 3, 'Musa later scored twice against Iceland in 2018 too.', 'https://en.wikipedia.org/wiki/Ahmed_Musa', 'live'),
  ('58e4fc4e-62d8-5108-a455-3bea2ab3880b', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who coached Nigeria at the 1994 World Cup and AFCON?', '["Philippe Troussier","Jo Bonfrere","Bora Milutinović","Clemens Westerhof"]'::jsonb, 3, 3, 'The Dutchman won the 1994 AFCON in Tunisia.', 'https://en.wikipedia.org/wiki/Clemens_Westerhof', 'live'),
  ('d09376f2-7d26-59c9-9e64-eb6c17c51f51', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who coached Nigeria''s 1996 Olympic gold-winning team?', '["Jo Bonfrere","Bora Milutinović","Shaibu Amodu","Clemens Westerhof"]'::jsonb, 0, 3, 'The squad was nicknamed the ''Dream Team''.', 'https://en.wikipedia.org/wiki/Jo_Bonfrere', 'live'),
  ('ee27f653-bdcf-5d10-9ae1-ff4ff66f6069', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria beat which team 4–3 in the 1996 Olympic semi-final?', '["Mexico","Portugal","Brazil","Argentina"]'::jsonb, 2, 3, 'Kanu scored a golden goal in extra time.', 'https://en.wikipedia.org/wiki/Football_at_the_1996_Summer_Olympics', 'live'),
  ('e3c205ee-7316-56a8-b8e2-b42cc8509ec6', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which country hosted the 1994 AFCON won by Nigeria?', '["Egypt","Tunisia","South Africa","Senegal"]'::jsonb, 1, 3, 'Nigeria beat Zambia 2–1 in the final.', 'https://en.wikipedia.org/wiki/1994_African_Cup_of_Nations', 'live'),
  ('76dcb2e3-cae7-5ce0-97a2-0f59b3a49788', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which country did Nigeria beat in the 2013 AFCON final?', '["Burkina Faso","Mali","Ghana","Ivory Coast"]'::jsonb, 0, 3, 'Sunday Mba scored the only goal.', 'https://en.wikipedia.org/wiki/2013_Africa_Cup_of_Nations_final', 'live'),
  ('f2db2603-55d5-5aa4-bc44-ff748d0d43e1', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who scored the winning goal in the 2013 AFCON final?', '["Brown Ideye","Victor Moses","Sunday Mba","Emmanuel Emenike"]'::jsonb, 2, 3, 'The final was played in Johannesburg.', 'https://en.wikipedia.org/wiki/Sunday_Mba', 'live'),
  ('4eaa1671-dcf3-5eb3-a2f3-974f0079f9ca', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria won Olympic football silver at Beijing 2008, losing the final to?', '["Cameroon","Belgium","Brazil","Argentina"]'::jsonb, 3, 3, 'Ángel Di María scored the only goal.', 'https://en.wikipedia.org/wiki/Football_at_the_2008_Summer_Olympics_%E2%80%93_Men%27s_tournament', 'live'),
  ('e79dc4a9-99a5-56da-bac7-885f816082ff', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'What medal did Nigeria win in men''s football at Rio 2016?', '["Silver","Bronze","None","Gold"]'::jsonb, 1, 3, 'Nigeria beat Honduras 3–2 in the bronze medal match.', 'https://en.wikipedia.org/wiki/Football_at_the_2016_Summer_Olympics_%E2%80%93_Men%27s_tournament', 'live'),
  ('31a1e72f-72ce-5d9f-834e-b2607c6640b2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who won the Golden Boot at the 2015 U-17 World Cup with a record 10 goals?', '["Victor Osimhen","Taiwo Awoniyi","Kelechi Nwakali","Samuel Chukwueze"]'::jsonb, 0, 3, 'Nigeria won that tournament in Chile.', 'https://en.wikipedia.org/wiki/2015_FIFA_U-17_World_Cup', 'live'),
  ('185ac1c6-8444-5624-8cac-3e3647d90bee', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Kelechi Iheanacho won the Golden Ball at which tournament?', '["2013 AFCON","2016 Olympics","2015 U-20 World Cup","2013 U-17 World Cup"]'::jsonb, 3, 3, 'Nigeria won the 2013 edition in the UAE.', 'https://en.wikipedia.org/wiki/2013_FIFA_U-17_World_Cup', 'live'),
  ('041fbcbd-ab91-5f76-b7fa-412fb942230a', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Asisat Oshoala has won African Women''s Footballer of the Year a record how many times?', '["3","5","6","4"]'::jsonb, 2, 3, 'Oshoala starred for FC Barcelona Femení.', 'https://en.wikipedia.org/wiki/Asisat_Oshoala', 'live'),
  ('39efb0fd-b864-5d3a-802e-61f4c99eb02e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s Super Falcons have qualified for how many Women''s World Cups?', '["Three","Five","Every edition since 1999","Every edition since 1991"]'::jsonb, 3, 3, 'Nigeria is one of only a few teams to play at every Women''s World Cup.', 'https://en.wikipedia.org/wiki/Nigeria_women%27s_national_football_team', 'live'),
  ('fcd6b387-6958-58fb-ae26-ac9d6bd140e5', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Hogan ''Kid'' Bassey became Nigeria''s first world boxing champion in which division?', '["Lightweight","Featherweight","Middleweight","Heavyweight"]'::jsonb, 1, 3, 'He won the world title in 1957.', 'https://en.wikipedia.org/wiki/Hogan_Bassey', 'live'),
  ('461d30d1-493b-5148-af07-c85d6a7ad9c5', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Dick Tiger held world titles at middleweight and which other division?', '["Welterweight","Lightweight","Light heavyweight","Heavyweight"]'::jsonb, 2, 3, 'Dick Tiger was born in Amaigbo, Imo State.', 'https://en.wikipedia.org/wiki/Dick_Tiger', 'live'),
  ('00580b88-d685-58ef-bde6-e1c7ed4d95c7', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Samuel Peter held which heavyweight world title in 2008?', '["WBC","WBO","WBA","IBF"]'::jsonb, 0, 3, 'Peter was nicknamed ''The Nigerian Nightmare'' before Usman.', 'https://en.wikipedia.org/wiki/Samuel_Peter', 'live'),
  ('daa8fe90-b384-5efa-95ba-e352fc691b0c', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which city hosted the 8th All-Africa Games in 2003?', '["Kaduna","Abuja","Port Harcourt","Lagos"]'::jsonb, 1, 3, 'Lagos had hosted the 2nd All-Africa Games in 1973.', 'https://en.wikipedia.org/wiki/2003_All-Africa_Games', 'live'),
  ('b91b6977-8e9a-59b1-a10f-5d47c109e2c4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Chess master Tunde Onakoya set a Guinness record in 2024 for the longest chess marathon in which city?', '["New York","Paris","London","Lagos"]'::jsonb, 0, 3, 'He played in Times Square for about 58 hours to raise funds for children''s education.', 'https://en.wikipedia.org/wiki/Tunde_Onakoya', 'live'),
  ('91734c08-688c-592b-ba26-041b14da5de3', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian table tennis star reached the Olympic quarter-finals at Rio 2016?', '["Bode Abiodun","Aruna Quadri","Segun Toriola","Funke Oshonaike"]'::jsonb, 1, 3, 'He was the first African to reach that stage in Olympic table tennis.', 'https://en.wikipedia.org/wiki/Quadri_Aruna', 'live'),
  ('a7b905cb-2669-5331-9d33-a03fd74f8eb9', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Ahmed Musa became the first Nigerian to score in two different World Cups. Which team did he score twice against in 2018?', '["Iceland","Argentina","Bosnia","Croatia"]'::jsonb, 0, 3, 'Nigeria won that match 2–0 in Volgograd.', 'https://en.wikipedia.org/wiki/Ahmed_Musa', 'live'),
  ('855c3ecb-41fb-5d50-a7f3-5a9e5d3a0636', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria beat which team in the final of the first U-16 World Championship in 1985?', '["Italy","Brazil","West Germany","Guinea"]'::jsonb, 2, 3, 'Nigeria won the final 2–0 in Beijing.', 'https://en.wikipedia.org/wiki/1985_FIFA_U-16_World_Championship', 'live'),
  ('75ea4f6d-09f0-5679-adf5-383584ebd52c', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Kokawa is a traditional form of which sport practised in northern Nigeria?', '["Boxing","Wrestling","Horse racing","Archery"]'::jsonb, 1, 3, 'Kokawa is the Hausa name for the West African folk wrestling style known as Laamb in Senegal.', 'https://en.wikipedia.org/wiki/Lutte_Traditionnelle', 'live'),
  ('a18d0b53-b434-537b-93bd-9f50dec13606', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who coached Nigeria to the 1980 AFCON title?', '["Tiko Jelisavčić","Adegboye Onigbinde","Clemens Westerhof","Otto Glória"]'::jsonb, 3, 4, 'The Brazilian coach had led Portugal to third place at the 1966 World Cup.', 'https://en.wikipedia.org/wiki/Otto_Gl%C3%B3ria', 'live'),
  ('92d19298-bb16-5ce0-b0a6-daaa9a8aca0a', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria beat which team in the 1994 AFCON final?', '["Mali","Zambia","Ghana","Ivory Coast"]'::jsonb, 1, 4, 'Emmanuel Amunike scored both goals in a 2–1 win.', 'https://en.wikipedia.org/wiki/1994_African_Cup_of_Nations', 'live'),
  ('6a977c2e-3e05-5225-a810-045554b32511', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'How many U-17 World Cup titles have Nigeria''s Golden Eaglets won?', '["2","4","5","3"]'::jsonb, 2, 4, 'They won in 1985, 1993, 2007, 2013 and 2015.', 'https://en.wikipedia.org/wiki/Nigeria_national_under-17_football_team', 'live'),
  ('c0453f1a-aec8-5f5f-a2d2-7a82d1af7104', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria failed to qualify for the 2022 World Cup after a play-off against which country?', '["Ghana","Tunisia","Egypt","Cameroon"]'::jsonb, 0, 4, 'Ghana went through on away goals after 0–0 and 1–1 draws.', 'https://en.wikipedia.org/wiki/Nigeria_national_football_team', 'live'),
  ('96c3a22d-8d2a-568e-972e-43617e797a6e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who was the Super Eagles'' head coach at the 2023 AFCON?', '["Gernot Rohr","Finidi George","José Peseiro","Augustine Eguavoen"]'::jsonb, 2, 4, 'The Portuguese coach guided Nigeria to the final.', 'https://en.wikipedia.org/wiki/Jos%C3%A9_Peseiro', 'live'),
  ('ed379b0f-becf-5c6d-9565-c6f56ced95a3', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian was the top scorer at the 2019 AFCON?', '["Odion Ighalo","Alex Iwobi","Samuel Kalu","Ahmed Musa"]'::jsonb, 0, 4, 'Ighalo scored five goals as Nigeria finished third.', 'https://en.wikipedia.org/wiki/Odion_Ighalo', 'live'),
  ('53b23b1d-495b-5ee8-8e83-2665d00e9930', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Moshood Abiola National Stadium is in which city?', '["Lagos","Ibadan","Abuja","Uyo"]'::jsonb, 2, 4, 'It was renamed in 2019 from the National Stadium, Abuja.', 'https://en.wikipedia.org/wiki/Moshood_Abiola_National_Stadium', 'live'),
  ('76b3793f-e10c-521a-b673-76977907f2c7', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which stadium in Uyo has become the Super Eagles'' main home ground?', '["Godswill Akpabio International Stadium","Ahmadu Bello Stadium","U.J. Esuene Stadium","Teslim Balogun Stadium"]'::jsonb, 0, 4, 'It is nicknamed the ''Nest of Champions''.', 'https://en.wikipedia.org/wiki/Godswill_Akpabio_International_Stadium', 'live'),
  ('6fc39569-38c3-5296-ab25-f41f178529ee', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s first-ever Olympic medal was won in which sport?', '["Boxing","Weightlifting","Football","Athletics"]'::jsonb, 0, 4, 'Nojim Maiyegun won bronze at Tokyo 1964.', 'https://en.wikipedia.org/wiki/Nigeria_at_the_Olympics', 'live'),
  ('a4e35cc7-5858-5d2d-adc7-c33155064f13', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian goalkeeper went 1,000+ minutes without conceding in Ligue 1 for Lille?', '["Peter Rufai","Austin Ejide","Vincent Enyeama","Carl Ikeme"]'::jsonb, 2, 4, 'His 1,062-minute run in 2013–14 fell just 114 minutes short of the Ligue 1 record.', 'https://en.wikipedia.org/wiki/Vincent_Enyeama', 'live'),
  ('46158b96-345c-566e-8160-ac1671c8214b', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Taribo West played for both Inter Milan and which other Milan club?', '["AC Milan","Atalanta","Monza","Como"]'::jsonb, 0, 4, 'He was known for his colourful braided hairstyles.', 'https://en.wikipedia.org/wiki/Taribo_West', 'live'),
  ('478e55f6-dd6f-594e-bbf3-4c773a6dc4e4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Daniel Amokachi starred for which English club in the mid-1990s?', '["Leeds United","Newcastle United","Everton","Aston Villa"]'::jsonb, 2, 4, 'He scored twice in Everton''s 1995 FA Cup semi-final.', 'https://en.wikipedia.org/wiki/Daniel_Amokachi', 'live'),
  ('29556912-2a6f-5241-b5d3-9ef1ad9079d2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Jay-Jay Okocha captained which English club?', '["Portsmouth","Bolton Wanderers","Hull City","West Brom"]'::jsonb, 1, 4, 'He joined Bolton from Paris Saint-Germain in 2002.', 'https://en.wikipedia.org/wiki/Jay-Jay_Okocha', 'live'),
  ('a71ae706-ff51-5441-9acf-9dae80fde2d0', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s women''s basketball team won the AfroBasket title in 2017, 2019, 2021 and which year?', '["2015","2023","2013","2011"]'::jsonb, 1, 4, 'D''Tigress dominated African women''s basketball in that era.', 'https://en.wikipedia.org/wiki/Nigeria_women%27s_national_basketball_team', 'live'),
  ('0cd3eebc-fe9b-59e1-8a19-1b7f6ecccc49', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'At Paris 2024, D''Tigress became the first African team to reach which stage of the Olympic basketball tournament?', '["Quarter-finals","Group stage","Semi-finals","Final"]'::jsonb, 0, 4, 'They beat Australia and Canada in the group stage.', 'https://en.wikipedia.org/wiki/Nigeria_women%27s_national_basketball_team', 'live'),
  ('156ed311-c106-5d39-bfe8-c0576e7689d6', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s men''s 4x400m relay team was upgraded to gold for which Olympics?', '["Athens 2004","Sydney 2000","Atlanta 1996","Beijing 2008"]'::jsonb, 1, 4, 'The US team was later disqualified over a doping case.', 'https://en.wikipedia.org/wiki/Athletics_at_the_2000_Summer_Olympics_%E2%80%93_Men%27s_4_%C3%97_400_metres_relay', 'live'),
  ('9f48c438-5f1b-5727-9198-510c71d8b1cc', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian club won the African Cup Winners'' Cup in 1976?', '["Shooting Stars","Enyimba","Rangers International","Bendel Insurance"]'::jsonb, 0, 4, 'Shooting Stars are based in Ibadan.', 'https://en.wikipedia.org/wiki/Shooting_Stars_S.C.', 'live'),
  ('0a3590f5-2e7e-56e9-a80a-2dfa22badec0', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Rangers International FC is based in which city?', '["Aba","Onitsha","Enugu","Owerri"]'::jsonb, 2, 4, 'Rangers are nicknamed ''The Flying Antelopes''.', 'https://en.wikipedia.org/wiki/Rangers_International_F.C.', 'live'),
  ('bbbda5c1-e35b-56b1-817d-f3aefa8338cc', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Before independence, Nigeria''s national team was nicknamed what, after its red-topped kits?', '["Desert Warriors","Green Eagles","Red Devils","Lone Stars"]'::jsonb, 2, 5, 'After independence the team became the Green Eagles, then the Super Eagles from 1988.', 'https://en.wikipedia.org/wiki/Nigeria_national_football_team', 'live'),
  ('51a61ecd-8ab0-5c75-bcbb-b5b6a0bb1b6f', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Stephen Keshi and which Egyptian are the only two men to win AFCON as player and coach?', '["Mahmoud El-Gohary","Hassan Shehata","Mohamed Aboutrika","Hossam Hassan"]'::jsonb, 0, 5, 'Keshi won in 1994 as a player and 2013 as coach.', 'https://en.wikipedia.org/wiki/Stephen_Keshi', 'live'),
  ('96719847-245f-5a94-9fb5-9dcc15134f47', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'In which country did Nigeria win the inaugural U-16 world title in 1985?', '["China","Scotland","Japan","Canada"]'::jsonb, 0, 5, 'The tournament later became the U-17 World Cup.', 'https://en.wikipedia.org/wiki/1985_FIFA_U-16_World_Championship', 'live'),
  ('9f35c458-431c-5cd9-bafb-cc57897c75ab', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which city hosted the 2nd All-Africa Games in 1973?', '["Kaduna","Ibadan","Lagos","Abuja"]'::jsonb, 2, 5, 'The Games were held at the National Stadium, Surulere.', 'https://en.wikipedia.org/wiki/1973_All-Africa_Games', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('92ba4b6d-57fd-5065-9737-b86e0a864b7e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who won Nigeria''s first Olympic medal, a bronze in boxing in 1964?', '["Nojim Maiyegun","Dick Tiger","Hogan Bassey","Isaac Ikhouria"]'::jsonb, 0, 5, 'Maiyegun won bronze in the light-middleweight division in Tokyo.', 'https://en.wikipedia.org/wiki/Nojim_Maiyegun', 'live'),
  ('0dc3c85a-05e9-5c6f-b545-75ce93d1e516', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s 1996 Olympic squad included which future Chelsea defender, a teenage star then?', '["Uche Okechukwu","Joseph Yobo","Celestine Babayaro","Taribo West"]'::jsonb, 2, 5, 'Babayaro was known for his somersault celebrations.', 'https://en.wikipedia.org/wiki/Celestine_Babayaro', 'live'),
  ('4c21c2ec-f86a-5321-845b-3f78683f3ef4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who scored the golden goal against Brazil in the 1996 Olympic semi-final?', '["Tijani Babangida","Emmanuel Amunike","Nwankwo Kanu","Victor Ikpeba"]'::jsonb, 2, 5, 'Kanu had also scored Nigeria''s equaliser in the 90th minute.', 'https://en.wikipedia.org/wiki/Football_at_the_1996_Summer_Olympics', 'live'),
  ('4b506465-d1b9-5d3b-bd3a-89808ba1f80c', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s Flying Eagles reached the FIFA U-20 World Cup final in 1989 and which other year?', '["1999","2005","2011","2015"]'::jsonb, 1, 5, 'In 2005 they lost the final to an Argentina side featuring Lionel Messi.', 'https://en.wikipedia.org/wiki/Nigeria_national_under-20_football_team', 'live'),
  ('31e06b7b-f9ac-5750-a288-c702d8fc62d2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Malian-French coach was appointed Super Eagles head coach in January 2025?', '["Claude Le Roy","Paul Put","Hervé Renard","Éric Chelle"]'::jsonb, 3, 5, 'He previously coached Mali.', 'https://en.wikipedia.org/wiki/%C3%89ric_Chelle', 'live'),
  ('03cbfc35-dec2-5867-b59c-7995dc9ace30', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria hosted which FIFA youth tournament in 2009?', '["U-20 World Cup","Women''s U-20 World Cup","U-17 World Cup","Club World Cup"]'::jsonb, 2, 5, 'Nigeria reached the final but lost to Switzerland.', 'https://en.wikipedia.org/wiki/2009_FIFA_U-17_World_Cup', 'live'),
  ('3dc9adf8-e9c6-563e-89f8-7a88eab834ae', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria hosted the FIFA World Youth Championship (U-20) in which year?', '["1989","1999","1995","2003"]'::jsonb, 1, 5, 'Spain won the tournament, with matches in Lagos, Kaduna, Enugu and elsewhere.', 'https://en.wikipedia.org/wiki/1999_FIFA_World_Youth_Championship', 'live'),
  ('3065e718-5246-5648-8c8e-619bb984a75e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s first Africa Cup of Nations appearance was in which year?', '["1976","1980","1963","1957"]'::jsonb, 2, 5, 'Nigeria were knocked out in the group stage in Ghana.', 'https://en.wikipedia.org/wiki/Nigeria_national_football_team', 'live'),
  ('c274d7c3-6cef-51a9-91dd-476e30d1b228', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s U-20 men''s football team is nicknamed?', '["Green Falcons","Golden Eaglets","Dream Team","Flying Eagles"]'::jsonb, 3, 1, 'The Flying Eagles have reached two U-20 World Cup finals.', 'https://en.wikipedia.org/wiki/Nigeria_national_under-20_football_team', 'live'),
  ('bd896c41-acdc-5379-ae0a-e183d51372b0', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s men''s basketball team is nicknamed?', '["D''Tigress","Hoop Eagles","D''Tigers","Super Eagles"]'::jsonb, 2, 1, 'D''Tigers won the AfroBasket title in 2015.', 'https://en.wikipedia.org/wiki/Nigeria_men%27s_national_basketball_team', 'live'),
  ('6b4cdf56-6d60-5756-9ea7-869a004d3c23', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Victor Boniface won an unbeaten Bundesliga title in 2023–24 with which club?', '["Bayern Munich","RB Leipzig","Borussia Dortmund","Bayer Leverkusen"]'::jsonb, 3, 1, 'Leverkusen went the whole league season without a defeat.', 'https://en.wikipedia.org/wiki/Victor_Boniface', 'live'),
  ('1aaee36c-64be-5191-8344-4990712c3ccd', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Kanu Nwankwo won the Premier League and FA Cup with which London club?', '["Arsenal","Chelsea","West Ham United","Tottenham Hotspur"]'::jsonb, 0, 1, 'Kanu was part of Arsenal''s unbeaten ''Invincibles'' squad of 2003–04.', 'https://en.wikipedia.org/wiki/Nwankwo_Kanu', 'live'),
  ('bff73525-5d9f-5908-995a-0bb4e56f1aee', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which body organises the Africa Cup of Nations?', '["UEFA","FIFA","CAF","ECOWAS"]'::jsonb, 2, 1, 'CAF stands for the Confederation of African Football.', 'https://en.wikipedia.org/wiki/Confederation_of_African_Football', 'live'),
  ('a7a293e2-b4da-57c9-83cb-d7abaaefb644', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'What does NFF stand for in Nigerian football?', '["National Football Forum","Nigeria Football Federation","Nigerian Federation of Footballers","National Football Fund"]'::jsonb, 1, 1, 'The NFF runs the national teams from Abuja.', 'https://en.wikipedia.org/wiki/Nigeria_Football_Federation', 'live'),
  ('b8cbe2f8-0ee5-5634-b92b-2fd2f1af43be', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Giannis Antetokounmpo''s parents emigrated to Greece from which country?', '["Ghana","Senegal","Cameroon","Nigeria"]'::jsonb, 3, 1, 'Giannis and his brothers have Nigerian heritage through both parents.', 'https://en.wikipedia.org/wiki/Giannis_Antetokounmpo', 'live'),
  ('3de9b51d-ce27-5693-bcd9-4a2ef2ccc104', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which sport does Tunde Onakoya use to empower children in Lagos slums?', '["Football","Table tennis","Chess","Boxing"]'::jsonb, 2, 1, 'His charity is called Chess in Slums Africa.', 'https://en.wikipedia.org/wiki/Tunde_Onakoya', 'live'),
  ('d03f6266-705c-54a1-b07d-ce58008967bd', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which brand made the Super Eagles'' 2018 World Cup kit that sold out worldwide?', '["Adidas","Umbro","Nike","Puma"]'::jsonb, 2, 1, 'The green zig-zag design was a nod to the 1994 kit.', 'https://en.wikipedia.org/wiki/Nigeria_national_football_team', 'live'),
  ('44339a2b-1c90-5f4a-8000-07e5c842d487', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Wilfred Ndidi is best known for playing which position?', '["Winger","Goalkeeper","Defensive midfielder","Striker"]'::jsonb, 2, 1, 'Ndidi was known for leading the Premier League in tackles.', 'https://en.wikipedia.org/wiki/Wilfred_Ndidi', 'live'),
  ('3f778344-34fe-5d77-8765-d0c9ead264d4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'In which sport did Hakeem Olajuwon become a legend?', '["Tennis","Football","Athletics","Basketball"]'::jsonb, 3, 1, 'He grew up in Lagos and played football and handball before basketball.', 'https://en.wikipedia.org/wiki/Hakeem_Olajuwon', 'live'),
  ('952e67e6-8a1a-5c0d-a95d-0b4ec2dcd888', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Anthony Joshua lost his heavyweight titles in a 2019 upset to which boxer?', '["Tyson Fury","Andy Ruiz Jr.","Oleksandr Usyk","Deontay Wilder"]'::jsonb, 1, 1, 'Joshua won the rematch six months later in Saudi Arabia.', 'https://en.wikipedia.org/wiki/Anthony_Joshua', 'live'),
  ('c1a8b897-c2b6-5f96-8f42-e50546556245', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian striker was famous for celebrating goals with somersaults?', '["Rashidi Yekini","Victor Osimhen","Obafemi Martins","Odion Ighalo"]'::jsonb, 2, 1, 'Martins burst onto the scene as a teenager at Inter Milan.', 'https://en.wikipedia.org/wiki/Obafemi_Martins', 'live'),
  ('f2068407-eaa1-5514-8d5e-f33ad8cda28d', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian player is famous for the ''Jay-Jay'' flicks and stepovers at Bolton and PSG?', '["Taribo West","Sunday Oliseh","Finidi George","Augustine Okocha"]'::jsonb, 3, 1, 'Bolton fans sang that he was ''so good they named him twice''.', 'https://en.wikipedia.org/wiki/Jay-Jay_Okocha', 'live'),
  ('4f97ec77-9565-5676-8c1d-4fd0e6b146ab', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'How do D''Tigers fans remember July 2021 in Las Vegas?', '["Nigeria won the World Cup","Nigeria won the Olympics","Nigeria beat the USA in an exhibition","Nigeria hosted the NBA finals"]'::jsonb, 2, 1, 'D''Tigers won 90–87 against Team USA before the Tokyo Olympics.', 'https://en.wikipedia.org/wiki/Nigeria_men%27s_national_basketball_team', 'live'),
  ('7e7a7b7a-4597-531d-945f-707231344155', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'The CHAN tournament is only open to players who play in…', '["Beach football","Their own country''s league","European leagues","Under-17 teams"]'::jsonb, 1, 1, 'CHAN stands for the African Nations Championship.', 'https://en.wikipedia.org/wiki/African_Nations_Championship', 'live'),
  ('4398c569-6002-5805-8181-ed8c82efbb0a', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Chiamaka Nnadozie plays which position for the Super Falcons?', '["Winger","Goalkeeper","Centre-back","Striker"]'::jsonb, 1, 1, 'She saved a penalty from Canada''s Christine Sinclair at the 2023 World Cup.', 'https://en.wikipedia.org/wiki/Chiamaka_Nnadozie', 'live'),
  ('1232d7a5-acce-5c6e-8703-b07958d4f709', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Tobi Amusan races in which event?', '["Marathon","Shot put","100m hurdles","High jump"]'::jsonb, 2, 1, 'She became world champion and world record holder on the same weekend in 2022.', 'https://en.wikipedia.org/wiki/Tobi_Amusan', 'live'),
  ('9b70753c-fe74-5769-a7f2-7ea5e72b09ea', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian striker scored Atalanta''s three goals in the 2024 Europa League final?', '["Taiwo Awoniyi","Ademola Lookman","Victor Boniface","Moses Simon"]'::jsonb, 1, 1, 'It was the first hat-trick in a Europa League final since 1975.', 'https://en.wikipedia.org/wiki/2024_UEFA_Europa_League_final', 'live'),
  ('afa55e12-9716-591e-93ca-41d29136fa99', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who coached Nigeria at the 2018 World Cup?', '["Sunday Oliseh","Stephen Keshi","Samson Siasia","Gernot Rohr"]'::jsonb, 3, 2, 'Rohr, a German, was in charge from 2016 to 2021.', 'https://en.wikipedia.org/wiki/Gernot_Rohr', 'live'),
  ('d1afecf3-e2aa-5b0c-a1e6-7034788e5e02', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who coached Nigeria at the 2014 World Cup?', '["Stephen Keshi","Lars Lagerbäck","Berti Vogts","Gernot Rohr"]'::jsonb, 0, 2, 'Keshi led Nigeria to the round of 16 in Brazil.', 'https://en.wikipedia.org/wiki/Stephen_Keshi', 'live'),
