  ('78132a63-3a77-5812-86fd-eca4adf3706b', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria went out of the 2018 World Cup after a 2–1 group-stage defeat to which team?', '["Argentina","Iceland","Brazil","Croatia"]'::jsonb, 0, 2, 'A late Marcos Rojo goal sent Argentina through instead.', 'https://en.wikipedia.org/wiki/2018_FIFA_World_Cup_Group_D', 'live'),
  ('5bd7ce78-f4be-5782-a100-ce6c5336b8ba', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which country beat Nigeria in the 2019 AFCON semi-final with a last-minute Riyad Mahrez free-kick?', '["Algeria","Tunisia","Egypt","Senegal"]'::jsonb, 0, 2, 'Algeria went on to win the tournament.', 'https://en.wikipedia.org/wiki/2019_Africa_Cup_of_Nations', 'live'),
  ('35242cc1-7131-5667-aee3-6904ae50f4a1', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria co-hosted the 2000 Africa Cup of Nations with which country?', '["Togo","Cameroon","Ghana","Benin"]'::jsonb, 2, 2, 'It was the first AFCON with two host nations.', 'https://en.wikipedia.org/wiki/2000_African_Cup_of_Nations', 'live'),
  ('4d30170d-140e-5a44-890d-322562884deb', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian won African Footballer of the Year in both 1996 and 1999?', '["Jay-Jay Okocha","Rashidi Yekini","Nwankwo Kanu","Victor Ikpeba"]'::jsonb, 2, 2, 'Kanu also won Olympic gold as captain in 1996.', 'https://en.wikipedia.org/wiki/African_Footballer_of_the_Year', 'live'),
