  ('3487e23f-fbd8-59c7-b062-9c0c4aa67824', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Jay-Jay Okocha played for which French club?', '["Paris Saint-Germain","Lyon","Monaco","Marseille"]'::jsonb, 0, 2, 'PSG paid a then-record fee for an African player to sign him in 1998.', 'https://en.wikipedia.org/wiki/Jay-Jay_Okocha', 'live'),
  ('6ae3cad9-3fdf-53a4-8030-376d65742a15', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Kelechi Iheanacho began his European career at which club?', '["Arsenal","Leicester City","Manchester City","Porto"]'::jsonb, 2, 2, 'He joined City after starring at the 2013 U-17 World Cup.', 'https://en.wikipedia.org/wiki/Kelechi_Iheanacho', 'live'),
