  ('9c3ae71e-a562-5648-bb63-d87aa5a88a7b', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Samuel Chukwueze moved to AC Milan in 2023 from which Spanish club?', '["Valencia","Real Betis","Villarreal","Sevilla"]'::jsonb, 2, 2, 'He won the Europa League with Villarreal in 2021.', 'https://en.wikipedia.org/wiki/Samuel_Chukwueze', 'live'),
  ('93a09fa2-e2d1-5e6e-ae94-722419e4ca41', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'In which year did Tobi Amusan become 100m hurdles world champion?', '["2019","2023","2021","2022"]'::jsonb, 3, 2, 'She won in Eugene, Oregon, setting a world record in the semi-final.', 'https://en.wikipedia.org/wiki/Tobi_Amusan', 'live'),
