  ('2f63eec7-e899-5371-bf3e-9a1e5cc1dbe2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Teslim Balogun Stadium is in which city?', '["Lagos","Port Harcourt","Ibadan","Abeokuta"]'::jsonb, 0, 2, 'It sits beside the National Stadium in Surulere.', 'https://en.wikipedia.org/wiki/Teslim_Balogun_Stadium', 'live'),
