  ('5a189100-6e66-5b82-a548-403287743eee', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nwankwo Kanu set up a foundation after surviving which health problem?', '["Malaria","A broken leg","A heart defect","A knee injury"]'::jsonb, 2, 2, 'The Kanu Heart Foundation funds heart surgery for children.', 'https://en.wikipedia.org/wiki/Nwankwo_Kanu', 'live'),
  ('04c81470-faa9-5468-8e4d-b4057fe100ea', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Nigerian sprinter won both the 100m and 200m at the 2014 Commonwealth Games?', '["Mary Onyali","Favour Ofili","Blessing Okagbare","Tobi Amusan"]'::jsonb, 2, 2, 'She set a Games record of 10.85s in the 100m in Glasgow.', 'https://en.wikipedia.org/wiki/Blessing_Okagbare', 'live'),
  ('c42b7d1b-fe3f-5904-868f-809462bd29c4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'D''Tigress beat which team in their opening game at the Paris 2024 Olympics?', '["USA","France","Australia","Japan"]'::jsonb, 2, 2, 'It was one of the biggest upsets of the tournament.', 'https://en.wikipedia.org/wiki/Nigeria_women%27s_national_basketball_team', 'live'),
  ('b2e3ef15-82a8-564e-abb8-18bf577133f4', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Odion Ighalo spent a loan spell at Manchester United. Which club was he signed from?', '["Al-Shabab","Granada","Shanghai Shenhua","Watford"]'::jsonb, 2, 2, 'He had supported United since childhood.', 'https://en.wikipedia.org/wiki/Odion_Ighalo', 'live'),
  ('081d7a05-31f5-5baf-be89-561b9dc47791', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s first-ever World Cup match, in 1994, was a 3–0 win over which team?', '["Bulgaria","Italy","Argentina","Greece"]'::jsonb, 0, 3, 'Rashidi Yekini, Daniel Amokachi and Emmanuel Amunike scored.', 'https://en.wikipedia.org/wiki/1994_FIFA_World_Cup', 'live'),
