  ('5d219297-f60f-5d5b-a81f-b5c05d1f3d6a', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who captained Nigeria at the 1994 World Cup?', '["Stephen Keshi","Uche Okechukwu","Rashidi Yekini","Peter Rufai"]'::jsonb, 0, 3, 'Keshi later won AFCON as Nigeria''s coach in 2013.', 'https://en.wikipedia.org/wiki/Stephen_Keshi', 'live'),
  ('72e1b2da-301c-5541-964f-38276f1f4bdd', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who was Nigeria''s goalkeeper at the 1994 World Cup?', '["Ike Shorunmu","Wilfred Agbonavbare","Peter Rufai","Vincent Enyeama"]'::jsonb, 2, 3, 'Rufai was nicknamed ''Dodo Mayana''.', 'https://en.wikipedia.org/wiki/Peter_Rufai', 'live'),
  ('b7b9a0a3-0b8d-5385-8c76-df3995d394fc', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who coached Nigeria at the 1998 World Cup?', '["Jo Bonfrere","Philippe Troussier","Clemens Westerhof","Bora Milutinović"]'::jsonb, 3, 3, 'The Serbian coach took five different nations to World Cups.', 'https://en.wikipedia.org/wiki/Bora_Milutinovi%C4%87', 'live'),
  ('3a0e1a57-0dbe-5dda-8459-ad3cdaa26db6', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria lost 4–1 to which team in the round of 16 of the 1998 World Cup?', '["France","Brazil","Denmark","Paraguay"]'::jsonb, 2, 3, 'Nigeria had topped a group that included Spain.', 'https://en.wikipedia.org/wiki/1998_FIFA_World_Cup', 'live'),
  ('e3f3fb5a-efe1-585c-88a1-be45928d8b11', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who coached Nigeria at the 2010 World Cup?', '["Stephen Keshi","Shaibu Amodu","Lars Lagerbäck","Berti Vogts"]'::jsonb, 2, 3, 'The Swede was appointed only months before the tournament.', 'https://en.wikipedia.org/wiki/Lars_Lagerb%C3%A4ck', 'live'),
  ('119ded7a-8e3d-50f3-b320-ae9b977b056d', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Yakubu Aiyegbeni''s famous open-goal miss at the 2010 World Cup came against which team?', '["Argentina","Ghana","South Korea","Greece"]'::jsonb, 2, 3, 'He scored a penalty in the same game, which ended 2–2.', 'https://en.wikipedia.org/wiki/Yakubu_(footballer)', 'live'),
  ('5e0c3935-e47b-5802-a646-c2b40eb75459', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'At the 2002 World Cup, Nigeria''s only point came from a 0–0 draw with which team?', '["England","Sweden","Paraguay","Argentina"]'::jsonb, 0, 3, 'The game was played in Osaka, Japan.', 'https://en.wikipedia.org/wiki/2002_FIFA_World_Cup_Group_F', 'live'),
  ('f2758dde-4307-5502-9419-7d496c33b4e2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s 2018 World Cup group contained Argentina, Iceland and which other team?', '["France","Peru","Denmark","Croatia"]'::jsonb, 3, 3, 'Croatia went on to reach the final.', 'https://en.wikipedia.org/wiki/2018_FIFA_World_Cup_Group_D', 'live'),
  ('ffbcfbb1-c91c-5787-b5f5-88d70f035797', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'How many FIFA World Cups did Nigeria play at between 1994 and 2018?', '["6","4","5","7"]'::jsonb, 0, 3, 'Nigeria missed only the 2006 edition in that period.', 'https://en.wikipedia.org/wiki/Nigeria_at_the_FIFA_World_Cup', 'live'),
  ('0854629f-2392-581b-b353-84076f789abf', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria finished third at the 2019 AFCON by beating which team?', '["Tunisia","Ivory Coast","Madagascar","Senegal"]'::jsonb, 0, 3, 'Odion Ighalo scored the only goal.', 'https://en.wikipedia.org/wiki/2019_Africa_Cup_of_Nations', 'live'),
  ('60f59dc4-2bbf-5ade-9b17-b088248f687a', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who scored Nigeria''s goal in the 2023 AFCON final?', '["Ademola Lookman","Victor Osimhen","William Troost-Ekong","Moses Simon"]'::jsonb, 2, 3, 'Ivory Coast came back to win 2–1.', 'https://en.wikipedia.org/wiki/2023_Africa_Cup_of_Nations_final', 'live'),
  ('c1c78036-af26-5b48-89ac-512f5d93aeca', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'The 2023 Africa Cup of Nations, where Nigeria finished runners-up, was played in which year?', '["2025","2022","2024","2023"]'::jsonb, 2, 3, 'It was moved to January–February 2024 to avoid Ivory Coast''s rainy season.', 'https://en.wikipedia.org/wiki/2023_Africa_Cup_of_Nations', 'live'),
  ('0cd7dbcc-2ce0-5463-a5df-16528594656d', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria lost the 2000 AFCON final on penalties to which team?', '["Egypt","Senegal","Ghana","Cameroon"]'::jsonb, 3, 3, 'The final was played in Lagos.', 'https://en.wikipedia.org/wiki/2000_African_Cup_of_Nations', 'live'),
  ('857c0fb1-e1f4-5e5a-bac8-efa9fff1eae9', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Rashidi Yekini was African Footballer of the Year in which year?', '["1996","1999","1989","1993"]'::jsonb, 3, 3, 'He was the top scorer at the 1994 AFCON.', 'https://en.wikipedia.org/wiki/Rashidi_Yekini', 'live'),
