  ('08d5e526-2015-5955-92ea-7de243cf5311', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Rangers International FC is nicknamed?', '["The Flying Antelopes","The People''s Elephant","The Oluyole Warriors","Sai Masu Gida"]'::jsonb, 0, 3, 'Rangers are one of the most popular clubs in eastern Nigeria.', 'https://en.wikipedia.org/wiki/Rangers_International_F.C.', 'live'),
  ('4be50bc9-6567-5a77-a1b5-b599c5b2ca9b', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Kano Pillars play home matches at which stadium?', '["Teslim Balogun Stadium","Liberation Stadium","Sani Abacha Stadium","Ahmadu Bello Stadium"]'::jsonb, 2, 3, 'The stadium is in Kano''s Kofar Mata area.', 'https://en.wikipedia.org/wiki/Kano_Pillars_F.C.', 'live'),
  ('45fa8f98-b64c-5c2a-96d2-1add0bc1a098', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Lagos stadium, opened in 1972, hosted the 1973 All-Africa Games?', '["Agege Stadium","Onikan Stadium","Teslim Balogun Stadium","National Stadium, Surulere"]'::jsonb, 3, 3, 'It hosted Nigeria''s 1980 AFCON triumph too.', 'https://en.wikipedia.org/wiki/National_Stadium,_Lagos', 'live'),
  ('a28a7ccc-fec5-549a-acb0-9a39ab2f4b51', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'The Liberation Stadium is in which city?', '["Uyo","Calabar","Warri","Port Harcourt"]'::jsonb, 3, 3, 'It was formerly known as the Yakubu Gowon Stadium.', 'https://en.wikipedia.org/wiki/Liberation_Stadium', 'in_review'),
  ('684495c6-8fbd-54db-8379-1c0fd54dcf1a', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Super Falcons'' best-ever Women''s World Cup finish was reaching which round in 1999?', '["Semi-finals","Quarter-finals","Final","Round of 16"]'::jsonb, 1, 3, 'They lost 4–3 to Brazil after extra time.', 'https://en.wikipedia.org/wiki/Nigeria_women%27s_national_football_team', 'live'),
