  ('3fbb6b57-05c3-5c27-af44-be83b084920f', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Anthony Joshua won Olympic gold in 2012 in which weight class?', '["Heavyweight","Light heavyweight","Super heavyweight","Cruiserweight"]'::jsonb, 2, 3, 'He won the final in London on a countback.', 'https://en.wikipedia.org/wiki/Anthony_Joshua', 'live'),
  ('615d58dd-67cf-53b5-bd3d-d6f4a28a1023', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Kamaru Usman was born in which Nigerian town?', '["Kano","Lokoja","Auchi","Benin City"]'::jsonb, 2, 3, 'He moved to the United States at the age of eight.', 'https://en.wikipedia.org/wiki/Kamaru_Usman', 'live'),
  ('1161b100-0d62-5cb9-97df-a47ab1b12ad8', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Hakeem Olajuwon was the first pick of which NBA draft?', '["1984","1988","1992","1980"]'::jsonb, 0, 3, 'Michael Jordan was picked third in the same draft.', 'https://en.wikipedia.org/wiki/1984_NBA_draft', 'live'),
  ('5669f11a-f84f-5ba1-801b-031be402e55b', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s women made Olympic history at PyeongChang 2018 as Africa''s first team in which sport?', '["Ice hockey","Figure skating","Curling","Bobsleigh"]'::jsonb, 3, 3, 'The team was led by pilot Seun Adigun.', 'https://en.wikipedia.org/wiki/Nigeria_at_the_2018_Winter_Olympics', 'live'),
  ('004f7126-f610-5797-8f4b-3897166e1fc5', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'In which Paralympic sport has Nigeria won the most medals?', '["Archery","Powerlifting","Wheelchair basketball","Swimming"]'::jsonb, 1, 3, 'Nigerian powerlifters have set several world records.', 'https://en.wikipedia.org/wiki/Nigeria_at_the_Paralympics', 'live'),
  ('75685fc6-7a6b-5feb-a649-4a9431eb521a', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Francis Obikwelu won Olympic 100m silver in 2004 representing which country?', '["Great Britain","Spain","Portugal","Nigeria"]'::jsonb, 2, 3, 'Born in Onitsha, he earlier won a world bronze for Nigeria.', 'https://en.wikipedia.org/wiki/Francis_Obikwelu', 'live'),
  ('8d1ad0a2-0aea-5dc6-a69d-5329712deb32', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Ese Brume won World Championship silver in 2022 in which event?', '["Triple jump","Long jump","Discus","100m"]'::jsonb, 1, 3, 'She had earlier won world bronze in 2019.', 'https://en.wikipedia.org/wiki/Ese_Brume', 'live'),
  ('48462ba5-0604-5f4b-ae91-83cbcf33c440', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which club has won the most Nigerian league titles?', '["Enyimba","Rangers International","Shooting Stars","Kano Pillars"]'::jsonb, 0, 3, 'Enyimba also won back-to-back CAF Champions League titles.', 'https://en.wikipedia.org/wiki/Enyimba_F.C.', 'in_review'),
  ('b62c3f0b-23c9-5b33-8192-a9d689d79982', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who is the most-capped player in Super Eagles history?', '["Vincent Enyeama","Ahmed Musa","Mikel John Obi","Joseph Yobo"]'::jsonb, 1, 3, 'Musa passed Enyeama''s record of 101 caps.', 'https://en.wikipedia.org/wiki/Ahmed_Musa', 'in_review'),
  ('9dd98c94-cdef-5abd-ae89-4415839c0f6e', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who coached Nigeria at the 2002 World Cup?', '["Christian Chukwu","Festus Onigbinde","Bora Milutinović","Shaibu Amodu"]'::jsonb, 1, 4, 'Onigbinde also coached Nigeria to the 1984 AFCON final.', 'https://en.wikipedia.org/wiki/Festus_Onigbinde', 'live'),
  ('4e89f6ee-94b9-577f-a539-d69079149ad7', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Argentine defender scored the late winner that knocked Nigeria out of the 2018 World Cup?', '["Marcos Rojo","Gabriel Mercado","Javier Mascherano","Nicolás Otamendi"]'::jsonb, 0, 4, 'Lionel Messi had opened the scoring.', 'https://en.wikipedia.org/wiki/Marcos_Rojo', 'live'),
