  ('44e43d99-689c-5bff-ad82-189d47f0fbcb', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Who scored Nigeria''s goal in their 1994 World Cup round-of-16 defeat to Italy?', '["Finidi George","Daniel Amokachi","Rashidi Yekini","Emmanuel Amunike"]'::jsonb, 3, 4, 'Nigeria were minutes away from the quarter-finals.', 'https://en.wikipedia.org/wiki/1994_FIFA_World_Cup_knockout_stage', 'live'),
  ('017589e5-863b-5e09-82f6-80af80befb0b', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Super Eagle was sent off for kicking a Greek player at the 2010 World Cup?', '["Sani Kaita","John Utaka","Dickson Etuhu","Taye Taiwo"]'::jsonb, 0, 4, 'Greece came from behind to win 2–1.', 'https://en.wikipedia.org/wiki/Sani_Kaita', 'live'),
  ('8de7e21d-8328-5edb-8886-3fc9e1512586', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria''s 2014 World Cup group contained Argentina, Iran and which other team?', '["Bosnia and Herzegovina","Greece","South Korea","Croatia"]'::jsonb, 0, 4, 'Nigeria beat Bosnia 1–0 in Cuiabá.', 'https://en.wikipedia.org/wiki/2014_FIFA_World_Cup_Group_F', 'live'),
  ('f3b4fc98-e3a4-58a2-b6eb-3266cce5c0b2', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Emmanuel Amunike was African Footballer of the Year in which year?', '["2000","1994","1990","1997"]'::jsonb, 1, 4, 'He scored twice in the 1994 AFCON final.', 'https://en.wikipedia.org/wiki/Emmanuel_Amunike', 'live'),
