  ('7ee16f24-432b-53e7-8c51-8bf2e7cabcfb', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Jay-Jay Okocha scored a famous dribbling goal past Oliver Kahn while playing for which club?', '["PSG","Eintracht Frankfurt","Fenerbahçe","Bolton Wanderers"]'::jsonb, 1, 4, 'The 1993 goal against Karlsruhe is a Bundesliga classic.', 'https://en.wikipedia.org/wiki/Jay-Jay_Okocha', 'live'),
