  ('762bf702-98d7-548d-a3a1-63e5a2e50bad', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Victor Osimhen got his first European move to which German club?', '["Schalke 04","VfL Wolfsburg","Hertha Berlin","Bayer Leverkusen"]'::jsonb, 1, 4, 'He went on loan to Charleroi in Belgium before joining Lille.', 'https://en.wikipedia.org/wiki/Victor_Osimhen', 'live'),
  ('c0f94a7a-4e50-531f-bbe0-5f0d5d76141d', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Emmanuel Emenike was joint top scorer at which Africa Cup of Nations?', '["2010","2013","2006","2019"]'::jsonb, 1, 4, 'He scored four goals as Nigeria won the title.', 'https://en.wikipedia.org/wiki/2013_Africa_Cup_of_Nations', 'live'),
  ('029faf60-0ece-5f64-8b6b-3c89e0f4aedb', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Nigeria withdrew from the 1996 AFCON, which was hosted by which country?', '["Burkina Faso","South Africa","Ghana","Egypt"]'::jsonb, 1, 4, 'Nigeria had won the previous edition in 1994.', 'https://en.wikipedia.org/wiki/1996_African_Cup_of_Nations', 'live'),
  ('44420999-1c8c-5122-9c50-04f5ceaf345f', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which team beat Nigeria in the 1984 and 1988 AFCON finals?', '["Algeria","Cameroon","Egypt","Ghana"]'::jsonb, 1, 4, 'Cameroon also beat Nigeria in the 2000 final.', 'https://en.wikipedia.org/wiki/Cameroon_national_football_team', 'live')
