  ('84406471-29a6-531b-83c5-3f217dad6710', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Which Kansas City Chiefs running back was nicknamed ''The Nigerian Nightmare''?', '["Christian Okoye","Amobi Okoye","Osi Umenyiora","Ezekiel Ansah"]'::jsonb, 0, 4, 'Okoye led the NFL in rushing yards in 1989.', 'https://en.wikipedia.org/wiki/Christian_Okoye', 'live'),
  ('764310b5-680b-5cad-b52e-b3105d39ebff', 'b7588822-cdfa-56d9-97ab-7b3ff22ebc14', 'Gidigbo is a traditional Yoruba form of which sport?', '["Archery","Boxing","Canoe racing","Wrestling"]'::jsonb, 3, 4, 'Gidigbo bouts test strength and balance.', 'https://en.wikipedia.org/wiki/Gidigbo', 'in_review'),
