  ('ba0b2ceb-eb44-52c8-92fe-4e67b441d1b9', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Whose portrait appears on the ₦20 note?', '["Abubakar Tafawa Balewa","Yakubu Gowon","Murtala Mohammed","Alvan Ikoku"]'::jsonb, 2, 2, 'The ₦20 was Nigeria''s first polymer banknote, in 2007.', 'https://en.wikipedia.org/wiki/Nigerian_naira', 'live'),
