  ('15d9d2e9-7baa-5c06-943b-c5f0c383b9a1', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'What was the first capital of Biafra?', '["Umuahia","Owerri","Onitsha","Enugu"]'::jsonb, 3, 3, 'Enugu fell to federal troops in October 1967.', 'https://en.wikipedia.org/wiki/Republic_of_Biafra', 'live'),
  ('15afd934-1541-5c24-af32-156722230c41', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'In which country was the 1967 Aburi Accord signed?', '["Togo","Benin","Ghana","Nigeria"]'::jsonb, 2, 3, 'Aburi is near Accra.', 'https://en.wikipedia.org/wiki/Aburi_Accord', 'live'),
  ('f9e6fec4-9fa0-5223-9546-4f3f70fdf75c', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'ECOWAS was founded in 1975 by a treaty signed in which city?', '["Lagos","Dakar","Abuja","Accra"]'::jsonb, 0, 3, 'Nigeria''s Yakubu Gowon was a driving force behind it.', 'https://en.wikipedia.org/wiki/Economic_Community_of_West_African_States', 'live'),
  ('15efdd7c-bb37-56cc-8eb2-4719d2ad1f02', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'In which year did Nigeria join the United Nations?', '["1963","1960","1958","1966"]'::jsonb, 1, 3, 'Nigeria joined days after independence.', 'https://en.wikipedia.org/wiki/Member_states_of_the_United_Nations', 'live'),
  ('688a946d-02f2-598b-9a0c-033351bf899b', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was the first civilian governor of Lagos State (1979)?', '["Mobolaji Johnson","Bola Tinubu","Lateef Jakande","Michael Otedola"]'::jsonb, 2, 3, 'Jakande built many low-cost housing estates.', 'https://en.wikipedia.org/wiki/Lateef_Jakande', 'live'),
  ('92152db7-aeba-5b64-a1f9-c2dd6a0d2193', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was Lagos State''s first military governor?', '["Lateef Jakande","Raji Rasaki","Mobolaji Johnson","Buba Marwa"]'::jsonb, 2, 3, 'Lagos State was created in 1967.', 'https://en.wikipedia.org/wiki/Mobolaji_Johnson', 'live'),
  ('b3658da8-271e-58b7-a4cb-3ca88d297cfa', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which Western Region leader introduced free primary education in 1955?', '["Samuel Akintola","Herbert Macaulay","Nnamdi Azikiwe","Obafemi Awolowo"]'::jsonb, 3, 3, 'It was one of the first such schemes in Africa.', 'https://en.wikipedia.org/wiki/Obafemi_Awolowo', 'live'),
  ('b88f93af-50e7-559b-bab1-a24ccb694657', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'The University of Nigeria, Nsukka was founded in 1960 by?', '["Michael Okpara","Obafemi Awolowo","Nnamdi Azikiwe","Ahmadu Bello"]'::jsonb, 2, 3, 'Its motto is ''To restore the dignity of man''.', 'https://en.wikipedia.org/wiki/University_of_Nigeria,_Nsukka', 'live'),
  ('7da5349f-5429-5888-bde3-4956126a02f3', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Nigeria''s Second Republic lasted from 1979 to which year?', '["1983","1987","1985","1981"]'::jsonb, 0, 3, 'It ended with a military coup on 31 December 1983.', 'https://en.wikipedia.org/wiki/Second_Nigerian_Republic', 'live'),
  ('8475362b-dbc3-5930-be14-38fcb98c151e', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'The 2012 ''Occupy Nigeria'' protests were sparked by what?', '["A rigged election","Removal of the fuel subsidy","A new tax on phones","Police brutality"]'::jsonb, 1, 3, 'Petrol prices more than doubled overnight on 1 January 2012.', 'https://en.wikipedia.org/wiki/Occupy_Nigeria', 'live'),
  ('9777a5b3-f405-565a-bf3f-d4f5a1f6c990', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which Wole Soyinka book recounts his detention during the civil war?', '["Aké","The Interpreters","The Man Died","Season of Anomy"]'::jsonb, 2, 3, 'He was held for about two years, mostly in solitary confinement.', 'https://en.wikipedia.org/wiki/The_Man_Died', 'live')
