  ('b216653a-4e3c-5cc4-b19c-d4cb00607a50', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'The eagle on Nigeria''s coat of arms represents what?', '["Agriculture","Unity","Peace","Strength"]'::jsonb, 3, 3, 'The eagle is red and stands on the shield.', 'https://en.wikipedia.org/wiki/Coat_of_arms_of_Nigeria', 'live'),
  ('2663e7b9-306e-5970-ad1f-d391153fd8c7', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which head of state was the first African military ruler to hand power to an elected government, in 1979?', '["Yakubu Gowon","Olusegun Obasanjo","Murtala Mohammed","Ibrahim Babangida"]'::jsonb, 1, 3, 'He handed over to President Shehu Shagari.', 'https://en.wikipedia.org/wiki/Olusegun_Obasanjo', 'live'),
  ('3a63eb01-6838-5046-b58d-d56fc75e348e', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Nigeria''s Chibok is a town in which state?', '["Borno","Gombe","Adamawa","Yobe"]'::jsonb, 0, 3, 'Some of the girls are still missing.', 'https://en.wikipedia.org/wiki/Chibok', 'live'),
