  ('5a96503a-d870-565c-9b67-8af736163cfa', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Dele Giwa co-founded which magazine?', '["Newswatch","Tell","The News","Tempo"]'::jsonb, 0, 4, 'Newswatch was launched in 1984.', 'https://en.wikipedia.org/wiki/Newswatch_(Nigeria)', 'live'),
  ('97919633-6bfe-510d-a280-b13a9e15def1', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Kudirat Abiola, pro-democracy activist and wife of M.K.O. Abiola, was assassinated in which year?', '["1998","1999","1993","1996"]'::jsonb, 3, 4, 'The Kudirat Initiative for Democracy is named after her.', 'https://en.wikipedia.org/wiki/Kudirat_Abiola', 'live'),
  ('7d3d0438-7aef-55f2-89ad-365824ba4693', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was Nigeria''s first female Speaker of the House of Representatives?', '["Florence Ita-Giwa","Margaret Ekpo","Oby Ezekwesili","Patricia Etteh"]'::jsonb, 3, 4, 'She served in 2007.', 'https://en.wikipedia.org/wiki/Patricia_Etteh', 'live'),
