  ('a12aaa09-6dd6-50ba-81a3-4c1a3bcfffd0', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was the first Nigerian Chief Justice of Nigeria?', '["Adetokunbo Ademola","Taslim Elias","Louis Mbanefo","Atanda Fatayi-Williams"]'::jsonb, 0, 4, 'He served from 1958 to 1972.', 'https://en.wikipedia.org/wiki/Adetokunbo_Ademola', 'live'),
