  ('311df77c-8675-5bef-ab8a-d008d18d4b6e', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'What did NCNC originally stand for?', '["Nigerian Congress of National Citizens","Northern and Central Nigeria Council","National Council of Nigeria and the Cameroons","National Convention of Nigerian Citizens"]'::jsonb, 2, 4, 'It later became the National Convention of Nigerian Citizens.', 'https://en.wikipedia.org/wiki/National_Council_of_Nigeria_and_the_Cameroons', 'live'),
  ('81700ca5-12e4-5982-8313-6b5015659368', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Shehu Shagari''s agricultural programme was called?', '["Better Life","Green Revolution","Anchor Borrowers","Operation Feed the Nation"]'::jsonb, 1, 4, 'It aimed at self-sufficiency in food.', 'https://en.wikipedia.org/wiki/Shehu_Shagari', 'live'),
