  ('eb39ef7a-f794-5aea-9ee6-a4476e07df9d', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'According to tradition, who founded the Oyo Empire?', '["Oduduwa","Sango","Afonja","Oranmiyan"]'::jsonb, 3, 4, 'He was a prince of Ile-Ife.', 'https://en.wikipedia.org/wiki/Oranmiyan', 'live'),
