  ('9d7fa31e-274e-5ff5-8d66-fbed323b02ea', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who reigned as Alaafin of Oyo from 1970 until his death in 2022?', '["Ado Bayero","Lamidi Adeyemi III","Ewuare II","Oba Okunade Sijuwade"]'::jsonb, 1, 4, 'He was one of Nigeria''s longest-reigning monarchs.', 'https://en.wikipedia.org/wiki/Lamidi_Adeyemi_III', 'live'),
  ('a8f81d7d-3ee8-5229-94f1-4e67f80337bf', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Armed Forces Remembrance Day is marked on 15 January because…', '["The army was founded then","The first coup happened then","The civil war ended on that date in 1970","Independence was declared then"]'::jsonb, 2, 4, 'It was originally held on 11 November, Armistice Day.', 'https://en.wikipedia.org/wiki/Armed_Forces_Remembrance_Day_(Nigeria)', 'live'),
