  ('7426a9fb-3a86-5683-85dd-aef042693cd0', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'The Lekki Toll Gate shooting during the #EndSARS protests took place on which date?', '["1 October 2020","12 June 2020","20 October 2020","29 May 2020"]'::jsonb, 2, 4, 'A Lagos judicial panel later investigated the shooting.', 'https://en.wikipedia.org/wiki/Lekki_massacre', 'live'),
  ('7edc5bfa-0a0d-5ee5-ada4-9c9f1571c9e4', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which Nigerian leader was a driving force behind founding ECOWAS?', '["Yakubu Gowon","Olusegun Obasanjo","Murtala Mohammed","Shehu Shagari"]'::jsonb, 0, 4, 'Togo''s Gnassingbé Eyadéma was his partner in the effort.', 'https://en.wikipedia.org/wiki/Yakubu_Gowon', 'live'),
  ('9f1dee10-d767-5156-85e3-809030232706', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'The redesigned naira notes of late 2022 were the ₦200, ₦500 and which other note?', '["₦50","₦1,000","₦20","₦100"]'::jsonb, 1, 4, 'The swap caused a cash shortage in early 2023.', 'https://en.wikipedia.org/wiki/2022%E2%80%932023_Nigerian_naira_redesign', 'live'),
  ('76dddc70-a02d-5731-9a86-b35b0f758a93', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which Nigerian was President of the UN General Assembly in 1989–90?', '["Emeka Anyaoku","Tijjani Muhammad-Bande","Joseph Nanven Garba","Ibrahim Gambari"]'::jsonb, 2, 5, 'Garba had earlier been Nigeria''s foreign minister.', 'https://en.wikipedia.org/wiki/Joseph_Nanven_Garba', 'live'),
  ('e7b5bcd7-94bb-5043-98c8-8e9de3f3eda6', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which airstrip was Biafra''s main lifeline for relief flights?', '["Owerri","Port Harcourt","Enugu","Uli"]'::jsonb, 3, 5, 'Relief planes landed on a stretch of road at night.', 'https://en.wikipedia.org/wiki/Uli_airstrip', 'live'),
