  ('d33fd7ca-0617-5ebc-a459-378f03b1284a', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who composed the music of ''Nigeria, We Hail Thee''?', '["Lillian Jean Williams","Benedict Odiase","Fela Sowande","Frances Berda"]'::jsonb, 3, 5, 'Lillian Jean Williams wrote the lyrics.', 'https://en.wikipedia.org/wiki/Nigeria,_We_Hail_Thee', 'live'),
  ('43a2726f-b05d-5058-91da-959c9f65dadd', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'In which year was the Colony of Lagos merged into the Southern Nigeria Protectorate?', '["1900","1906","1861","1914"]'::jsonb, 1, 5, 'The North and South were joined eight years later.', 'https://en.wikipedia.org/wiki/Southern_Nigeria_Protectorate', 'live'),
  ('078bffee-29e9-5ab1-b809-230e68d3a131', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was the Biafran leader who surrendered to the federal government in January 1970?', '["Philip Effiong","Louis Mbanefo","Alexander Madiebo","Odumegwu Ojukwu"]'::jsonb, 0, 5, 'Ojukwu had flown into exile days before.', 'https://en.wikipedia.org/wiki/Philip_Effiong', 'live'),
