  ('13074311-4988-55b7-bb43-af98d44fc95b', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which military governor of the Western Region died with Aguiyi-Ironsi in 1966?', '["Adekunle Fajuyi","Robert Adebayo","Hassan Katsina","David Ejoor"]'::jsonb, 0, 5, 'Fajuyi is remembered for refusing to abandon his guest.', 'https://en.wikipedia.org/wiki/Adekunle_Fajuyi', 'live'),
