  ('3414203f-efc3-5e80-af49-cb86f889b718', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Which flower is Nigeria''s national flower?', '["Costus spectabilis","Hibiscus","Bougainvillea","Pride of Barbados"]'::jsonb, 0, 5, 'It has bright yellow trumpet-shaped blooms.', 'https://en.wikipedia.org/wiki/Costus_spectabilis', 'in_review'),
  ('a7d3f206-c1ac-58a1-8ebb-f251c0021b97', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Who was President of the UN General Assembly in 2019–20?', '["Joseph Garba","Tijjani Muhammad-Bande","Ibrahim Gambari","Amina Mohammed"]'::jsonb, 1, 5, 'He was Nigeria''s ambassador to the UN.', 'https://en.wikipedia.org/wiki/Tijjani_Muhammad-Bande', 'in_review'),
  ('d4babec4-d7fc-56dd-8eab-61ddac287be9', '4ce1015d-3027-50fa-9e9d-9221da41de75', 'Kudirat Kekere-Ekun, sworn in as Chief Justice in 2024, is Nigeria''s how-manyth female CJN?', '["Third","First","Second","Fourth"]'::jsonb, 2, 5, 'Aloma Mukhtar was the first.', 'https://en.wikipedia.org/wiki/Kudirat_Kekere-Ekun', 'in_review'),
