  ('7a1abedf-fc47-5de4-ba34-b3154e588ace', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Onitsha sits on the banks of which river?', '["Imo","Anambra","Niger","Benue"]'::jsonb, 2, 2, 'The Second Niger Bridge now links Onitsha and Asaba.', 'https://en.wikipedia.org/wiki/Onitsha', 'live'),
  ('1c614cc2-77aa-5bad-ae2d-85037af5d404', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which Lagos beach was reclaimed to build Eko Atlantic?', '["Bar Beach","Alpha Beach","Elegushi Beach","Tarkwa Bay"]'::jsonb, 0, 2, 'Bar Beach was once Lagos''s most famous beach.', 'https://en.wikipedia.org/wiki/Bar_Beach', 'live'),
  ('d20f6f75-7c08-5dee-b829-45237dfbf0b2', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Lagos''s main international airport is named after?', '["Nnamdi Azikiwe","Tafawa Balewa","Murtala Muhammed","Obafemi Awolowo"]'::jsonb, 2, 2, 'It is Nigeria''s busiest airport.', 'https://en.wikipedia.org/wiki/Murtala_Muhammed_International_Airport', 'live'),
  ('5bd21e55-7504-52b1-8301-f666cf632d26', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Abuja''s international airport is named after?', '["Murtala Muhammed","Ahmadu Bello","Nnamdi Azikiwe","Yakubu Gowon"]'::jsonb, 2, 2, 'It opened in 1982.', 'https://en.wikipedia.org/wiki/Nnamdi_Azikiwe_International_Airport', 'live'),
  ('9367ea7f-a6fd-5549-aace-aebdd52df031', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Where does the River Niger end its journey?', '["Lake Chad","Red Sea","Gulf of Guinea","Mediterranean Sea"]'::jsonb, 2, 2, 'It splits into many creeks across the Niger Delta first.', 'https://en.wikipedia.org/wiki/Niger_River', 'live'),
  ('5e12bd84-188e-5ee7-a7be-c7bd98d41e1b', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Edo State is in which geopolitical zone?', '["South South","South West","South East","North Central"]'::jsonb, 0, 2, 'Its capital is Benin City.', 'https://en.wikipedia.org/wiki/Geopolitical_zones_of_Nigeria', 'live'),
  ('35c4b001-e43e-560b-9d1b-2db21e99c6ac', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which of these states is in the South East zone?', '["Ebonyi","Kogi","Benue","Delta"]'::jsonb, 0, 2, 'The South East has five states.', 'https://en.wikipedia.org/wiki/Geopolitical_zones_of_Nigeria', 'live'),
  ('9a07966d-676b-5604-9d03-7ec43a201293', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Ogbomosho is a city in which state?', '["Oyo","Osun","Ogun","Kwara"]'::jsonb, 0, 2, 'It is one of Nigeria''s larger cities by population.', 'https://en.wikipedia.org/wiki/Ogbomosho', 'live'),
  ('5179e705-6ad8-549a-ab2d-e63753d2456f', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Nsukka, home of the University of Nigeria, is in which state?', '["Imo","Anambra","Enugu","Ebonyi"]'::jsonb, 2, 2, 'The university was founded in 1960.', 'https://en.wikipedia.org/wiki/Nsukka', 'live'),
  ('a3f5374f-87f2-5ee9-a819-dee59e811aff', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Zaria is a historic city in which state?', '["Katsina","Kaduna","Kano","Niger"]'::jsonb, 1, 2, 'It was once the capital of the Zazzau kingdom.', 'https://en.wikipedia.org/wiki/Zaria', 'live'),
  ('0ab4b9d2-e8e1-5d71-b39c-7ab3309cc5af', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Old Oyo National Park is in which state?', '["Oyo","Kwara","Osun","Ogun"]'::jsonb, 0, 2, 'It contains the ruins of the old Oyo Empire capital.', 'https://en.wikipedia.org/wiki/Old_Oyo_National_Park', 'live'),
  ('abe15036-c445-5bc6-a729-0f815ca24529', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The Calabar Carnival is held during which month?', '["December","October","August","April"]'::jsonb, 0, 2, 'It is often called Africa''s biggest street party.', 'https://en.wikipedia.org/wiki/Calabar_Carnival', 'live'),
  ('724d07d8-8f79-55c7-87ae-66b6c6dd1972', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Millennium Park is a large public park in which city?', '["Kaduna","Abuja","Lagos","Ibadan"]'::jsonb, 1, 2, 'It was opened by Queen Elizabeth II in 2003.', 'https://en.wikipedia.org/wiki/Millennium_Park_(Abuja)', 'live'),
  ('0ec6a848-7428-5a76-88d1-98eda07e1110', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Gateway State''?', '["Kogi","Ogun","Lagos","Kwara"]'::jsonb, 1, 2, 'Ogun borders Lagos and the Republic of Benin.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('b86fc83d-2235-51f8-b9dd-c11a4e28504e', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Sunshine State''?', '["Ondo","Osun","Ekiti","Oyo"]'::jsonb, 0, 2, 'Ondo''s capital is Akure.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('b48eaf62-73d5-5b77-a013-21aba7ef9c6e', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Land of Promise''?', '["Akwa Ibom","Cross River","Bayelsa","Rivers"]'::jsonb, 0, 2, 'Its capital is Uyo.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('0b6fdcf4-34e2-5240-948c-b220c5c78493', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Salt of the Nation''?', '["Ebonyi","Abia","Imo","Enugu"]'::jsonb, 0, 2, 'Ebonyi has natural salt lakes at Uburu and Okposi.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('624ab95d-3721-5646-8fb4-f05b9b0705bc', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Seat of the Caliphate''?', '["Sokoto","Kebbi","Kano","Katsina"]'::jsonb, 0, 2, 'Sokoto was the capital of the Sokoto Caliphate.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('ef0af068-594b-5757-a588-5c34d3cf0554', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Abeokuta is the capital of which state?', '["Osun","Ondo","Ogun","Oyo"]'::jsonb, 2, 2, 'The city''s name means ''under the rock''.', 'https://en.wikipedia.org/wiki/Abeokuta', 'live'),
  ('52bf84e7-912f-5c5f-ba61-5faf5cbd4399', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Makurdi is the capital of which state?', '["Benue","Nasarawa","Taraba","Kogi"]'::jsonb, 0, 2, 'It sits on the River Benue.', 'https://en.wikipedia.org/wiki/Makurdi', 'live'),
  ('17d8ca7c-5587-5916-896b-b9dbbc3d156a', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Asaba is the capital of which state?', '["Bayelsa","Anambra","Delta","Edo"]'::jsonb, 2, 2, 'It lies across the Niger from Onitsha.', 'https://en.wikipedia.org/wiki/Asaba', 'live'),
  ('a12ae24d-3f4f-54b9-97c9-bb6fa0a016ea', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which geopolitical zone has the most states?', '["South West","South South","North Central","North West"]'::jsonb, 3, 3, 'The North West has seven states.', 'https://en.wikipedia.org/wiki/Geopolitical_zones_of_Nigeria', 'live'),
  ('db0cdd0a-9193-5312-96dd-f50fd484180a', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which geopolitical zone has the fewest states?', '["South East","North East","South South","South West"]'::jsonb, 0, 3, 'The South East has five states.', 'https://en.wikipedia.org/wiki/Geopolitical_zones_of_Nigeria', 'live'),
  ('73e252ca-7d89-5719-a928-08f6da088b2c', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Kwara State belongs to which geopolitical zone?', '["North West","South West","North Central","South South"]'::jsonb, 2, 3, 'Many Kwarans are Yoruba despite the northern zone.', 'https://en.wikipedia.org/wiki/Geopolitical_zones_of_Nigeria', 'live'),
  ('fb0ee722-8cf2-58fd-8c2d-15afbf8cb284', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state has the most local government areas?', '["Katsina","Oyo","Kano","Lagos"]'::jsonb, 2, 3, 'Kano has 44 LGAs.', 'https://en.wikipedia.org/wiki/Local_government_areas_of_Nigeria', 'live'),
  ('a9f4c8d0-28e2-55e3-87d6-3d811b8a3147', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'How many local government areas does Lagos State have?', '["44","16","20","37"]'::jsonb, 2, 3, 'Lagos also has 37 local council development areas.', 'https://en.wikipedia.org/wiki/Lagos_State', 'live'),
  ('1e3144b7-5124-5e24-8a6b-55fb6bc8e39e', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state was the most populous in the 2006 census?', '["Kano","Oyo","Kaduna","Lagos"]'::jsonb, 0, 3, 'Kano edged Lagos, though Lagos disputed the figures.', 'https://en.wikipedia.org/wiki/Demographics_of_Nigeria', 'live'),
  ('20bec59d-2b69-5d32-8aab-0c88211358de', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The Bakassi Peninsula was handed over to which country in 2008?', '["Gabon","Benin","Equatorial Guinea","Cameroon"]'::jsonb, 3, 3, 'The handover followed a 2002 International Court of Justice ruling.', 'https://en.wikipedia.org/wiki/Bakassi', 'live'),
  ('ca69c803-4d02-56f0-8d3d-b588af94340b', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The Mambilla Plateau is famous for growing which crop?', '["Cocoa","Cotton","Rubber","Tea"]'::jsonb, 3, 3, 'Its cool climate suits tea and cattle.', 'https://en.wikipedia.org/wiki/Mambilla_Plateau', 'live'),
  ('8d64313c-eca4-50ac-8470-c880c38ce567', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which rare primate lives in the forests around the Nigeria–Cameroon border?', '["Cross River gorilla","Bonobo","Golden monkey","Mountain gorilla"]'::jsonb, 0, 3, 'It is one of the world''s rarest great apes.', 'https://en.wikipedia.org/wiki/Cross_River_gorilla', 'live'),
  ('c1b8dd42-bd16-5383-8c7f-51e0a28ef047', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'In which country does the River Niger begin?', '["Senegal","Mali","Guinea","Niger"]'::jsonb, 2, 3, 'It rises in the Guinea Highlands.', 'https://en.wikipedia.org/wiki/Niger_River', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('e2fb001f-835e-5753-9c08-208e969d47ec', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The Kaduna River is a tributary of which river?', '["Komadugu Yobe","Niger","Benue","Ogun"]'::jsonb, 1, 3, 'Shiroro Dam is built on the Kaduna River.', 'https://en.wikipedia.org/wiki/Kaduna_River', 'live'),
  ('5192474b-9ec1-5c09-a868-77c17e4db4db', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Kano''s centuries-old dye pits are called?', '["Kofar Mata","Gidan Makama","Kurmi","Dala"]'::jsonb, 0, 3, 'They are among the oldest in Africa.', 'https://en.wikipedia.org/wiki/Kano', 'live'),
  ('275019b6-25ce-58b7-8fd7-0a5e4bf3a4e8', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Kurmi Market, one of West Africa''s oldest markets, is in which city?', '["Sokoto","Zaria","Katsina","Kano"]'::jsonb, 3, 3, 'It dates back to the 15th century.', 'https://en.wikipedia.org/wiki/Kurmi_Market', 'live'),
  ('0ff19f84-926d-5df9-bb00-e6178c9884cc', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Igbo-Ora, nicknamed the ''Twin Capital of the World'', is in which state?', '["Ogun","Osun","Ondo","Oyo"]'::jsonb, 3, 3, 'The town has an unusually high rate of twin births.', 'https://en.wikipedia.org/wiki/Igbo-Ora', 'live'),
  ('7b452dff-61b5-538c-beb0-9e3bae168f4f', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The Ofala Festival is most associated with the king of which city?', '["Onitsha","Enugu","Awka","Owerri"]'::jsonb, 0, 3, 'The Obi of Onitsha appears in public for the celebration.', 'https://en.wikipedia.org/wiki/Ofala_Festival', 'live'),
  ('b116adbd-0834-575b-8679-7469ad17166c', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The Olojo Festival is held in which town?', '["Osogbo","Oyo","Ibadan","Ile-Ife"]'::jsonb, 3, 3, 'It celebrates Ogun, god of iron.', 'https://en.wikipedia.org/wiki/Olojo_festival', 'live'),
  ('fccfadc5-9c94-5b2c-a50d-f80f75604119', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which Lagos bridge is a cable-stayed bridge opened in 2013?', '["Lekki-Ikoyi Link Bridge","Eko Bridge","Third Mainland Bridge","Carter Bridge"]'::jsonb, 0, 3, 'It is a popular spot for joggers.', 'https://en.wikipedia.org/wiki/Lekki-Ikoyi_Link_Bridge', 'live'),
  ('d1462457-7be4-507e-855a-77cc6fcbe05b', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Kano''s international airport is named after?', '["Sani Abacha","Mallam Aminu Kano","Ado Bayero","Ahmadu Bello"]'::jsonb, 1, 3, 'It is one of the oldest airports in Nigeria.', 'https://en.wikipedia.org/wiki/Mallam_Aminu_Kano_International_Airport', 'live'),
  ('10c1d85b-91ae-56cf-9790-60043a8d22e6', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Enugu''s airport is named after?', '["Michael Okpara","Sam Mbakwe","Akanu Ibiam","Nnamdi Azikiwe"]'::jsonb, 2, 3, 'Akanu Ibiam was a governor of the Eastern Region.', 'https://en.wikipedia.org/wiki/Akanu_Ibiam_International_Airport', 'live'),
  ('bdd208ed-1511-5df7-a713-b9bac363e9fb', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Bonny Island, home of Nigeria LNG, is in which state?', '["Akwa Ibom","Bayelsa","Rivers","Delta"]'::jsonb, 2, 3, 'Gas from the Niger Delta is liquefied there for export.', 'https://en.wikipedia.org/wiki/Bonny_Island', 'live'),
  ('d9b6b9df-d497-5db0-8230-d0e28fd720fb', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Daura, Muhammadu Buhari''s hometown, is in which state?', '["Jigawa","Sokoto","Kano","Katsina"]'::jsonb, 3, 3, 'Daura is linked to the legend of Bayajidda.', 'https://en.wikipedia.org/wiki/Daura', 'live'),
  ('2eaca6f5-7d78-5249-a4a9-c55ab396e627', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Otuoke, Goodluck Jonathan''s hometown, is in which state?', '["Delta","Rivers","Akwa Ibom","Bayelsa"]'::jsonb, 3, 3, 'A federal university was established there in 2011.', 'https://en.wikipedia.org/wiki/Otuoke', 'live'),
  ('6b95060c-3514-51f6-9eb4-2a9bc34d6ca4', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Ota, home of Obasanjo''s farm and library, is in which state?', '["Lagos","Ogun","Osun","Oyo"]'::jsonb, 1, 3, 'The Olusegun Obasanjo Presidential Library is in nearby Abeokuta.', 'https://en.wikipedia.org/wiki/Ota,_Nigeria', 'live'),
  ('3432a508-ad0b-5aaf-a140-345faab6c1f0', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Nnewi, known for motor parts and Innoson Motors, is in which state?', '["Enugu","Anambra","Imo","Abia"]'::jsonb, 1, 3, 'Nnewi is sometimes called ''the Japan of Africa''.', 'https://en.wikipedia.org/wiki/Nnewi', 'live'),
  ('ee16ca91-a550-5e2c-adec-40a49688841a', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Suleja, a town bordering Abuja, is in which state?', '["Nasarawa","Niger","Kaduna","Kogi"]'::jsonb, 1, 3, 'Suleja was formerly called Abuja.', 'https://en.wikipedia.org/wiki/Suleja', 'live'),
  ('d4c621ad-9949-5ec3-b39f-29bd5430ed83', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Okene is a major town in which state?', '["Edo","Kogi","Niger","Kwara"]'::jsonb, 1, 3, 'Okene is the heartland of the Ebira people.', 'https://en.wikipedia.org/wiki/Okene', 'live'),
  ('1d1931c0-b077-53e0-b002-6d79a3edf13a', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Ikot Ekpene, nicknamed the ''Raffia City'', is in which state?', '["Abia","Rivers","Cross River","Akwa Ibom"]'::jsonb, 3, 3, 'It is famous for raffia crafts.', 'https://en.wikipedia.org/wiki/Ikot_Ekpene', 'live'),
  ('a3bab666-2ae0-5558-a413-a7877f1fd39b', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Offa is a town in which state?', '["Kwara","Oyo","Osun","Kogi"]'::jsonb, 0, 3, 'Most people in Offa are Yoruba.', 'https://en.wikipedia.org/wiki/Offa,_Nigeria', 'live'),
  ('ee23c982-68db-537d-9350-f2e196ccd310', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Home of Hospitality''?', '["Kaduna","Kano","Kebbi","Katsina"]'::jsonb, 3, 3, 'Katsina was carved out of Kaduna State in 1987.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('1309b51c-e2ea-54c1-9df0-8d0be8f3c8ca', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Land of Beauty''?', '["Plateau","Taraba","Gombe","Adamawa"]'::jsonb, 3, 3, 'Its capital is Yola.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('2efbed93-2214-5189-8ae1-447e487db815', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Pearl of Tourism''?', '["Cross River","Kebbi","Bauchi","Plateau"]'::jsonb, 2, 3, 'It is home to Yankari Game Reserve.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('cc06db85-5656-508a-ba64-236901541bcb', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Land of Honour and Integrity''?', '["Kwara","Ondo","Osun","Ekiti"]'::jsonb, 3, 3, 'Ekiti was created in 1996.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('0071b30b-b63e-564f-a7e0-bb8796cede71', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Pride of the Sahel''?', '["Sokoto","Borno","Yobe","Jigawa"]'::jsonb, 2, 3, 'Its capital is Damaturu.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('5f097dbd-64c5-5613-8ac6-b94a864527a7', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Nature''s Gift to the Nation''?', '["Plateau","Taraba","Cross River","Adamawa"]'::jsonb, 1, 3, 'Taraba is home to the Mambilla Plateau.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('61b5f0b2-c052-5ac9-9df3-dde7e3b2d995', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''The New World''?', '["Yobe","Jigawa","Kebbi","Zamfara"]'::jsonb, 1, 3, 'Its capital is Dutse.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('87e26670-0567-5b9b-bfe1-29ea863db08e', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which state''s slogan is ''Farming is Our Pride''?', '["Niger","Kebbi","Benue","Zamfara"]'::jsonb, 3, 3, 'Its capital is Gusau.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('4b4f0bed-c601-55fc-9882-6a957c2a37d0', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'The FCT''s slogan is?', '["Heart of the Nation","Centre of Unity","Centre of Excellence","Home of Peace"]'::jsonb, 1, 3, 'Abuja was chosen partly for its central location.', 'https://en.wikipedia.org/wiki/List_of_Nigerian_state_nicknames', 'live'),
  ('a29a36ae-1adb-519c-b346-5829a46ec083', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Which is the oldest of the bridges linking Lagos Island to the mainland?', '["Eko Bridge","Carter Bridge","Lekki-Ikoyi Link Bridge","Third Mainland Bridge"]'::jsonb, 1, 4, 'The first Carter Bridge opened in 1901.', 'https://en.wikipedia.org/wiki/Carter_Bridge', 'live'),
  ('2ba6b862-fc68-5727-9aca-878b04423cb9', '211a4a9b-0b4a-557f-babf-a3510ad048a9', 'Lekki Deep Sea Port began commercial operations in which year?', '["2023","2019","2016","2021"]'::jsonb, 0, 4, 'It is Nigeria''s first deep-sea port.', 'https://en.wikipedia.org/wiki/Lekki_Deep_Sea_Port', 'live'),
