  ('8fbe33fe-4601-533b-8a99-3ffdfabf71ec', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Miyan kuka is made from the leaves of which tree?', '["Moringa","Mango","Neem","Baobab"]'::jsonb, 3, 2, 'Dried, powdered baobab leaves give the soup its texture.', 'https://en.wikipedia.org/wiki/Miyan_kuka', 'live'),
  ('a9e41b4e-aba8-52c3-9756-f6c280688d3f', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kilishi is a northern Nigerian…', '["Rice cake","Millet drink","Spiced dried meat","Bean dumpling"]'::jsonb, 2, 2, 'It''s like a spicy, thin jerky.', 'https://en.wikipedia.org/wiki/Kilishi', 'live'),
  ('77e9c8ea-7bec-5758-95e0-228545293149', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kuli-kuli is made from…', '["Tiger nuts","Groundnuts","Cashews","Coconut"]'::jsonb, 1, 2, 'It''s crunchy fried groundnut paste, often ground into suya spice.', 'https://en.wikipedia.org/wiki/Kuli-kuli', 'live'),
  ('3d4481bf-62cd-5d74-a14f-bc962b35f3f3', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Masa (waina) is a northern Nigerian…', '["Bean stew","Plantain chip","Rice cake","Meat pie"]'::jsonb, 2, 2, 'It''s often eaten with miyan taushe or spicy pepper.', 'https://en.wikipedia.org/wiki/Masa_(food)', 'live'),
  ('9e255fb7-7cfe-55ba-bce5-7d8236b5e4b8', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Fura da nono combines millet balls with…', '["Palm wine","Tea","Zobo","Fermented milk"]'::jsonb, 3, 2, 'It''s a popular Fulani refreshment.', 'https://en.wikipedia.org/wiki/Fura', 'live'),
  ('6bf2ae62-8fbe-59ae-8e18-76831b797ed3', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kunu is a drink usually made from…', '["Cocoa","Millet or sorghum","Palm sap","Hibiscus"]'::jsonb, 1, 2, 'Kunu aya is a variant made with tiger nuts.', 'https://en.wikipedia.org/wiki/Kunu', 'live'),
  ('b02795d7-7e9f-58f8-8772-e9e11c92d718', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Chapman is a popular Nigerian…', '["Mocktail/cocktail","Pepper soup","Pastry","Snack chip"]'::jsonb, 0, 2, 'It typically mixes soft drinks with grenadine and Angostura bitters.', 'https://en.wikipedia.org/wiki/Chapman_(drink)', 'live'),
  ('57fc74d1-3b7b-5a16-92be-e07efcbfc996', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Nkwobi is made with…', '["Cow foot","Goat head","Catfish","Chicken gizzard"]'::jsonb, 0, 2, 'It''s served in a spicy palm oil paste with utazi leaves.', 'https://en.wikipedia.org/wiki/Nkwobi', 'live'),
  ('df5606b1-3398-5f75-932e-27e6ce799238', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Isi ewu is a delicacy made from which part of the goat?', '["Liver","Tail","Leg","Head"]'::jsonb, 3, 2, 'It''s a beer-parlour classic in the South East.', 'https://en.wikipedia.org/wiki/Isi_ewu', 'live'),
  ('ace27bec-c6f6-5b0f-8a6a-d15772fb531d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Boli'' is the name for…', '["Boiled yam","Grilled corn","Fried cassava","Roasted plantain"]'::jsonb, 3, 2, 'In Port Harcourt it''s famously eaten with fish: ''bole and fish''.', 'https://en.wikipedia.org/wiki/Bole_(food)', 'live'),
  ('81cd69a7-2b2e-5203-91c7-843c72b25e60', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ofada rice is traditionally served with which sauce?', '["Ayamase (green pepper stew)","Gbegiri","Ogbono","Egusi"]'::jsonb, 0, 2, 'Ayamase is also called ''designer stew''.', 'https://en.wikipedia.org/wiki/Ofada_rice', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
