  ('dbf5dcdd-2c4d-548a-9237-67043e11e4dc', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Amala served with gbegiri and ewedu together is called…', '["Asaro","Ekuru","Abula","Ikokore"]'::jsonb, 2, 2, 'Abula is a must-try in Ibadan.', 'https://en.wikipedia.org/wiki/Gbegiri_soup', 'live'),
  ('1d2d4597-7c1f-533c-9dea-ecf8a4f35ec7', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Rodo'' is the Yoruba name for which pepper?', '["Black pepper","Scotch bonnet","Cayenne","Bell pepper"]'::jsonb, 1, 2, 'Tatashe is the milder red bell pepper.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('ee22dd25-60fe-5564-bb29-fa149f7fcade', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Kpomo'' (ponmo) is made from…', '["Fish bones","Cow skin","Chicken feet","Goat intestine"]'::jsonb, 1, 2, 'It''s soft, chewy and soaks up stew flavour.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('afc2490c-2d1a-5cec-8175-161474993483', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Shaki'' refers to which part of a cow?', '["Tail","Liver","Tripe (stomach)","Tongue"]'::jsonb, 2, 2, 'Shaki is popular in pepper soup and stew.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('e6ee8d63-73fd-5174-98c2-e344ed57b432', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which bread, named after a Lagos town, is a soft, dense Nigerian favourite?', '["Ikorodu loaf","Epe roll","Badagry bun","Agege bread"]'::jsonb, 3, 2, 'Agege bread pairs well with akara or ewa agoyin.', 'https://en.wikipedia.org/wiki/Agege_bread', 'live'),
  ('1954523d-7997-5ca7-9267-5ec2d3d42daa', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Iru (dawadawa) is made from fermented…', '["Locust beans","Cocoa beans","Oil beans","Soy beans"]'::jsonb, 0, 3, 'It adds a deep umami flavour to soups.', 'https://en.wikipedia.org/wiki/Dawadawa', 'live'),
  ('fe763fb6-856f-5552-96a0-bba86253631e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ugba (ukpaka) is made from…', '["Breadfruit","Dried cassava","Locust beans","Fermented oil bean seeds"]'::jsonb, 3, 3, 'Ugba is a key topping in abacha.', 'https://en.wikipedia.org/wiki/Pentaclethra_macrophylla', 'live'),
  ('e5c70769-648e-51f9-91df-223ff5c134f4', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ukwa is the Igbo name for…', '["Coconut","Bambara nut","African breadfruit","Cocoyam"]'::jsonb, 2, 3, 'Ukwa is cooked into a rich porridge.', 'https://en.wikipedia.org/wiki/Treculia_africana', 'live'),
  ('b5a48d7c-7054-5186-aa6f-0fcf855dc8f2', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Nsala soup is also known as…', '["Black soup","Green soup","White soup","Draw soup"]'::jsonb, 2, 3, 'It''s cooked without palm oil and thickened with pounded yam.', 'https://en.wikipedia.org/wiki/Nsala_soup', 'live'),
  ('3fd986fe-bafb-57f4-8fb8-70e928dab47b', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Oha soup gets its name from…', '["A type of fish","A spice blend","The leaves of the oha tree","A town called Oha"]'::jsonb, 2, 3, 'Oha leaves are torn by hand rather than cut.', 'https://en.wikipedia.org/wiki/Oha_soup', 'live'),
  ('62b1e85c-9626-5cc8-9b2f-29e97815c7da', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Efo riro is a Yoruba…', '["Yam porridge","Bean pudding","Vegetable soup","Pepper soup"]'::jsonb, 2, 3, 'Efo riro means ''stirred leaf'' in Yoruba.', 'https://en.wikipedia.org/wiki/Efo_riro', 'live'),
  ('e5e6b04b-a3c6-5841-82ea-b6bc58ba6115', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ewa agoyin is beans served with…', '["Tomato ketchup","Coconut milk","A special dark pepper sauce","Egusi"]'::jsonb, 2, 3, 'The sauce is made by slowly frying dried peppers and onions in palm oil.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('4f438e50-179d-5feb-a55f-3f606c5bb820', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ikokore is a pottage from Ijebu made with…', '["Plantain","Beans","Rice","Water yam"]'::jsonb, 3, 3, 'The water yam is grated before cooking.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('1d34ba7e-e5f9-5385-81a8-bacd831fa1fe', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The Yoruba dish ekuru is…', '["Coconut candy","Fried yam","White moi moi without pepper or oil","Corn porridge"]'::jsonb, 2, 3, 'It''s served with a separate pepper sauce.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('b28dff3f-c13a-5373-81c1-2b2d00780581', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Gizdodo combines plantain with…', '["Prawns","Liver","Snail","Gizzard"]'::jsonb, 3, 3, 'It''s a popular Nigerian party side dish.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('9122357e-3f9e-51c3-90f9-7f73341d4c9d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Asun is a…', '["Fish soup","Spicy smoked goat meat","Corn snack","Leaf wrap"]'::jsonb, 1, 3, 'Asun is a Yoruba barbecue favourite.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('bde3c1c1-4ed0-5a04-9709-c66fdf7a9648', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Yamarita is yam that is…', '["Pounded with plantain","Roasted with palm oil","Boiled with beans","Coated in egg batter and fried"]'::jsonb, 3, 3, 'It''s a popular Lagos breakfast.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('8ac6fd01-0e10-5fd8-a27d-e88cd9fd73b3', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Dan wake is a northern dish of…', '["Millet porridge","Bean flour dumplings","Rice pancakes","Fried meat"]'::jsonb, 1, 3, 'It''s served with oil, pepper and boiled egg.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('26dd5f99-3aef-5126-b831-f7b381551f47', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kosai is the Hausa name for…', '["Puff-puff","Suya","Moi moi","Akara"]'::jsonb, 3, 3, 'Kosai is a common northern breakfast.', 'https://en.wikipedia.org/wiki/Akara', 'live'),
