  ('7837fa62-d463-53e0-a811-31b12b1b736c', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Miya'' means soup in which language?', '["Igbo","Hausa","Ijaw","Yoruba"]'::jsonb, 1, 3, 'Miyan kuka means ''baobab leaf soup''.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('1cd4934b-f412-5ba2-8f9a-57ff66316f04', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Scent leaf is called ''efirin'' in Yoruba. What is its common English plant name?', '["African basil","Coriander","Bay leaf","Mint"]'::jsonb, 0, 3, 'In Igbo it''s nchanwu; in Hausa, daidoya.', 'https://en.wikipedia.org/wiki/Ocimum_gratissimum', 'live'),
  ('d398cd2c-8154-5f24-8f57-4be74a0ea6bb', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Uziza seeds and leaves are a type of…', '["Ginger","Pepper","Garlic","Onion"]'::jsonb, 1, 3, 'Uziza adds peppery heat to soups like ofe nsala.', 'https://en.wikipedia.org/wiki/Piper_guineense', 'live'),
  ('d8f10cb9-b2b3-504b-8d9f-f05fd0a36270', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ehuru is better known in English as…', '["Black pepper","Cloves","Cinnamon","Calabash nutmeg"]'::jsonb, 3, 3, 'It''s toasted and ground for pepper soup.', 'https://en.wikipedia.org/wiki/Monodora_myristica', 'live'),
  ('2d0be09c-7d78-5ec5-b703-6efabd16e865', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which state is Nigeria''s leading cocoa producer?', '["Cross River","Ondo","Ekiti","Oyo"]'::jsonb, 1, 3, 'Cocoa was a key cash crop of the old Western Region.', 'https://en.wikipedia.org/wiki/Ondo_State', 'live'),
  ('f68aaf20-3def-5cb8-92ca-db41636b0012', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kano was famous in the 1960s for pyramids made of what?', '["Groundnut sacks","Cocoa bags","Cotton bales","Rice sacks"]'::jsonb, 0, 3, 'The groundnut pyramids were a symbol of northern agriculture.', 'https://en.wikipedia.org/wiki/Groundnut_pyramids', 'live'),
  ('4469b3c7-3eca-58b1-bc5b-9efc3006986e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Stockfish, used in many Nigerian soups, is mostly imported from which country?', '["Japan","Norway","Morocco","Portugal"]'::jsonb, 1, 3, 'Stockfish is cod that is air-dried in the cold.', 'https://en.wikipedia.org/wiki/Stockfish', 'live'),
  ('e404d4d7-18df-588d-a243-16196b9b79f9', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ofada rice is named after a town in which state?', '["Oyo","Ondo","Lagos","Ogun"]'::jsonb, 3, 3, 'It''s a local, unpolished rice with a strong aroma.', 'https://en.wikipedia.org/wiki/Ofada_rice', 'live'),
  ('b829ea88-cb82-555f-a6b9-69278213f720', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which spice blend coats suya?', '["Suya masala","Ras el hanout","Yaji","Berbere"]'::jsonb, 2, 3, 'Yaji typically includes ground kuli-kuli, ginger and chilli.', 'https://en.wikipedia.org/wiki/Suya', 'live'),
  ('7b96d43f-a690-5c8d-9b1b-c626610bd08e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Burukutu is a traditional beer brewed from…', '["Sorghum or millet","Plantain","Barley","Palm sap"]'::jsonb, 0, 3, 'It''s popular in the Middle Belt and north.', 'https://en.wikipedia.org/wiki/Burukutu', 'live'),
  ('c48be014-a5bf-55f7-b9ac-2c151057a13b', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Utazi leaves are known for being…', '["Salty","Sweet","Bitter","Sour"]'::jsonb, 2, 4, 'Utazi is used sparingly in nkwobi and ugba.', 'https://en.wikipedia.org/wiki/Gongronema_latifolium', 'live'),
  ('d8825fd5-dc1a-55f7-bb62-2a000e406391', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ofe Owerri is a rich soup from which state?', '["Abia","Enugu","Imo","Anambra"]'::jsonb, 2, 4, 'It''s thickened with cocoyam and packed with meats.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('2fcb92de-2bba-584e-9e53-ba988e0ee163', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ekpang Nkukwo is a Calabar dish made with grated cocoyam wrapped in…', '["Cocoyam or ugu leaves","Corn husks","Moin-moin leaves","Banana leaves"]'::jsonb, 0, 4, 'It''s cooked in a rich palm oil broth with seafood.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('a2bc7569-793a-5219-8ae0-c037f0d37086', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Afia efere is an Efik…', '["White soup","Leaf salad","Pepper sauce","Fish roll"]'::jsonb, 0, 4, 'It is cooked without palm oil.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('dbf8355d-f598-5df4-850c-6f899ae6390a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ukodo is a yam pepper soup associated with which people?', '["Hausa","Urhobo","Kanuri","Tiv"]'::jsonb, 1, 4, 'It''s often cooked with goat meat and lemongrass.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('6747cc19-9ace-5b6f-8353-b782fc03decf', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Miyan taushe is a northern soup made mainly with…', '["Pumpkin","Baobab leaves","Okra","Spinach"]'::jsonb, 0, 4, 'Groundnut paste often thickens it.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('10d95845-66d9-58b5-bb05-5485ec1f34c7', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Agidi (eko) is a solid pudding made from…', '["Beans","Rice","Corn starch (pap)","Cassava"]'::jsonb, 2, 4, 'It''s wrapped in leaves and eaten with stews or akara.', 'https://en.wikipedia.org/wiki/Agidi_(food)', 'live'),
  ('717171ce-521f-59bb-9ae0-a07f8bd92c13', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Dambu nama is a northern dish of…', '["Fermented milk","Shredded fried meat floss","Rice balls","Spiced beans"]'::jsonb, 1, 4, 'It''s often made for festive occasions.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('24b9210a-00fa-52b1-86a6-d5897e9b9214', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which tool is used to whip ewedu soup?', '["Ikoko","Odo","Ijabe","Omorogun"]'::jsonb, 2, 4, 'An omorogun is a wooden stick for turning amala and eba.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('c032ccac-ca37-57b0-b000-6759c8c97201', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'An ''omorogun'' is used in the kitchen to…', '["Grind pepper","Pound yam","Turn swallows like amala and eba","Whip ewedu"]'::jsonb, 2, 4, 'It''s a flat wooden stirring stick.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('412d9578-3158-5eec-9cc4-f1fd8a7cf958', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kunu aya is made from…', '["Tiger nuts","Millet","Sorghum","Coconut"]'::jsonb, 0, 4, 'Tiger nuts are called aya in Hausa.', 'https://en.wikipedia.org/wiki/Kunu', 'live'),
  ('b062bc35-bd75-5465-9c2f-9829d3d1c950', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Nono is the Hausa/Fulani name for…', '["Honey","Fermented milk","Millet","Butter"]'::jsonb, 1, 4, 'Nono is famously paired with fura.', 'https://en.wikipedia.org/wiki/Fura', 'live'),
  ('e1a496e8-be78-5653-b911-261cffa3f11b', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Tatashe is…', '["Red bell pepper","Scotch bonnet","Garden egg","Long chilli"]'::jsonb, 0, 4, 'Tatashe gives stews their deep red colour without too much heat.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('5ad81b35-72b7-57fc-9c23-ef2f9681c076', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Shombo is a…', '["Type of fish","Long red chilli pepper","Bean variety","Leafy vegetable"]'::jsonb, 1, 4, 'Shombo, tatashe and rodo form the base of Nigerian stew.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('764f309e-cc11-5912-9d69-bc865a08b25d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Garden egg is a type of…', '["Tomato","Potato","Eggplant","Egg"]'::jsonb, 2, 4, 'Garden eggs are often eaten raw with peanut butter.', 'https://en.wikipedia.org/wiki/Solanum_aethiopicum', 'live'),
  ('7ed32a70-d3e1-5dde-9d96-b89d1bf83908', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ijebu garri is known for being…', '["Smoked and brown","Coarse and red","Yellow and sweet","White, fine and sour"]'::jsonb, 3, 4, 'Yellow garri gets its colour from palm oil.', 'https://en.wikipedia.org/wiki/Garri', 'live'),
  ('6f341f36-07b9-545b-b850-78a9a3f2274f', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The Igbo New Yam festival is called…', '["Ofala","Iri Ji","Eyo","Igue"]'::jsonb, 1, 4, 'It marks the end of the farming season.', 'https://en.wikipedia.org/wiki/New_Yam_Festival_of_the_Igbo', 'live'),
  ('a3762a38-169e-575e-836b-4be578dcbd6c', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which Edo dish is called ''black soup'' (omoebe)?', '["Smoked fish stew","A dark herbal leaf soup","Burnt-pot jollof","Charcoal-roasted yam"]'::jsonb, 1, 4, 'It gets its dark colour from blended bitter leaf, scent leaf and uziza.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('7ba7c5ad-37a4-58ce-b7b0-caca1437ed2a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Afang leaves come from which climbing plant?', '["Talinum triangulare","Vernonia amygdalina","Gnetum africanum","Telfairia occidentalis"]'::jsonb, 2, 5, 'Afang is widely harvested from forests in the south.', 'https://en.wikipedia.org/wiki/Gnetum_africanum', 'live'),
  ('d030aab0-9b84-5766-b1fd-ec1b268dfd72', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Waterleaf''s scientific name is…', '["Corchorus olitorius","Piper guineense","Gnetum africanum","Talinum triangulare"]'::jsonb, 3, 5, 'It softens dishes like edikang ikong.', 'https://en.wikipedia.org/wiki/Talinum_fruticosum', 'live'),
  ('26f56b9e-af63-5204-a849-a6454fd033b5', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ogbono seeds come from which tree?', '["Irvingia gabonensis","Elaeis guineensis","Adansonia digitata","Parkia biglobosa"]'::jsonb, 0, 5, 'The tree is also called African bush mango.', 'https://en.wikipedia.org/wiki/Irvingia_gabonensis', 'live'),
  ('9b7001ee-7b6b-518d-994c-7e8c28a65aa9', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Iru/dawadawa is traditionally made from the seeds of which tree?', '["Irvingia gabonensis","Treculia africana","Parkia biglobosa","Vitellaria paradoxa"]'::jsonb, 2, 5, 'Parkia biglobosa is called the African locust bean tree.', 'https://en.wikipedia.org/wiki/Parkia_biglobosa', 'live'),
  ('d23848f5-f4ca-545b-90d2-0c05d3ced27a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The oil palm, source of palm oil, has which scientific name?', '["Cocos nucifera","Borassus aethiopum","Raphia hookeri","Elaeis guineensis"]'::jsonb, 3, 5, 'The oil palm is native to West and Central Africa.', 'https://en.wikipedia.org/wiki/Elaeis_guineensis', 'live'),
  ('f2a0e5c3-bf0b-5998-8c57-7cde25041567', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Bitter leaf''s scientific name is…', '["Gongronema latifolium","Vernonia amygdalina","Ocimum gratissimum","Piper guineense"]'::jsonb, 1, 5, 'It is used in ofe onugbu and as a herbal remedy.', 'https://en.wikipedia.org/wiki/Vernonia_amygdalina', 'live'),
  ('3a997530-5a85-56a7-9cf9-1b777d61f756', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ewedu is made from the leaves of which plant?', '["Amaranthus hybridus","Corchorus olitorius","Telfairia occidentalis","Talinum triangulare"]'::jsonb, 1, 5, 'The same plant is used to make jute fibre.', 'https://en.wikipedia.org/wiki/Corchorus_olitorius', 'live'),
  ('f6324462-4b1c-52e1-9600-3491762a9318', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which spice, called ''uda'' in Igbo, comes from the seed pods of Xylopia aethiopica?', '["Grains of Selim","Calabash nutmeg","Grains of paradise","Alligator pepper"]'::jsonb, 0, 5, 'It is used in pepper soup and post-natal dishes.', 'https://en.wikipedia.org/wiki/Xylopia_aethiopica', 'live'),
  ('b60b8f9e-24f2-5a49-95b9-bd544666230e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Alligator pepper is also known as…', '["Grains of paradise","Calabash nutmeg","West African pepper","Grains of Selim"]'::jsonb, 0, 5, 'It is widely used in traditional ceremonies.', 'https://en.wikipedia.org/wiki/Aframomum_melegueta', 'live'),
  ('2780f986-81ff-5922-845b-61efdb1ed515', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Shea butter comes from which tree?', '["Parkia biglobosa","Vitellaria paradoxa","Irvingia gabonensis","Elaeis guineensis"]'::jsonb, 1, 5, 'Nigeria is one of the largest producers of shea nuts.', 'https://en.wikipedia.org/wiki/Vitellaria', 'live'),
  ('b19a4802-6ca2-5505-9050-e5184e9dc9bf', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The kola nut, important in Igbo hospitality, comes from which genus?', '["Coffea","Garcinia","Cola","Theobroma"]'::jsonb, 2, 5, 'Bitter kola is a different plant, Garcinia kola.', 'https://en.wikipedia.org/wiki/Kola_nut', 'live'),
  ('3350b5d1-38a0-588a-9e9d-eb9e469f113a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Bitter kola belongs to which genus?', '["Piper","Garcinia","Xylopia","Cola"]'::jsonb, 1, 5, 'It is chewed for its bitter taste and believed health benefits.', 'https://en.wikipedia.org/wiki/Garcinia_kola', 'live'),
  ('38635404-56a4-5835-9893-899a4761b9f6', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Jollof rice gets its red colour mainly from?', '["Food colouring","Tomatoes and peppers","Beetroot","Palm oil only"]'::jsonb, 1, 1, 'A blend of tomato, tatashe and scotch bonnet forms the base.', 'https://en.wikipedia.org/wiki/Jollof_rice', 'live'),
  ('a0601d8f-4698-5e78-8bc7-c8b461428c65', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Fresh catfish pepper soup is popularly called?', '["Point and kill","Asun","Isi ewu","Nkwobi"]'::jsonb, 0, 1, 'Customers point at a live fish, which is then cooked for them.', 'https://en.wikipedia.org/wiki/Pepper_soup', 'live'),
  ('e5fb7ed1-8497-5638-869c-aa692c16604c', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which instant noodle brand is a household name in Nigeria?', '["Indomie","Maggi","Golden Penny","Dangote"]'::jsonb, 0, 1, 'Nigeria is one of the world''s biggest instant-noodle markets.', 'https://en.wikipedia.org/wiki/Indomie', 'live'),
  ('78f3242d-df42-55e0-88ca-4c65f9540b7e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Garri soaked in cold water with sugar, milk and groundnuts is known as?', '["Eba","Soaked garri","Fufu","Abacha"]'::jsonb, 1, 1, 'It''s a favourite snack in boarding schools.', 'https://en.wikipedia.org/wiki/Garri', 'live'),
  ('37fc6196-3b3a-5b46-a8e7-4d02e562fe13', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'A ''mama put'' is a…', '["Market tax","Roadside food vendor","Wedding planner","Type of soup"]'::jsonb, 1, 1, 'The name comes from customers saying ''Mama, put more!''.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('83778b6b-cbd7-5606-87da-3831478fd624', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'A ''buka'' is a…', '["Kind of bread","Cooking pot","Local restaurant","Spice blend"]'::jsonb, 2, 1, 'Bukas serve swallow, soups and rice at affordable prices.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('f0866e02-e12e-5381-9a3d-2a2a2d3b6a1e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Hilda Baci set a Guinness World Record in 2023 for what?', '["Fastest pounded yam","Longest cooking marathon by an individual","Biggest pot of jollof","Most suya skewers"]'::jsonb, 1, 1, 'Crowds gathered in Lekki to cheer her on.', 'https://en.wikipedia.org/wiki/Hilda_Baci', 'live'),
  ('a98beaa8-8603-5b19-b40c-0ed1fb4f7ed3', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which of these is a classic item in Nigerian ''small chops''?', '["Pounded yam","Tuwo","Samosa","Egusi soup"]'::jsonb, 2, 1, 'Small chops often include puff-puff, spring rolls and gizzard.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('dd3080f5-d16d-5c4f-9df8-3f990bbe067d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which dressing is a favourite on Nigerian salads?', '["Pesto","Balsamic vinegar","Ranch","Salad cream"]'::jsonb, 3, 1, 'Nigerian salads often include baked beans and boiled eggs too.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('256405b6-2567-578f-8bb0-9e89b3f24e24', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Fried yam is called what in Yoruba?', '["Iyan","Ojojo","Asaro","Dundun"]'::jsonb, 3, 1, 'It is often served with fried pepper sauce.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('446e8b83-b58b-5e7b-b301-f9b85580b756', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Pounded yam is called what in Yoruba?', '["Amala","Eko","Iyan","Dundun"]'::jsonb, 2, 1, 'It is often eaten with egusi or efo riro.', 'https://en.wikipedia.org/wiki/Pounded_yam', 'live'),
  ('4ad72b96-ef0a-5677-a267-4ac3e7c44d8d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Yellow garri gets its colour from what?', '["Egg yolk","Turmeric","Carrots","Palm oil"]'::jsonb, 3, 1, 'White garri is made without palm oil.', 'https://en.wikipedia.org/wiki/Garri', 'live'),
  ('47be3636-6b0d-5e2b-9300-0d40553a4573', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Akpu is the Igbo name for which swallow?', '["Cassava fufu","Amala","Pounded yam","Tuwo"]'::jsonb, 0, 1, 'It is made from fermented cassava.', 'https://en.wikipedia.org/wiki/Fufu', 'live'),
  ('e4ba8aba-7e0b-5f07-9133-7a85f8a7d605', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Agbalumo, a seasonal fruit, is known in English as?', '["Mango","Soursop","African star apple","Guava"]'::jsonb, 2, 1, 'It is called udara in Igbo.', 'https://en.wikipedia.org/wiki/Chrysophyllum_albidum', 'live'),
  ('9a6d3ca1-6609-57fe-a6b8-c6cfbd0568db', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ube, a purple fruit often eaten with roasted corn, is known in English as?', '["Avocado","African pear","Plum","Fig"]'::jsonb, 1, 1, 'Ube softens when warmed in hot water.', 'https://en.wikipedia.org/wiki/Dacryodes_edulis', 'live'),
  ('86e2a028-aed8-566f-b1bc-a9c2c8a20335', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Suya originated with which people?', '["Hausa","Efik","Igbo","Ijaw"]'::jsonb, 0, 1, 'Suya spots stay busy late into the night.', 'https://en.wikipedia.org/wiki/Suya', 'live'),
  ('17ff859a-a1f9-598a-9088-a2a6e9a06f41', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ogogoro is a…', '["Fermented milk","Local gin distilled from palm wine","Ginger drink","Millet porridge"]'::jsonb, 1, 1, 'It also goes by names like kai-kai and Sapele water.', 'https://en.wikipedia.org/wiki/Ogogoro', 'live'),
  ('93edc2d4-ad58-5b2c-ac79-69acb027d516', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Asaro'' is a Yoruba dish of…', '["Yam porridge","Rice pudding","Bean cake","Fried plantain"]'::jsonb, 0, 1, 'It is cooked with palm oil, peppers and fish.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('d22d6bec-af85-525e-975e-407614224502', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Fisherman soup is most associated with which region?', '["North Central","South West","North West","Niger Delta"]'::jsonb, 3, 2, 'It is packed with fresh fish and seafood.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('cc0745c9-5e86-5989-afe8-9ad29372877d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Okpa is made mainly from which ingredient?', '["Cassava","Plantain","Bambara nut flour","Millet"]'::jsonb, 2, 2, 'It is a popular breakfast in Enugu State.', 'https://en.wikipedia.org/wiki/Okpa', 'live'),
  ('4803543a-d286-5768-bfd6-a18f3e1e9487', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Akamu is the Igbo name for which food?', '["Fufu","Moi moi","Akara","Pap"]'::jsonb, 3, 2, 'It is called ogi in Yoruba.', 'https://en.wikipedia.org/wiki/Ogi_(food)', 'live'),
  ('0492d68c-6a62-57ab-b0a7-a6474f2a1dba', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Tuwo masara is made from what?', '["Yam","Maize","Rice","Cassava"]'::jsonb, 1, 2, 'Masara is the Hausa word for maize.', 'https://en.wikipedia.org/wiki/Tuwo', 'live'),
  ('b0f5ce79-f6a2-5d19-9d2f-40870cd4c603', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Fufu is most commonly made from which crop?', '["Fermented cassava","Wheat","Sorghum","Rice"]'::jsonb, 0, 2, 'It is soaked, mashed and cooked into a soft dough.', 'https://en.wikipedia.org/wiki/Fufu', 'live'),
  ('aac96fb9-1e3a-5329-8a29-e1d5ce5cf6fb', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Semovita is made from what?', '["Wheat (semolina)","Yam","Corn","Cassava"]'::jsonb, 0, 2, 'It is a popular swallow in many homes.', 'https://en.wikipedia.org/wiki/Semolina', 'live'),
  ('c2d242c0-f680-5c8c-a59f-5a8c73b48762', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'In Port Harcourt, roasted plantain (''bole'') is famously served with?', '["Egusi soup","Moi moi","Ewedu","Grilled fish"]'::jsonb, 3, 2, 'The dish is a Rivers State street-food icon.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('0ddd6c23-a492-53a7-afe6-33dd98be7e7c', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Obe ata'' is the Yoruba name for which dish?', '["Okra soup","Bean porridge","Pepper stew","Yam pottage"]'::jsonb, 2, 2, 'It is a base for many rice and swallow meals.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('a2d8c0c6-179a-5bb4-b45b-5e9ed6d046d6', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Nigerian fried rice often gets its yellow colour from what?', '["Curry powder","Saffron","Palm oil","Egg yolk"]'::jsonb, 0, 2, 'It is usually cooked with mixed vegetables.', 'https://en.wikipedia.org/wiki/Fried_rice', 'live'),
  ('2f041e93-39cb-5601-bff4-176ea824e5dc', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Zobo is often spiced with which ingredients?', '["Onion and garlic","Ginger and cloves","Curry and thyme","Salt and pepper"]'::jsonb, 1, 2, 'Pineapple is often added for sweetness.', 'https://en.wikipedia.org/wiki/Zobo_drink', 'live'),
  ('34d0fcbf-a785-5612-ac14-e5176126a8ad', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which spicy northern meat on sticks is similar to suya?', '["Balangu","Dambu","Tsire","Kilishi"]'::jsonb, 2, 2, 'Tsire is coated in groundnut-based spice before grilling.', 'https://en.wikipedia.org/wiki/Suya', 'live'),
  ('31f392de-6956-59b3-a19b-06e3633fb232', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kunun gyada is a kunu made with what?', '["Ginger","Sorghum only","Tiger nuts","Groundnuts"]'::jsonb, 3, 2, 'Gyada is the Hausa word for groundnut.', 'https://en.wikipedia.org/wiki/Kunu', 'live'),
  ('8d10cf93-89d1-5a87-a373-b67f46669e69', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Miyan zogale is a northern soup made with which leaves?', '["Pumpkin","Baobab","Moringa","Bitter leaf"]'::jsonb, 2, 2, 'Zogale is the Hausa name for moringa.', 'https://en.wikipedia.org/wiki/Moringa_oleifera', 'live'),
  ('11c3261f-851f-5425-86fd-a2eb7ee246d8', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Oji'' is the Igbo word for what?', '["Yam","Kola nut","Palm wine","Pepper"]'::jsonb, 1, 2, 'Breaking kola opens many Igbo gatherings.', 'https://en.wikipedia.org/wiki/Kola_nut', 'live'),
  ('01eca577-1bd3-5cf6-bc87-067570f69fc5', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Palm wine is called what in Yoruba?', '["Oji","Emu","Burukutu","Nkwu"]'::jsonb, 1, 2, 'In Igbo it is called mmanya nkwu.', 'https://en.wikipedia.org/wiki/Palm_wine', 'live'),
  ('10dd4bb4-46c0-53d6-a66c-48bd76df5db2', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Lafun'' is a swallow made from?', '["Cassava flour","Millet","Yam flour","Plantain flour"]'::jsonb, 0, 2, 'It is sometimes called white amala.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('a77c2658-e823-593b-ba8c-b247ccadaf57', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'In Nigerian slang, ''Congo meat'' refers to?', '["Bush rat","Chicken","Snail","Goat meat"]'::jsonb, 2, 2, 'Peppered snail is a party favourite.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('1f9a8e7f-2327-5f55-8dc9-eb41a7fcfc80', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kokoro is a crunchy snack made mainly from?', '["Beans","Plantain","Corn flour","Cassava"]'::jsonb, 2, 2, 'It is popular in Ogun and Lagos.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('e487d528-284c-532f-ad93-27977154bfe0', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ojojo is a fried snack made from which crop?', '["Cocoyam","Water yam","Beans","Plantain"]'::jsonb, 1, 2, 'It is like akara but made with grated water yam.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('863c42f2-4074-5a2a-8f9e-5ba3294d5b1e', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which city is famous for its local ''Abakaliki rice''?', '["Abuja","Aba","Abeokuta","Abakaliki"]'::jsonb, 3, 2, 'Ebonyi State is a major rice producer.', 'https://en.wikipedia.org/wiki/Abakaliki', 'live'),
  ('8ad367d4-da74-5a9d-b1a1-a64fb38d3bfb', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Starch, eaten with banga soup in Delta, is made from?', '["Corn","Cassava","Yam","Rice"]'::jsonb, 1, 2, 'It is cooked with palm oil, giving it a yellow colour.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('5f8b9eb9-635e-5c4f-8e1e-07e95e4d4c1b', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Okpa is especially associated with which state?', '["Enugu","Lagos","Kano","Rivers"]'::jsonb, 0, 3, 'Nsukka is famous for its okpa sellers.', 'https://en.wikipedia.org/wiki/Okpa', 'live'),
  ('0fc9d2a1-d61f-50a5-810d-a23211eee747', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ofe akwu is an Igbo soup or stew made from?', '["Groundnuts","Okra","Melon seeds","Palm fruit"]'::jsonb, 3, 3, 'It is often eaten with white rice.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('a48fb9fb-8cbc-5e4d-8f24-635fa20c6c45', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Tuwo dawa is made from which grain?', '["Wheat","Sorghum (guinea corn)","Maize","Rice"]'::jsonb, 1, 3, 'Dawa is the Hausa word for sorghum.', 'https://en.wikipedia.org/wiki/Tuwo', 'live'),
  ('a4523436-c8fc-5b87-b1c1-81ee7a49f8b4', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Okra soup is called what in Yoruba?', '["Ewedu","Ila","Efo","Gbegiri"]'::jsonb, 1, 3, 'Ila alasepo is a richer version with assorted meat.', 'https://en.wikipedia.org/wiki/Okra_soup', 'live'),
  ('53b05b7e-5a2c-54e4-81af-1c335ff2d856', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Dodo Ikire, a snack of overripe plantain, comes from a town in which state?', '["Ondo","Ogun","Oyo","Osun"]'::jsonb, 3, 3, 'Ikire is on the Ibadan–Ife road.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('4fe97644-9435-5353-91f1-e02d834458f2', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Baba dudu is a Nigerian…', '["Bean soup","Dark caramel candy","Fried fish","Palm wine"]'::jsonb, 1, 3, 'Its name means ''black old man'' in Yoruba.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('68484e42-3603-59fb-bb8e-75e27ca6c7cd', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Pito is a traditional drink brewed from?', '["Sorghum or millet","Sugar cane","Palm sap","Cashew fruit"]'::jsonb, 0, 3, 'It is popular in the north and in Ghana.', 'https://en.wikipedia.org/wiki/Pito', 'live'),
  ('e52d9257-2f75-5865-be79-524ae666e2a6', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kaun (akanwu in Igbo) is used in cooking as a…', '["Preservative oil","Sweetener","Food colour","Softener and thickener (potash)"]'::jsonb, 3, 3, 'It is used in abacha and some soups.', 'https://en.wikipedia.org/wiki/Trona', 'live'),
  ('e0e0a860-a2fa-5f54-8848-fcaf57104445', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ogiri is a fermented seasoning made from?', '["Fish bones","Cassava peels","Melon or castor seeds","Milk"]'::jsonb, 2, 3, 'It has a very strong smell.', 'https://en.wikipedia.org/wiki/Ogiri', 'live'),
  ('d274c9d4-4b88-57a6-bf78-f1a3316da918', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Cameroon pepper is…', '["A leafy vegetable","A sweet bell pepper","A seed used in kunu","Dried, ground hot pepper"]'::jsonb, 3, 3, 'It gives pepper soup and suya extra heat.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('81a15087-cb68-5414-b701-e206ebd84e5a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Lake Rice was a joint rice brand of Lagos and which state?', '["Kano","Kebbi","Niger","Ebonyi"]'::jsonb, 1, 3, 'It was launched in 2015.', 'https://en.wikipedia.org/wiki/Lake_Rice', 'live'),
  ('978da252-0d82-56b0-8e87-ceb3d7865a01', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which state is known as Nigeria''s leading ginger producer?', '["Rivers","Lagos","Enugu","Kaduna"]'::jsonb, 3, 3, 'Southern Kaduna grows much of Nigeria''s ginger.', 'https://en.wikipedia.org/wiki/Ginger', 'live'),
  ('410cae9f-009e-5642-adaa-24b0a123cea5', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Palm oil is called what in Yoruba?', '["Epo oyinbo","Epo pupa","Mai ja","Mmanu"]'::jsonb, 1, 3, 'Pupa means red.', 'https://en.wikipedia.org/wiki/Palm_oil', 'live'),
  ('54fca814-c7aa-58f2-aeef-0c283f65382f', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Roughly how long did Hilda Baci''s record cooking marathon last?', '["About 24 hours","About 48 hours","About 150 hours","About 93 hours"]'::jsonb, 3, 3, 'Guinness confirmed 93 hours and 11 minutes.', 'https://en.wikipedia.org/wiki/Hilda_Baci', 'live'),
  ('5e24f81c-81b8-5320-abd7-808937abc82c', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Achi, ofo and akparata are used in Igbo soups as…', '["Meat substitutes","Thickeners","Garnishes","Sweeteners"]'::jsonb, 1, 3, 'Ofe owerri and oha soup often use them.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('f972353c-b054-5158-bab8-262f005c4d2a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Owo soup, eaten with starch or yam, is associated with which people?', '["Hausa","Kanuri","Tiv","Urhobo and Isoko"]'::jsonb, 3, 3, 'It is thickened with palm oil and potash.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('2eb50faf-410e-52f6-b12b-cb5b66bdbbab', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Edikang ikong''s two main leaves are fluted pumpkin and?', '["Scent leaf","Waterleaf","Uziza","Bitter leaf"]'::jsonb, 1, 3, 'It is a favourite of Efik and Ibibio cooks.', 'https://en.wikipedia.org/wiki/Edikang_ikong', 'live'),
  ('d0c3e1d0-ecda-5347-a090-40fb1ae3f50d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'In Hausa, groundnut soup is called?', '["Miyan gyada","Miyan zogale","Miyan taushe","Miyan kuka"]'::jsonb, 0, 3, 'It is often eaten with tuwo.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('07da5d05-ec8b-521e-98d6-eb5e8137c376', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Atama soup is a delicacy of which people?', '["Efik and Ibibio","Nupe","Yoruba","Kanuri"]'::jsonb, 0, 4, 'Atama leaves have a strong, aromatic taste.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('d9a762f0-48ee-5778-a947-97de5c2b35fa', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Moi moi was traditionally steamed in which kind of leaves?', '["Cocoyam leaves only","Bitter leaves","Banana leaves only","Thaumatococcus (uma) leaves"]'::jsonb, 3, 4, 'The leaves add a distinct aroma.', 'https://en.wikipedia.org/wiki/Moi_moi', 'live'),
  ('001b59d4-c6b5-5263-95e1-b433e14181ca', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Gurasa is a…', '["Fried fish","Millet drink","Northern flatbread","Bean soup"]'::jsonb, 2, 4, 'It is especially popular in Kano.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('941a2a4a-d756-5e05-9d84-a004f1538afa', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Kanwa (potash) is mined largely around which lake?', '["Lekki Lagoon","Lake Chad","Oguta Lake","Kainji Lake"]'::jsonb, 1, 4, 'It is traded across the north and south.', 'https://en.wikipedia.org/wiki/Trona', 'live'),
  ('c5b21f44-b537-562f-9055-6b8f5a454acd', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Iyan'' and ''amala'' are both swallows. What is amala made from that iyan is not?', '["Cassava","Fresh boiled yam","Dried yam flour","Rice"]'::jsonb, 2, 4, 'Iyan is pounded from fresh boiled yam.', 'https://en.wikipedia.org/wiki/Amala_(food)', 'live'),
  ('d1e8b1dc-57fc-51ed-a8d9-b21fe161a4a1', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which leafy vegetable is called ''efo shoko'' in Yoruba?', '["Lagos spinach (Celosia)","Waterleaf","Bitter leaf","Fluted pumpkin"]'::jsonb, 0, 4, 'It is often used in efo riro.', 'https://en.wikipedia.org/wiki/Celosia_argentea', 'live'),
  ('d388a3ef-2cb7-53ea-8c36-0a59a524411f', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which leafy vegetable is called ''efo tete'' in Yoruba?', '["Jute leaf","Moringa","Uziza","Amaranth"]'::jsonb, 3, 4, 'It is cooked like spinach.', 'https://en.wikipedia.org/wiki/Amaranth', 'live'),
  ('a9f0b17f-d1ae-5274-93fe-a507d3f8a523', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ofada stew is also popularly called?', '["Designer stew","Village stew","Red stew","Party stew"]'::jsonb, 0, 4, 'It uses green peppers and locust beans.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'in_review'),
  ('201498fc-eeff-53ae-b715-d729bd1adcbb', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'World Jollof Day is celebrated on which date?', '["12 June","1 October","14 February","22 August"]'::jsonb, 3, 4, 'Cooks across West Africa share their best jollof online.', 'https://en.wikipedia.org/wiki/Jollof_rice', 'in_review'),
  ('d01e22a1-7214-53b5-a127-b02321214864', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Alkubus is a northern Nigerian…', '["Steamed bread","Fried bean cake","Fermented drink","Grilled meat"]'::jsonb, 0, 4, 'It is often eaten with soup or sauce.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'in_review'),
  ('433d8ee0-8aad-5cff-8ace-ed277cf37352', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Robo is a Yoruba snack made by frying balls of?', '["Egusi paste","Cassava","Rice","Plantain"]'::jsonb, 0, 4, 'It is crunchy and often spiced with pepper.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'in_review'),
  ('3971e853-3a2c-5306-89c9-076b89b451fc', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Gwate is a northern Nigerian…', '["Porridge","Kebab","Bread","Soup thickener"]'::jsonb, 0, 4, 'It is often made with grains and vegetables.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'in_review'),
  ('9c8fe6ad-f780-5eb8-9b48-7b32d345e5ba', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Ghanaian jollof is often made with which kind of rice, unlike Nigerian jollof?', '["Parboiled long grain","Ofada","Jasmine or basmati","Brown rice"]'::jsonb, 2, 4, 'Nigerian cooks tend to use parboiled long-grain rice.', 'https://en.wikipedia.org/wiki/Jollof_rice', 'in_review'),
  ('27d30819-570f-5dde-8ea3-2d05751ed651', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The African star apple (agbalumo) has which scientific name?', '["Irvingia gabonensis","Garcinia kola","Chrysophyllum albidum","Dacryodes edulis"]'::jsonb, 2, 5, 'It is in season during the dry months.', 'https://en.wikipedia.org/wiki/Chrysophyllum_albidum', 'live'),
  ('4e7cfb79-eacb-501b-af65-84f89cdb22ea', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The African pear (ube) has which scientific name?', '["Chrysophyllum albidum","Dacryodes edulis","Treculia africana","Cola nitida"]'::jsonb, 1, 5, 'It is also called the safou in Central Africa.', 'https://en.wikipedia.org/wiki/Dacryodes_edulis', 'live'),
  ('54136ca9-1af6-52ef-af50-4afd1aca9bd2', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'African breadfruit (ukwa) has which scientific name?', '["Treculia africana","Parkia biglobosa","Artocarpus altilis","Irvingia gabonensis"]'::jsonb, 0, 5, 'Ukwa seeds are cooked into a rich porridge.', 'https://en.wikipedia.org/wiki/Treculia_africana', 'live'),
  ('46bf5e83-4bf1-5d01-850c-c5590b30e7f1', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Moringa (zogale) has which scientific name?', '["Vernonia amygdalina","Corchorus olitorius","Moringa oleifera","Talinum triangulare"]'::jsonb, 2, 5, 'It is nicknamed the ''miracle tree''.', 'https://en.wikipedia.org/wiki/Moringa_oleifera', 'live'),
  ('a8407541-cbbe-5730-9658-761eb716306a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Fluted pumpkin (ugu) has which scientific name?', '["Talinum triangulare","Telfairia occidentalis","Cucurbita pepo","Gongronema latifolium"]'::jsonb, 1, 5, 'Its seeds are also edible.', 'https://en.wikipedia.org/wiki/Telfairia_occidentalis', 'live'),
  ('a40ed02e-cb47-5c37-9dcb-305bb11b587b', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Utazi has which scientific name?', '["Piper guineense","Vernonia amygdalina","Ocimum gratissimum","Gongronema latifolium"]'::jsonb, 3, 5, 'It is a bitter-sweet climbing plant.', 'https://en.wikipedia.org/wiki/Gongronema_latifolium', 'live'),
  ('26fe8820-0227-501e-b83c-4deb8ced55ce', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Uziza has which scientific name?', '["Piper nigrum","Piper guineense","Aframomum melegueta","Xylopia aethiopica"]'::jsonb, 1, 5, 'It is also called West African black pepper.', 'https://en.wikipedia.org/wiki/Piper_guineense', 'live'),
  ('0772704f-82a7-56b4-bbf6-7b4060c69725', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Scent leaf (efirin/nchanwu) has which scientific name?', '["Vernonia amygdalina","Ocimum basilicum","Corchorus olitorius","Ocimum gratissimum"]'::jsonb, 3, 5, 'It is a type of basil.', 'https://en.wikipedia.org/wiki/Ocimum_gratissimum', 'live'),
  ('2b89ced8-7449-5a00-a2cb-ba43e7299a38', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The kola nut used at Igbo gatherings comes mainly from which species?', '["Coffea arabica","Garcinia kola","Cola acuminata","Cola gigantea"]'::jsonb, 2, 5, 'Cola nitida is the other main species.', 'https://en.wikipedia.org/wiki/Cola_acuminata', 'live'),
  ('683c9f01-b480-51ec-b3aa-0ec9a6e64001', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'The baobab, used for miyan kuka, has which scientific name?', '["Adansonia digitata","Parkia biglobosa","Vitellaria paradoxa","Tamarindus indica"]'::jsonb, 0, 5, 'Baobabs can live for over a thousand years.', 'https://en.wikipedia.org/wiki/Adansonia_digitata', 'live'),
  ('6ca578a7-bc80-58eb-9925-c7b98e7f39f8', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Tiger nuts, used in kunu aya, have which scientific name?', '["Cyperus esculentus","Vigna subterranea","Arachis hypogaea","Sesamum indicum"]'::jsonb, 0, 5, 'Despite the name, they are tubers, not nuts.', 'https://en.wikipedia.org/wiki/Cyperus_esculentus', 'live'),
  ('90abc73e-526e-5a5d-9818-a8b7ad72fd45', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Bambara nut, used in okpa, has which scientific name?', '["Cajanus cajan","Vigna subterranea","Arachis hypogaea","Vigna unguiculata"]'::jsonb, 1, 5, 'It is named after the Bambara people of Mali.', 'https://en.wikipedia.org/wiki/Vigna_subterranea', 'live'),
  ('5091aec8-a587-5088-8168-49e26dfb1485', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Cowpea, the bean used for akara and moi moi, has which scientific name?', '["Vigna subterranea","Vigna unguiculata","Phaseolus vulgaris","Glycine max"]'::jsonb, 1, 5, 'Nigeria is the world''s largest cowpea producer.', 'https://en.wikipedia.org/wiki/Cowpea', 'live'),
  ('8448ce9d-7948-534c-aa7a-09c1d40aa6f0', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Aidan fruit, used in pepper soup, is called what in Yoruba?', '["Aridan","Uda","Iru","Ehuru"]'::jsonb, 0, 5, 'Its scientific name is Tetrapleura tetraptera.', 'https://en.wikipedia.org/wiki/Tetrapleura_tetraptera', 'in_review'),
  ('20e15d8e-a769-5ce3-8fc4-c4904a651981', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Which fruit is famously eaten with roasted groundnuts?', '["Mango","Banana","Pineapple","Orange"]'::jsonb, 1, 1, 'Banana and groundnut is a classic street snack.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('bbcd88fb-e61e-55d9-8a73-d665ecbe5c18', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Ewa'' means what in Yoruba?', '["Rice","Yam","Fish","Beans"]'::jsonb, 3, 2, 'Ewa agoyin is a famous Lagos bean dish.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('fea48da4-15b1-55ba-84aa-f35206bfcc7d', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Iṣu'' means what in Yoruba?', '["Beans","Pepper","Corn","Yam"]'::jsonb, 3, 2, 'Iyan (pounded yam) is made from iṣu.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('5fb69b86-16c7-5013-b407-1248997dd36a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Ji'' means what in Igbo?', '["Water","Fish","Yam","Rice"]'::jsonb, 2, 2, 'Iri Ji is the New Yam festival.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('cff49b85-7704-5c99-98af-d50db2dcf1e1', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Shinkafa'' means what in Hausa?', '["Beans","Yam","Millet","Rice"]'::jsonb, 3, 2, 'Tuwo shinkafa is a rice swallow.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('41fefd99-df79-59b8-a4a1-852ee70b55ee', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Nama'' means what in Hausa?', '["Milk","Meat","Salt","Fish"]'::jsonb, 1, 2, 'Dambun nama is shredded meat floss.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('dec8f91d-e892-511d-aa2a-ca697de51cc1', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Ẹja'' means what in Yoruba?', '["Snail","Fish","Chicken","Meat"]'::jsonb, 1, 2, 'Ẹja dindin means fried fish.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('ccef4440-668b-584c-a8a1-b3ec92495ab3', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Ẹran'' means what in Yoruba?', '["Bread","Egg","Meat","Fish"]'::jsonb, 2, 2, 'Ẹran dindin means fried meat.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('0bb9a30c-b95d-58ca-855d-d6764f81cfce', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Agwa'' means what in Igbo?', '["Rice","Beans","Corn","Yam"]'::jsonb, 1, 3, 'Agwa is often cooked with plantain.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('b50f9d7e-0f2f-5756-b439-44633458df6a', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Wake'' means what in Hausa?', '["Yam","Beans","Pepper","Rice"]'::jsonb, 1, 3, 'Dan wake are bean-flour dumplings.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('87fb6d88-b344-5b41-86b5-de8882ab88f1', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Doya'' means what in Hausa?', '["Millet","Cassava","Yam","Corn"]'::jsonb, 2, 3, 'Yam is grown widely in the Middle Belt.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('99fdf3b4-804c-5a86-a121-be26024f06df', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Azụ'' means what in Igbo?', '["Meat","Crab","Snail","Fish"]'::jsonb, 3, 3, 'Azụ is a key ingredient in many soups.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('55f8a98e-325d-551d-bd0b-23da1e055aad', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Anụ'' means what in Igbo?', '["Pepper","Oil","Meat","Fish"]'::jsonb, 2, 3, 'Anụ ọkụkọ means chicken meat.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('0410faf9-e601-59ab-9dcf-896460b9d53b', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Okazi (ukazi) is the Igbo name for which leaf?', '["Waterleaf","Scent leaf","Bitter leaf","Afang leaf"]'::jsonb, 3, 3, 'It is used in afang and okazi soups.', 'https://en.wikipedia.org/wiki/Gnetum_africanum', 'live'),
  ('7daf3315-c9ff-5ed2-8453-f4fbfba44e50', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Ìrẹsì'' means what in Yoruba?', '["Rice","Plantain","Yam","Beans"]'::jsonb, 0, 3, 'Ìrẹsì ọ̀fada is local Ofada rice.', 'https://en.wikipedia.org/wiki/Nigerian_cuisine', 'live'),
  ('088313bb-f8e4-5849-a080-dbbd3c709865', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', '''Moi moi elemi meje'' is moi moi with how many ''lives'' (fillings)?', '["Five","Ten","Three","Seven"]'::jsonb, 3, 4, 'Fillings can include egg, fish, corned beef and liver.', 'https://en.wikipedia.org/wiki/Moi_moi', 'in_review'),
  ('0b4ef39e-447f-571b-a784-7e95c48fcbcc', 'dc3ea6aa-2f43-51ab-ac95-33cd1210b7ef', 'Palm kernel oil is called what in Yoruba?', '["Epo pupa","Òróró","Àdín","Ọ̀rí"]'::jsonb, 2, 4, 'It is dark and strong-smelling.', 'https://en.wikipedia.org/wiki/Palm_kernel_oil', 'in_review'),
  ('a6870eec-54d1-53d3-8d39-5d175f8f28ee', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''wahala'' mean?', '["Friend","Money","Trouble","Food"]'::jsonb, 2, 1, '''No wahala'' means ''no problem''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('9c5de913-8eb1-5caf-a620-fb1f801ce318', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''abeg'' mean?', '["Hurry","Thank you","Go away","Please"]'::jsonb, 3, 1, 'It comes from ''I beg''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('569a8bcc-0dce-5a7e-a3c8-b40ea7231b93', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The Pidgin greeting ''How far?'' means?', '["How are you?","Where are you going?","How long is the journey?","How much?"]'::jsonb, 0, 1, 'A common reply is ''I dey''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('7957552d-efb8-559b-8a20-9a9368f07e9d', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''wetin'' mean?', '["When","What","Where","Who"]'::jsonb, 1, 1, '''Wetin dey happen?'' means ''What''s going on?''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('8f120795-7083-577a-ac34-142037083e10', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''chop'' mean?', '["Sleep","Dance","Cut","Eat"]'::jsonb, 3, 1, '''Chop money'' is money for food and upkeep.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('1ce1e7f5-eb88-5d4d-989d-0803eb023cf2', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what is a ''pikin''?', '["A child","A small bag","A taxi","A pickaxe"]'::jsonb, 0, 1, 'The word likely comes from Portuguese ''pequeno'', meaning small.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('8247ec2c-00d4-5db4-bd5e-70ca01df653e', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''comot'' mean?', '["Come back","Hold on","Leave or get out","Sit down"]'::jsonb, 2, 1, '''Comot for road!'' means ''Get out of the way!''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('3f5d3859-edfd-5742-917b-85de9b58ed24', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Who is an ''oyibo'' in Nigerian slang?', '["A rich uncle","A taxi driver","A white or foreign person","A police officer"]'::jsonb, 2, 1, 'The word comes from Yoruba ''oyinbo''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('5a976ab3-0775-5302-8c6d-0569dd600338', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''I dey come'' in Pidgin means?', '["Come with me","I''m not coming","I''m coming (I''ll be right back)","I came yesterday"]'::jsonb, 2, 1, 'It is famously used even when someone will take a while.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('4d187818-ce4b-5d60-b1a3-44b14ad58b67', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''sabi'' mean?', '["To know","To sell","To sleep","To save"]'::jsonb, 0, 1, '''I no sabi'' means ''I don''t know''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('f4ef061d-c6bb-5e81-bf31-e9c7c28e081c', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''Na so'' means?', '["Say it again","Not like that","Be quiet","That''s how it is"]'::jsonb, 3, 1, 'It is often used to agree with someone.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('41a206b0-efc9-53ce-ac7e-759b87a41e15', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''una'' means?', '["Us","You (plural)","One","Them"]'::jsonb, 1, 1, '''How una dey?'' means ''How are you all?''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('9a32b999-ae5d-55a3-9038-dceee892e697', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Japa'' became popular slang for what?', '["Getting married","Winning the lottery","Emigrating abroad","Running a business"]'::jsonb, 2, 1, 'It comes from a Yoruba word meaning to run away.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('5f165b92-3d8f-56df-8baf-8f8650871291', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''sharp sharp'' means?', '["Carefully","Later","Sharply dressed","Quickly"]'::jsonb, 3, 1, '''Do am sharp sharp!'' means ''Do it fast!''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('86a0b0c3-f988-50ec-9d00-ae502719bd04', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Who is your ''oga''?', '["Your driver","Your younger sibling","Your neighbour","Your boss"]'::jsonb, 3, 1, 'The word comes from Yoruba.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('4d3e213b-c503-5140-97ee-cd7475e32b32', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, what is ''gist''?', '["A punch","Chit-chat or news","A meal","A gift"]'::jsonb, 1, 1, '''Give me gist'' means ''Tell me the latest''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('5ffc7788-a9f4-577c-abca-b8ac5d4f91d2', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Who is an ''amebo''?', '["A singer","A thief","A gossip","A cook"]'::jsonb, 2, 1, 'The name comes from a gossipy character in NTA''s The Village Headmaster.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('1ce7d6c9-a8db-5ec2-b0ea-8267d93a927b', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''sapa'' mean in Nigerian slang?', '["Being sick","Being broke","Being in love","Being rich"]'::jsonb, 1, 1, 'Many say ''sapa'' hits hardest in January.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('c720e774-4a10-5ac8-9619-f65f81d31460', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''Shine your eye'' means?', '["Go to sleep","Clean your face","Be alert","Look at the sun"]'::jsonb, 2, 1, 'It''s advice to stay smart and watchful.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('f9118e47-17fe-5ed2-89a8-ddbb58b2762e', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''abi?'' at the end of a sentence means?', '["Right? / Isn''t it?","Never","Goodbye","Maybe"]'::jsonb, 0, 1, 'It is a tag question borrowed from Yoruba.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('20ea9568-27d1-5f97-92d8-2652aff06341', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''go-slow'' means?', '["A lazy person","A traffic jam","A slow song","A tortoise"]'::jsonb, 1, 1, 'Lagos go-slow is legendary.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('45083ebd-e112-53ab-aca0-4013a3741083', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''small small'' means?', '["Very small","Little by little","Too small","Children"]'::jsonb, 1, 1, '''Small small, we go reach'' means ''Bit by bit, we''ll get there''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('4f92aeab-fd72-5b6e-83a5-fe1b5aad9ab3', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''No vex'' mean?', '["Don''t go","Don''t worry","No money","Sorry, don''t be angry"]'::jsonb, 3, 1, '''Vex'' means to be angry.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('1de644eb-5c2e-57af-8171-f304e232a96d', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''Oya!'' means?', '["Ouch!","Thank you!","Stop!","Come on! / Let''s go!"]'::jsonb, 3, 1, 'It is used to hurry someone along.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('1dd50192-33b2-59ba-a69a-b1a8bdbfc2ae', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does the exclamation ''Omo!'' usually express?', '["Hunger","Surprise or ''Wow!''","Sadness only","Goodbye"]'::jsonb, 1, 1, 'In Yoruba, ''omo'' also means ''child''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('ae14e990-ddac-5b78-bc85-9bf03a9c2c58', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''I no fit'' means?', '["I''m not fit","I''m full","I don''t want","I can''t"]'::jsonb, 3, 1, '''Fit'' means ''can'' in Pidgin.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('b7878a74-2eb6-5276-9828-b1c5240c6b7b', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''waka'' mean?', '["Walk","Wake","Work","Wash"]'::jsonb, 0, 1, 'A ''waka-pass'' is a passer-by.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('5adf1036-e3d4-5546-9bd1-360799f9bc8c', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''Gbam!'' means?', '["Exactly!","Run!","Never!","Ouch!"]'::jsonb, 0, 1, 'It is said to agree strongly with a point.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('c07244ee-804f-5721-bac0-3f6e907a6a0b', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Nigerian Pidgin is mainly based on which language?', '["Hausa","French","Portuguese","English"]'::jsonb, 3, 1, 'It also borrows from Yoruba, Igbo, Hausa and Portuguese.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('b67041ec-b2d3-5129-8439-ce1227588858', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Detty December'' refers to?', '["A rainy month","The party-packed festive season","A cleaning campaign","End-of-year exams"]'::jsonb, 1, 1, 'Many diaspora Nigerians fly home for it.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('7a0cd1b2-7294-5dc0-8f32-48f3b733088b', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''E no easy'' means?', '["It''s not ready","It isn''t easy","It''s not nice","It''s very easy"]'::jsonb, 1, 1, 'It''s a common sigh about tough times.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('c4d5f946-a44b-591b-bfe7-bd861de4c00e', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, who is an ''ajebutter'' (ajebota)?', '["A bus conductor","A butter seller","Someone from a privileged background","A street fighter"]'::jsonb, 2, 2, 'The opposite is ''ajepako''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('6f7ff00d-29e1-5dae-b4f1-901a1eb219a2', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''shakara'' mean in Nigerian slang?', '["Shaking with fear","Dancing at a party","Showing off or playing hard to get","Telling lies"]'::jsonb, 2, 2, '''Na only shakara you sabi!''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('8d3a4ecb-1ae3-50cd-b453-e043dcaa8b88', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''Jand'' refers to?', '["The United Kingdom","The USA","Lagos Island","Ghana"]'::jsonb, 0, 2, '''Yankee'' is slang for the USA.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('e6bee283-9433-5855-9613-56cae4faffdb', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''Yankee'' refers to?', '["Canada","Jamaica","The United States","The UK"]'::jsonb, 2, 2, '''Jand'' is slang for the UK.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('19a0e7c9-544a-59e6-b431-2abc967723f3', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, what does ''mumu'' mean?', '["A sweet","A fool","A mother","A dumpling"]'::jsonb, 1, 2, '''No be mumu I be!'' means ''I''m not a fool!''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('928c531c-006a-5d89-9cd3-09e546f40b8c', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''ginger'' mean as a verb in Nigerian slang?', '["To slow down","To insult","To hype up or motivate","To spice food"]'::jsonb, 2, 2, '''Dis song dey ginger me!''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('8f7bcc23-da90-5283-a4be-d23b10f50ecf', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''carry go'' means?', '["Stop","Take it away","Carry a load","Go ahead, proceed"]'::jsonb, 3, 2, 'A driver might hear ''Carry go!'' to move on.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('c1e497b7-a11b-58d4-8852-458ce02ca62d', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The expression ''Na wa o!'' expresses?', '["Surprise or exasperation","Hunger","Agreement","Happiness"]'::jsonb, 0, 2, '''Na wa for you!'' means ''You''re something else!''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('7fcc0597-4a59-51b9-88c1-d0eda1a44ad5', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The Igbo-derived exclamation ''Chai!'' expresses?', '["Joy","Agreement","Hunger","Shock or dismay"]'::jsonb, 3, 2, 'It is used across Nigeria.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('2d9a534a-e6f3-5ead-bff5-b938154fe72e', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The exclamation ''Haba!'' means roughly?', '["Thank you!","Hurray!","Run!","Come on! / Really?"]'::jsonb, 3, 2, 'It comes from Hausa.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('c2f78944-60c9-5f78-a77c-c1b9d39bdb48', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''419'' refers to?', '["A radio station","A bus route","A football score","Advance-fee fraud"]'::jsonb, 3, 2, 'It comes from Section 419 of Nigeria''s Criminal Code.', 'https://en.wikipedia.org/wiki/Advance-fee_scam', 'live'),
  ('ff74c446-fd3e-5601-9466-7cdbf1463edb', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'A ''yahoo boy'' is slang for?', '["A newspaper seller","An internet fraudster","A tech engineer","A footballer"]'::jsonb, 1, 2, 'The name comes from early Yahoo email scams.', 'https://en.wikipedia.org/wiki/Yahoo_Boys', 'live'),
  ('fde7cbb0-3511-5817-8bd2-6fb4bbf8d401', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What is an ''owambe''?', '["A street fight","A lavish party","A school exam","A local drink"]'::jsonb, 1, 2, 'Owambe parties feature aso ebi and live bands.', 'https://en.wikipedia.org/wiki/Owambe', 'live'),
  ('1fad1abf-bb1d-50ce-9618-827eb7dc2be1', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''soft life'' means?', '["A soft drink","A quiet street","A weak person","An easy, comfortable lifestyle"]'::jsonb, 3, 2, 'Social media is full of ''soft life'' posts.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('469fbd6c-d7d1-5968-9c86-259c98d4a0a1', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In relationship slang, to be ''served breakfast'' means?', '["To be promoted","To be dumped","To be proposed to","To be fed"]'::jsonb, 1, 2, 'A ''breakfast'' song is a heartbreak song.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('05a4656f-cea7-56e4-8a1f-c2ea6466c41f', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''dash'' means?', '["To run fast","To give as a gift","To break","To lose"]'::jsonb, 1, 2, 'A ''dash'' can also mean a tip or a bribe.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('d42b7f77-641a-5674-b40e-edcb42a4531b', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''belle'' means?', '["Bell","Bill","Beauty","Stomach"]'::jsonb, 3, 2, '''She get belle'' means ''She is pregnant''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('b549312b-a751-5855-a300-ddc0ac9df96c', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''I don chop'' means?', '["I am cutting","I have eaten","I will eat","I am hungry"]'::jsonb, 1, 2, '''Don'' marks something already done.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('e0b87041-8234-5282-97b3-3e781e94bc77', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''taya'' means?', '["To shout","To be tired or fed up","To dress up","A car tyre only"]'::jsonb, 1, 2, '''I don taya for this matter!''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('1928448c-0938-5773-8fdd-94f83dd114ad', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''yeye'' mean in Nigerian slang?', '["Useless or nonsense","Very good","Yes yes","Mother"]'::jsonb, 0, 2, '''Yeye dey smell'' is a classic Pidgin saying.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('2a073ff1-99de-56ec-a485-43ca3f5bce02', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Who is an ''agbero''?', '["A motor-park tout","A palm-wine tapper","A traditional ruler","A wrestler"]'::jsonb, 0, 2, 'Agberos collect fees from bus drivers.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('e70a370c-0d5c-5516-b164-4257be4471bf', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Who are ''area boys''?', '["Football fans only","School prefects","Neighbourhood guards","Street touts and loiterers"]'::jsonb, 3, 2, 'The term is strongly linked with Lagos.', 'https://en.wikipedia.org/wiki/Area_boys', 'live'),
  ('6b1dc901-8866-58c8-9a36-f46882d59640', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''Odogwu'' mean?', '["A young child","A trader","A coward","A champion or strong man"]'::jsonb, 3, 2, 'Burna Boy uses Odogwu as a nickname.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('20aa0e97-5300-5b5f-be33-9666ca2f24e7', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''bad belle'' means?', '["Envy or jealousy","A stomach ache","Bad food","Pregnancy"]'::jsonb, 0, 2, '''Bad belle people'' can''t stand your success.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('68146ddf-bedd-5b8b-ba62-1f7806149ebd', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''village people'' refers to?', '["A music group","Imagined forces holding someone back","Rural farmers","Old relatives"]'::jsonb, 1, 2, 'It is often used jokingly when things go wrong.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('39bb4b39-2807-5245-bee8-3489bea16739', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''God when?'' mean in Nigerian slang?', '["''When will I get mine?'' when admiring someone''s blessing","A curse","A question about church time","A prayer request"]'::jsonb, 0, 2, 'It''s a playful reaction to someone else''s good news.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('7af87eba-581d-52cd-98e3-9f309853ca11', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Tokunbo'' describes goods that are?', '["Brand new","Locally made","Imported and second-hand","Stolen"]'::jsonb, 2, 2, '''Tokunbo cars'' are fairly-used imports.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('3788eda9-c36e-5b1c-9181-5806d2a899d9', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''No be small thing'' means?', '["It''s tiny","It''s not mine","It''s a big deal","It''s not ready"]'::jsonb, 2, 2, 'Used to praise an achievement.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('352fb73c-9071-53f1-8750-305af33c8dca', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Yoruba-flavoured slang, ''Oshey!'' means?', '["Hurry up!","Goodbye!","Shut up!","Well done / Thanks!"]'::jsonb, 3, 2, 'From Yoruba ''o se'', thank you.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('3ed2ac9c-aaad-5bd9-ac5f-b0ace6c92f08', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''sha'' means roughly?', '["Anyway","Never","Before","Very"]'::jsonb, 0, 2, '''I go come sha'' means ''I''ll come anyway''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('d88a1e4e-4d8b-5c76-b457-dbb2ba0c61e0', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'A ''bobo'' in Nigerian slang is?', '["A baby","A bus","A dog","A guy or boyfriend"]'::jsonb, 3, 2, '''Na my bobo be dat!''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('e9207423-448a-5d8b-bd08-5dd0fe92e3eb', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The Lagos radio station Wazobia FM broadcasts mainly in?', '["French","Yoruba","Pidgin","Igbo"]'::jsonb, 2, 2, 'It launched in 2007.', 'https://en.wikipedia.org/wiki/Wazobia_FM', 'live'),
  ('127112f2-357b-589e-b8dc-f420f6e39112', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Wazobia'' combines the word for ''come'' in which three languages?', '["Pidgin, English and French","Edo, Fulfulde and Kanuri","Yoruba, Hausa and Igbo","Efik, Tiv and Ijaw"]'::jsonb, 2, 2, 'Wa (Yoruba), zo (Hausa), bia (Igbo).', 'https://en.wikipedia.org/wiki/Wazobia', 'live'),
  ('688f5b04-586d-5f51-b1b3-85a84895db07', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''chop money'' is?', '["Money for a wedding","Money for food and upkeep","Money from betting","Money for school fees"]'::jsonb, 1, 2, 'It is usually a regular household allowance.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('ea11857c-4fb3-55e1-9913-54b7d9f78b7b', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The Pidgin phrase ''Wetin concern me?'' means?', '["Why should it matter to me?","What do I owe?","Where am I?","What''s wrong with me?"]'::jsonb, 0, 2, 'It''s how you stay out of other people''s business.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('2cddc01b-3aff-595e-b7e3-0210de9b279d', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''kpatakpata'' means?', '["Soon","At all / completely","Quickly","Never again"]'::jsonb, 1, 3, '''I no get money kpatakpata!''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('9d2b447f-208d-520e-bb57-e57ce5cfcf04', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Who is an ''ajepako''?', '["A carpenter","Someone from a tough, humble background","A rice farmer","A rich kid"]'::jsonb, 1, 3, 'The opposite of an ''ajebutter''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('4542a7ef-55fb-5883-bfab-510d7b1417b8', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''ode'' means?', '["A poem","A hunter","A fool","A street"]'::jsonb, 2, 3, 'It comes from Yoruba.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('961c84e7-2bff-502c-b58e-7c00e76db3ea', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''wayo'' means?', '["Trickery or cunning","Wisdom","A long road","Weather"]'::jsonb, 0, 3, '''Na wayo dem take collect am.''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('61f93d3c-7a93-5f69-970c-13793aba58d3', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''gbedu'' mean in Nigerian slang?', '["Music or a party jam","A fight","Fried yam","A boat"]'::jsonb, 0, 3, '''The gbedu is loud!''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('a037ab4a-a8f0-5b9c-a042-872121683dc8', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''shayo'' mean?', '["Drinking alcohol","Shaking hands","Shopping","Singing loudly"]'::jsonb, 0, 3, '''Shayo'' was popularised by street-pop songs.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('8dcb1b8a-8542-5ed6-a038-3337adb4f8b6', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin slang, to ''pepper dem'' means?', '["To fight someone","To apologise","To make rivals jealous by showing success","To cook spicy food"]'::jsonb, 2, 3, 'BBNaija''s 2019 season was titled ''Pepper Dem''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('496c57a2-67d0-5436-a616-02258397cca7', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''He don kolo'' means he has?', '["Fallen asleep","Got married","Gone crazy","Become rich"]'::jsonb, 2, 3, 'A ''kolo'' is also a savings box.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('8fe36272-b025-5ce5-b2fe-8ee4b3f70765', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''gbese'' mean?', '["Debt or trouble","A dance","A gift","Wealth"]'::jsonb, 0, 3, '''Who go pay this gbese?''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('ef310c01-397a-5e99-915b-340ea4193a98', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''ojoro'' mean in Nigerian slang?', '["A queue","A party","Rain","Cheating"]'::jsonb, 3, 3, '''No ojoro!'' means ''No cheating!''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('ccc72944-72f4-571b-8d35-841d4b2f46ad', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''K-leg'' means?', '["A kick","Something has gone wrong or looks suspicious","A lucky break","Bow legs"]'::jsonb, 1, 3, '''This deal get K-leg.''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('c8b6c4a5-187a-5c8f-b689-4d8dcccbee08', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''I no get shishi'' means?', '["I''m not sure","I''m not shy","I have no shoes","I have no money at all"]'::jsonb, 3, 3, '''Shishi'' means a tiny amount of money.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('192b8de3-551d-550c-b4a5-6fe9d020ea95', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''tush'' means?', '["Late","Classy or posh","Rough","Cheap"]'::jsonb, 1, 3, '''This place too tush!''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('aa3dd057-c4b0-5d32-987f-146e4454ef02', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Eko o ni baje'' is a slogan meaning?', '["Lagos never sleeps","Lagos is crowded","Lagos will not be spoiled","Lagos belongs to us"]'::jsonb, 2, 3, 'It is a rallying cry for Lagosians.', 'https://en.wikipedia.org/wiki/Lagos', 'live'),
  ('b4b173ca-8d3c-5ebe-beff-40448d1528d9', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Monkey dey work, baboon dey chop'' means?', '["One person labours while another enjoys the profit","Animals are hungry","Avoid the forest","Work hard and eat well"]'::jsonb, 0, 3, 'It''s a complaint about unfair rewards.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('35ed003e-16de-5681-ba4d-3420a192fb4a', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Na condition make crayfish bend'' means?', '["Cook crayfish carefully","Circumstances force people into situations","Crayfish are naturally bent","Be patient"]'::jsonb, 1, 3, 'A classic Pidgin proverb.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('4bbef07b-b09f-5689-b31f-a672589a8c03', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''gobe'' means?', '["A plate of food","A joke","A goat","Trouble or a scandal"]'::jsonb, 3, 3, 'BBNaija''s 2017 season was titled ''See Gobbe''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('6dd0c815-6778-51cc-911f-492b901d219f', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''E don cast'' means?', '["It has been thrown away","It''s been cast in a film","The secret is out","It''s broken"]'::jsonb, 2, 3, 'Said when hidden information leaks.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('8794cc0a-908f-52b5-b423-463898b24906', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Who is a ''sabi-sabi''?', '["A know-it-all","A wise elder","A fortune teller","A teacher"]'::jsonb, 0, 3, '''Over-sabi'' is similar.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('28c3e21b-c784-549c-bd99-e4e5f3ba0a01', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Do me I do you'' means?', '["I love you","Let''s work together","Tit for tat","Do it for me"]'::jsonb, 2, 3, 'It warns that bad deeds get repaid.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('82caca05-8eda-584c-bbe0-9361dc2192ab', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''whine'' (as in ''You dey whine me?'') means?', '["To dance","To fool or deceive","To drink","To complain"]'::jsonb, 1, 3, '''Stop to dey whine me!''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('5bd5380d-2987-5a6f-8840-39fbe97d23af', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Yawa don gas'' means?', '["The party has started","We are on time","The gas is finished","Things have gone badly wrong"]'::jsonb, 3, 3, '''Yawa'' means trouble or embarrassment.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('3352399e-756c-5346-8962-f7874eee9a1b', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Jaiye'' in Nigerian slang refers to?', '["Enjoying life","Fighting","Fasting","Working hard"]'::jsonb, 0, 3, 'A ''jaiye-jaiye'' person loves parties.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('dd87993f-fe5a-57b3-9c07-c406e517e183', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Na today?'' in Pidgin means?', '["Is it today?","Not today","This isn''t new","Do it today"]'::jsonb, 2, 3, 'It means something has been happening for a long time.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('454e9655-e6cf-5156-8a79-806b452ef109', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In which year did the BBC launch its Pidgin-language service?', '["2005","2010","2021","2017"]'::jsonb, 3, 3, 'It is aimed at West and Central African audiences.', 'https://en.wikipedia.org/wiki/BBC_News_Pidgin', 'live'),
  ('291d82dd-1743-5481-96e7-c9ead8df15b2', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''gbas gbos'' refers to?', '["An exchange of blows or a heated quarrel","A drum beat","A loud laugh","A car horn"]'::jsonb, 0, 3, 'It mimics the sound of punches.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('8cc759c7-a5cc-5831-988c-69e11b7e7993', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Sef'' in ''Wetin sef?'' adds what?', '["Emphasis, like ''even''","A question about self","Politeness","A negative"]'::jsonb, 0, 3, '''Who sef send you?''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('74e41d8d-5c09-5508-af7a-337fd738af03', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''e choke'' means?', '["It''s too small","It''s overwhelming or amazing","It''s poisonous","It''s stuck"]'::jsonb, 1, 3, 'Often used about a big show or crowd.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('ebc25855-157d-5213-b34c-60f66026e1af', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Pidgin, ''kuku'' as in ''Make I kuku go'' means?', '["Just / might as well","Never","Slowly","Again"]'::jsonb, 0, 4, '''Make I kuku go'' means ''Let me just go''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('09d645e8-0f03-580b-bb17-5390d91b8a2f', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The Pidgin word ''sabi'' comes from which language?', '["French","Spanish","Dutch","Portuguese"]'::jsonb, 3, 4, 'It comes from Portuguese ''saber'', to know.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('fb98d84f-e54e-599b-8d38-28a041116364', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The word ''palaver'' (trouble, talk) comes from which language?', '["Hausa","Arabic","Latin","Portuguese"]'::jsonb, 3, 4, 'Portuguese ''palavra'' means ''word''.', 'https://en.wikipedia.org/wiki/Palaver', 'live'),
  ('991607d8-8c0e-5f4b-9c1c-1ec17dbea7e3', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Wetin concern agbero with overload?'' means?', '["The bus is full","Pay the tout","Mind your own business","Who is driving?"]'::jsonb, 2, 4, 'Agberos don''t care how full the bus is — so why should you?', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('66a91d5a-b7a5-57b0-adfc-effa88dbd68a', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''If e no be Panadol, e no fit be like Panadol'' became a saying meaning?', '["Take your medicine","Buy local brands","Nothing compares to the original","Pain is temporary"]'::jsonb, 2, 4, 'It started as an advertising slogan.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('fc73648a-9e5f-56cd-b484-d67d6ce0f342', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Some linguists call Nigerian Pidgin by which name?', '["Wazobia","Broken Hausa","Krio","Naijá"]'::jsonb, 3, 4, 'Krio is the related creole of Sierra Leone.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('34daae40-effb-5419-95cc-fe7ae50c6a77', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Shey'' at the start of a Pidgin question means roughly?', '["Is it that…?","Never","Because","Tomorrow"]'::jsonb, 0, 4, '''Shey you go come?'' means ''Will you come?''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('e8d6dd98-6959-5d71-aa5e-55fc1d7327dd', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Who is a ''waka-pass''?', '["A tour guide","A traffic warden","A bus pass","A passer-by"]'::jsonb, 3, 4, 'Also used for someone who isn''t really involved.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('f38c1170-5590-5344-aa28-ab61cf7c43b5', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''gragra'' means?', '["Gravel","Aggressive bluster or showing force","Laughter","Grace"]'::jsonb, 1, 4, '''Na only gragra, no action.''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'in_review'),
  ('e7d54647-e7a0-5b05-93b1-f8a8b8c2c80c', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''kampe'' means?', '["Camp","Quiet","Strong, solid or fine","Broken"]'::jsonb, 2, 4, '''I dey kampe'' means ''I''m doing great''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'in_review'),
  ('8c09f8b4-2ae4-535f-b748-d4c1734aa225', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'In Nigerian slang, ''ogbonge'' means?', '["Huge","Lazy","Fake","Genuine or top-quality"]'::jsonb, 3, 4, '''Na ogbonge material be this.''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'in_review'),
  ('8b14f4ec-5a73-5f2e-9eb7-db8b3359e645', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'What does ''wotowoto'' mean?', '["Rotten","Very hot","Small amount","Plenty or in abundance"]'::jsonb, 3, 4, '''Food dey wotowoto for the party.''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'in_review'),
  ('d421edb6-a233-574e-9f6e-0de5adf12169', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'An ''Ajala traveller'' is someone who?', '["Never leaves home","Travels around a lot","Drives a bus","Sells travel tickets"]'::jsonb, 1, 4, 'It refers to a famous Nigerian globetrotter, Olabisi Ajala.', 'https://en.wikipedia.org/wiki/Olabisi_Ajala', 'in_review'),
  ('91d97f5c-668d-5d94-beab-fe20ff1c9b27', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'The Pidgin word ''pikin'' likely comes from which Portuguese word?', '["Pessoa","Piquete","Pequeno","Pai"]'::jsonb, 2, 5, 'Pequeno means ''small''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('a6be4cdc-d166-5202-9aab-0e5aedc9ae0b', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Roughly how many people use Nigerian Pidgin as a first or second language?', '["About 20 million","About 1 million","Over 100 million","About 5 million"]'::jsonb, 2, 5, 'It is one of the most widely spoken languages in Africa.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'live'),
  ('1d6a0fd4-c8b6-51e6-9314-d6c9b688efba', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', 'Nigerian Pidgin is most closely related to which Sierra Leonean creole?', '["Papiamento","Krio","Tok Pisin","Sango"]'::jsonb, 1, 5, 'Both grew out of West African English-based contact languages.', 'https://en.wikipedia.org/wiki/Krio_language', 'live'),
  ('d44a3487-53e9-5d93-8b24-1b82cd55459d', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Shege'' in northern Nigerian slang refers to?', '["A type of food","Hardship or suffering","A wedding","Good luck"]'::jsonb, 1, 5, '''I don see shege!'' means ''I''ve suffered!''.', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'in_review'),
  ('89b4b657-758a-56ae-9a9b-47d42055ff6d', 'dcd8395e-f583-5c23-af6e-51ccbb80276f', '''Yanga'' in Nigerian slang means?', '["Hunger","Anger","Showing off or pride","Shyness"]'::jsonb, 2, 5, '''Na yanga she dey form.''', 'https://en.wikipedia.org/wiki/Nigerian_Pidgin', 'in_review'),
  ('9ffcd43c-f0b0-5217-b787-f8772accf26f', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is Nigeria''s official language?', '["Yoruba","Pidgin","Hausa","English"]'::jsonb, 3, 1, 'Hausa, Yoruba and Igbo are the largest indigenous languages.', 'https://en.wikipedia.org/wiki/Languages_of_Nigeria', 'live'),
  ('eef40bf2-78a8-5d58-875b-49c8db1993d0', 'ec062750-dc53-5896-9199-43aec3f81085', 'Which three languages are Nigeria''s largest indigenous languages?', '["Hausa, Yoruba and Igbo","Fulfulde, Urhobo and Ibibio","Efik, Tiv and Ijaw","Edo, Nupe and Kanuri"]'::jsonb, 0, 1, 'Each has tens of millions of speakers.', 'https://en.wikipedia.org/wiki/Languages_of_Nigeria', 'live'),
  ('22331eff-eecc-5ba1-b37e-46f335f6ee12', 'ec062750-dc53-5896-9199-43aec3f81085', '''Ẹ kú àárọ̀'' (E kaaro) is a Yoruba greeting meaning?', '["Welcome","Goodbye","Good morning","Good night"]'::jsonb, 2, 1, 'Elders are greeted with a bow or prostration.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('ccc1ec12-5ba6-5aa8-8fc9-8413c2e0b306', 'ec062750-dc53-5896-9199-43aec3f81085', '''Kedu?'' is an Igbo greeting meaning?', '["Good night","How are you?","Come here","Thank you"]'::jsonb, 1, 1, 'A common reply is ''Ọ dị mma'' (It is fine).', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('17b9d407-b08f-5cee-8762-73333f508894', 'ec062750-dc53-5896-9199-43aec3f81085', '''Sannu'' is a Hausa word meaning?', '["Hello","Water","Sorry, I''m late","Goodbye"]'::jsonb, 0, 1, '''Sannu da zuwa'' means ''welcome''.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('349c05a4-5d7e-5964-9f52-f9fafc83fe69', 'ec062750-dc53-5896-9199-43aec3f81085', '''Nagode'' means what in Hausa?', '["I love you","Thank you","Good morning","Please"]'::jsonb, 1, 1, 'Hausa is widely spoken across northern Nigeria and Niger.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('7ce40609-ce4e-529b-a801-ffff74e01451', 'ec062750-dc53-5896-9199-43aec3f81085', '''Daalụ'' means what in Igbo?', '["Sorry","Thank you","Goodbye","Hello"]'::jsonb, 1, 1, 'You may also hear ''Imeela''.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('08143023-24cb-5e4b-b7c0-87b28c93be4e', 'ec062750-dc53-5896-9199-43aec3f81085', '''Ẹ ṣé'' (E se) means what in Yoruba?', '["Welcome","Thank you","Sorry","Hurry"]'::jsonb, 1, 1, '''Ẹ ṣé gan'' means ''thank you very much''.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('943fb8bd-c4fc-583f-91c2-e396bdb30125', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo word ''nne'' means?', '["Child","Father","Friend","Mother"]'::jsonb, 3, 1, '''Nna'' means father.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('6b29bc8d-e685-5cba-8d29-9baf4a730602', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba word ''ìyá'' means?', '["Grandmother","Mother","Sister","Wife"]'::jsonb, 1, 1, '''Bàbá'' means father.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('5e7c2fd3-48ee-56e0-a3d0-5fa6e273adbd', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo name ''Ngozi'' means?', '["Wealth","Beauty","Blessing","Peace"]'::jsonb, 2, 1, 'It is a popular name for girls.', 'https://en.wikipedia.org/wiki/Igbo_name', 'live'),
  ('d21a1acd-30fe-5ced-af0f-450c136a0c66', 'ec062750-dc53-5896-9199-43aec3f81085', 'Complete the proverb: ''When two elephants fight, it is the ___ that suffers.''', '["Grass","River","Hunter","Tree"]'::jsonb, 0, 1, 'It means ordinary people suffer when the powerful clash.', 'https://en.wikipedia.org/wiki/African_proverbs', 'live'),
  ('ed4bb6c7-69e6-5573-b261-a231c36cdae2', 'ec062750-dc53-5896-9199-43aec3f81085', 'Which saying means a whole community helps bring up children?', '["It takes a village to raise a child","Many hands make light work","Charity begins at home","Birds of a feather flock together"]'::jsonb, 0, 1, 'It is often described as an African proverb.', 'https://en.wikipedia.org/wiki/African_proverbs', 'live'),
  ('dbac7855-9df7-5c12-9fb6-6a79a04f8075', 'ec062750-dc53-5896-9199-43aec3f81085', 'Edo (Bini) is the main language of which state?', '["Delta","Ondo","Edo","Kogi"]'::jsonb, 2, 1, 'It is the language of the ancient Benin Kingdom.', 'https://en.wikipedia.org/wiki/Edo_language', 'live'),
  ('84bee6fb-b569-5d22-bd0e-d4882656efd9', 'ec062750-dc53-5896-9199-43aec3f81085', 'Which language is written with ''ẹ'', ''ọ'' and ''ṣ'' and uses tone marks?', '["Yoruba","Hausa","English","Pidgin"]'::jsonb, 0, 1, 'The dots under letters change the sound.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('14672a84-0730-5330-8d14-1c614462677b', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba name ''Ayọ̀dele'' means?', '["Born on a journey","Joy has come home","God is great","The king''s child"]'::jsonb, 1, 1, '''Ayọ̀'' means joy.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('dfc16de4-b4aa-5dd6-9f8c-22d4bccb77e7', 'ec062750-dc53-5896-9199-43aec3f81085', 'Among Yoruba twins, which name goes to the first-born?', '["Taiwo","Kehinde","Alaba","Idowu"]'::jsonb, 0, 1, 'Taiwo means ''taste the world''.', 'https://en.wikipedia.org/wiki/Taiwo_and_Kehinde', 'live'),
  ('be81715c-ff17-54fc-8d9b-49a7ad39074b', 'ec062750-dc53-5896-9199-43aec3f81085', '''Chukwu'' is the Igbo word for?', '["God (the Supreme Being)","Market","Sky","King"]'::jsonb, 0, 1, 'Many Igbo names start with ''Chukwu'' or ''Chi''.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('34ae1523-5859-5c8d-9315-9b382bcc3024', 'ec062750-dc53-5896-9199-43aec3f81085', 'Roughly how many languages are spoken in Nigeria?', '["About 30","About 100","About 50","Over 500"]'::jsonb, 3, 2, 'Nigeria is one of the most linguistically diverse countries in the world.', 'https://en.wikipedia.org/wiki/Languages_of_Nigeria', 'live'),
  ('c027befd-5e44-530a-a40f-ece6bfe683ae', 'ec062750-dc53-5896-9199-43aec3f81085', 'Among Yoruba twins, who is traditionally regarded as the elder?', '["Idowu","Taiwo","Both equally","Kehinde"]'::jsonb, 3, 2, 'Taiwo is sent first to ''taste the world'' for Kehinde.', 'https://en.wikipedia.org/wiki/Taiwo_and_Kehinde', 'live'),
  ('2e03ca8f-379e-50d7-9b43-7c04ceb99342', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba name ''Babatunde'' means?', '["Father''s gift","Father has returned","Father is great","Father''s joy"]'::jsonb, 1, 2, 'It is given to a boy born after a grandfather has died.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('b1f36bd6-70b7-5dcc-a38a-ef93a1caf82b', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba name ''Yetunde'' means?', '["Mother''s joy","Mother is great","Mother has returned","Mother''s crown"]'::jsonb, 2, 2, 'It is given to a girl born after a grandmother has died.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('5dfd2652-9f74-51f8-bbe7-dbdef397b48c', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba name ''Oluwafẹmi'' means?', '["God gave me joy","God loves me","God is king","God has done it"]'::jsonb, 1, 2, '''Fẹ'' means to love.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('b4bc6f1c-48a1-54cf-b3eb-13da2b40ea0b', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba name ''Oluwaseun'' means?', '["God has come","God is great","God''s gift","We thank God"]'::jsonb, 3, 2, 'It is often shortened to Seun.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('3b3b87ac-025d-5beb-b722-21935b82795f', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo name ''Chukwuemeka'' means?', '["God has done great things","God is love","God is my strength","God''s gift"]'::jsonb, 0, 2, 'It is often shortened to Emeka.', 'https://en.wikipedia.org/wiki/Igbo_name', 'live'),
  ('0224b0dd-d21a-58c5-a7ff-323108daaa8c', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo name ''Chiamaka'' means?', '["God is great","God is king","God is near","God is beautiful"]'::jsonb, 3, 2, 'It is often shortened to Amaka.', 'https://en.wikipedia.org/wiki/Igbo_name', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('444d6388-1cbc-58c8-9f7c-6e53abbc1ac3', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo name ''Adaeze'' means?', '["Princess (daughter of a king)","Beautiful woman","Market woman","First daughter"]'::jsonb, 0, 2, '''Eze'' means king.', 'https://en.wikipedia.org/wiki/Igbo_name', 'live'),
  ('03e88fa2-bc0f-5593-ad1b-7f487152ae0d', 'ec062750-dc53-5896-9199-43aec3f81085', 'How many days are in the traditional Igbo market week?', '["8","5","4","7"]'::jsonb, 2, 2, 'The days are Eke, Orie, Afọ and Nkwọ.', 'https://en.wikipedia.org/wiki/Igbo_calendar', 'live'),
  ('973c4e31-eaa1-5b60-899f-ccfb3ca37f7a', 'ec062750-dc53-5896-9199-43aec3f81085', '''Ndewo'' means what in Igbo?', '["Good night","Thank you","Sorry","Hello / Greetings"]'::jsonb, 3, 2, '''Ndewo'' is a polite greeting.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('6389fd12-5d9c-5a68-ab7d-62b68ce37308', 'ec062750-dc53-5896-9199-43aec3f81085', '''Ina kwana?'' is a Hausa morning greeting asking?', '["Have you eaten?","How did you sleep?","Where are you going?","How is work?"]'::jsonb, 1, 2, 'The reply is often ''Lafiya lau'' (very well).', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('12a7a440-d6b7-5920-9426-2f456edbe50c', 'ec062750-dc53-5896-9199-43aec3f81085', '''Ẹ káàsán'' is a Yoruba greeting for?', '["Good morning","Happy birthday","Good evening","Good afternoon"]'::jsonb, 3, 2, 'Yoruba has a greeting for almost every situation.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('37fe3a33-3b57-5cb5-86fd-bf55a1177aac', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Yoruba word for water?', '["Ruwa","Amu","Omi","Mmiri"]'::jsonb, 2, 2, 'In Igbo it''s ''mmiri'' and in Hausa ''ruwa''.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('127a0eb5-b94b-5aad-bf72-aab9e5f16d83', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Igbo word for water?', '["Ego","Omi","Mmiri","Ruwa"]'::jsonb, 2, 2, '''Mmiri'' also means rain.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('bb79e30d-2b24-5151-9749-77a3cebf8b20', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Hausa word for water?', '["Kudi","Mmiri","Ruwa","Omi"]'::jsonb, 2, 2, '''Ruwan sama'' means rain (water from the sky).', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('f9b504a4-ad0d-50fa-aef3-dff566117931', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Hausa word for money?', '["Owo","Ego","Ruwa","Kudi"]'::jsonb, 3, 2, 'In Igbo it''s ''ego''; in Yoruba ''owó''.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('1fe13bfe-f164-59c5-a742-af6490761f26', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Igbo word for money?', '["Owo","Ego","Nne","Kudi"]'::jsonb, 1, 2, '''Ego'' is also in names like Egobia.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('7f189c69-57f4-5476-8088-ae898ebfd5cc', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba proverb ''Ìwà l''ẹwà'' means?', '["Beauty is power","Patience is wealth","Silence is golden","Character is beauty"]'::jsonb, 3, 2, 'It teaches that good conduct matters more than looks.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('8121895d-b984-5c59-86cd-1e5836064faa', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo saying ''Egbe bere, ugo bere'' means?', '["Birds fly high","Do not trust birds","The eagle is king","Let the kite perch and let the eagle perch (live and let live)"]'::jsonb, 3, 2, 'Chinua Achebe often quoted it.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('3421b28b-e482-5bc1-9b9a-76c9292b25af', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo saying ''Igwe bụ ike'' means?', '["Iron is hard","The sky is wide","Unity is strength","The king is strong"]'::jsonb, 2, 2, 'Literally, ''the multitude is strength''.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('3730c59d-425c-535a-8371-33a782f2825d', 'ec062750-dc53-5896-9199-43aec3f81085', 'Complete Achebe''s proverb from Things Fall Apart: ''If a child washes his hands, he could eat with…''', '["Gods","Elders","Chiefs","Kings"]'::jsonb, 3, 2, 'It means hard work earns a young person respect.', 'https://en.wikipedia.org/wiki/Things_Fall_Apart', 'live'),
  ('8fbf38f5-1666-5a49-8b74-aeed7ce60422', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Tiv people are mainly found in which state?', '["Plateau","Benue","Kogi","Taraba"]'::jsonb, 1, 2, 'Tiv is one of the larger languages of the Middle Belt.', 'https://en.wikipedia.org/wiki/Tiv_people', 'live'),
  ('b77646bb-75bb-56e4-a7e0-2936e5a2f32c', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Kanuri people are mainly found in which state?', '["Kano","Borno","Kebbi","Sokoto"]'::jsonb, 1, 2, 'They are linked to the old Kanem-Bornu Empire.', 'https://en.wikipedia.org/wiki/Kanuri_people', 'live'),
  ('304e9b62-37c8-5287-a47b-c5509b923394', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Urhobo people are mainly found in which state?', '["Edo","Rivers","Delta","Bayelsa"]'::jsonb, 2, 2, 'Warri and Ughelli are in Urhobo-speaking areas.', 'https://en.wikipedia.org/wiki/Urhobo_people', 'live'),
  ('da02ddaf-5942-5a99-91d6-a7e155e3ece9', 'ec062750-dc53-5896-9199-43aec3f81085', 'Fulfulde is the language of which people?', '["Nupe","Kanuri","Hausa","Fulani"]'::jsonb, 3, 2, 'It is spoken across much of West Africa.', 'https://en.wikipedia.org/wiki/Fula_language', 'live'),
  ('58243fa5-a7f0-5b05-bc47-b10dd193eccf', 'ec062750-dc53-5896-9199-43aec3f81085', 'Efik is spoken mainly around which city?', '["Enugu","Uyo","Port Harcourt","Calabar"]'::jsonb, 3, 2, 'Efik was one of the first Nigerian languages to be written down by missionaries.', 'https://en.wikipedia.org/wiki/Efik_language', 'live'),
  ('32f8e69f-6826-5176-8a77-266b80b7da0d', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Ibibio people are mainly found in which state?', '["Abia","Rivers","Cross River","Akwa Ibom"]'::jsonb, 3, 2, 'Ibibio is closely related to Efik.', 'https://en.wikipedia.org/wiki/Ibibio_people', 'live'),
  ('bdab797a-1a42-5f42-be72-9f0df4aa8e32', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Ijaw people mainly live in which region?', '["The Sahel","The Mambilla Plateau","The Niger Delta","The Jos Plateau"]'::jsonb, 2, 2, 'Bayelsa State is largely Ijaw.', 'https://en.wikipedia.org/wiki/Ijaw_people', 'live'),
  ('37a90a6b-5d40-5e29-ab8d-c8a0b34f89b2', 'ec062750-dc53-5896-9199-43aec3f81085', 'Hausa is also a major language in which neighbouring country?', '["Cameroon","Benin","Niger","Ghana"]'::jsonb, 2, 2, 'It is one of Africa''s most widely spoken languages.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('8d30d7d1-c063-52bc-9e87-5e6bca8894d9', 'ec062750-dc53-5896-9199-43aec3f81085', 'Complete the proverb: ''No matter how long a log stays in the water, it doesn''t become a…''', '["Fish","Rock","Canoe","Crocodile"]'::jsonb, 3, 2, 'It means people don''t change their true nature.', 'https://en.wikipedia.org/wiki/African_proverbs', 'live'),
  ('0442779c-e77a-57b1-9e9a-e01100a093e3', 'ec062750-dc53-5896-9199-43aec3f81085', 'Complete the proverb: ''However long the night, the ___ will break.''', '["Day","Dawn","Silence","Rain"]'::jsonb, 1, 2, 'It means hard times don''t last forever.', 'https://en.wikipedia.org/wiki/African_proverbs', 'live'),
  ('281afffb-b6ac-55c0-b7c8-6b1da5d254a3', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Hausa proverb ''Idan kida ya canza, rawa ma ta canza'' means?', '["Dance until morning","When the music changes, so does the dance","Music is life","Never stop the drum"]'::jsonb, 1, 2, 'It means adapt to changing circumstances.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('032c35c8-a0cf-5ebd-abfc-284880322968', 'ec062750-dc53-5896-9199-43aec3f81085', 'Achebe wrote in Things Fall Apart that proverbs are the ___ with which words are eaten.', '["Palm oil","Honey","Salt","Pepper"]'::jsonb, 0, 3, 'The line describes how the Igbo value proverbs in conversation.', 'https://en.wikipedia.org/wiki/Things_Fall_Apart', 'live'),
  ('30dda770-73d9-518d-896f-e2e0e6c82749', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba proverb ''Ilé la ti ń kó ẹ̀ṣọ́ r''òde'' is like which English saying?', '["Charity begins at home","Don''t count your chickens","Home sweet home","Look before you leap"]'::jsonb, 0, 3, 'Literally: ''It is from home we carry beauty outside''.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('70423364-3da6-5c71-b501-c2d916d62a56', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba proverb about the frog becoming ''father of the soup'' when fish is absent means?', '["Frogs are tasty","Always cook with fish","Something second-best gains value when the best is missing","Fathers should cook"]'::jsonb, 2, 3, '''Àìsí ẹja, ọ̀pọ̀lọ́ ń jẹ́ bàbá ìsàsùn.''', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('4b1238fe-4b41-5e0b-ab76-d1371bb5efc8', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Hausa proverb ''Sannu sannu, bata hana zuwa'' means?', '["Hurry or you''ll be late","Greet everyone you meet","Slowly but surely, you will get there","Rest when you are tired"]'::jsonb, 2, 3, 'Literally: ''Slowly, slowly doesn''t stop arrival''.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('83feed77-4502-5148-b383-32110b1f73ad', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo saying ''Onye wetara ọjị, wetara ndụ'' means?', '["He who brings kola brings life","Respect your elders","Kola is bitter","Share your food"]'::jsonb, 0, 3, 'Kola nut is central to Igbo hospitality.', 'https://en.wikipedia.org/wiki/Kola_nut', 'live'),
  ('828bf0a5-c533-5df5-b9ad-017e18c3c18b', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo name and saying ''Ezi afa ka ego'' means?', '["Names are powerful","A good name is better than riches","Wealth comes from work","Money talks"]'::jsonb, 1, 3, 'It echoes a proverb found in many cultures.', 'https://en.wikipedia.org/wiki/Igbo_name', 'live'),
  ('8e7ef28b-179c-5845-ae5e-97a68cbf65b5', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo concept ''chi'' refers to?', '["A personal god or guardian spirit","A traditional dance","A type of yam","A market day"]'::jsonb, 0, 3, 'Achebe wrote that a man''s chi says yes when he says yes.', 'https://en.wikipedia.org/wiki/Odinani', 'live'),
  ('2bba5a16-2c49-5dd9-a3da-454e6bd376ae', 'ec062750-dc53-5896-9199-43aec3f81085', 'Which of these is an Igbo market day?', '["Ọjọ́ Àìkú","Sunday","Litinin","Nkwọ"]'::jsonb, 3, 3, 'The others are Eke, Orie and Afọ.', 'https://en.wikipedia.org/wiki/Igbo_calendar', 'live'),
  ('79c08535-ea70-58e3-aa48-2ea78d6526f2', 'ec062750-dc53-5896-9199-43aec3f81085', 'In Yoruba naming, ''Idowu'' is the name for?', '["A first son","A child born at a festival","A child born after twins","A child born feet first"]'::jsonb, 2, 3, 'The next child after Idowu is often called Alaba.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('1127465c-00bc-593f-bef3-fb61bd2fec0e', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba name ''Abiọ́dún'' means?', '["Born at night","Born on the road","Born during a festival","Born after twins"]'::jsonb, 2, 3, 'It is used for both boys and girls.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('ea784dac-0782-554b-955e-6b3e05de4772', 'ec062750-dc53-5896-9199-43aec3f81085', 'Yoruba is a tonal language with how many basic tones?', '["4","5","2","3"]'::jsonb, 3, 3, 'They are high, mid and low.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('20ba04c6-085e-5287-81db-ddb5a17b1b81', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''biyu'' in Hausa?', '["Ten","Two","One","Five"]'::jsonb, 1, 3, '''Daya'' is one and ''uku'' is three.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('7ba85a27-3973-54c3-8005-0afbf2c45075', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''otu'' in Igbo?', '["Ten","Two","One","Four"]'::jsonb, 2, 3, '''Abụọ'' is two and ''atọ'' is three.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('e5062e61-4797-5144-bef8-13c0ed3b8ad8', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''èjì'' in Yoruba?', '["Three","Nine","Two","Seven"]'::jsonb, 2, 3, '''Ọ̀kan'' is one and ''ẹ̀ta'' is three.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('1b4e9c0f-08e5-595c-b400-acb56577e064', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''goma'' in Hausa?', '["Ten","Hundred","Seven","Eight"]'::jsonb, 0, 3, '''Bakwai'' is seven.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('bda2fca4-a2a3-5301-ab6d-711e3fe945d5', 'ec062750-dc53-5896-9199-43aec3f81085', 'In ''Hausa Bakwai'', the seven original Hausa states, what does ''bakwai'' mean?', '["Original","Kingdom","Seven","Holy"]'::jsonb, 2, 3, 'The seven include Kano, Katsina, Daura and Zazzau.', 'https://en.wikipedia.org/wiki/Hausa_Kingdoms', 'live'),
  ('86aae215-2523-5e8b-ba74-731928f55d59', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Nupe people are mainly found in which state?', '["Plateau","Kogi","Niger","Kebbi"]'::jsonb, 2, 3, 'Bida is the centre of the Nupe kingdom.', 'https://en.wikipedia.org/wiki/Nupe_people', 'live'),
  ('87ae2958-5725-5b67-a09b-dacf470d0c54', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Ebira people are mainly found in which state?', '["Kwara","Benue","Kogi","Edo"]'::jsonb, 2, 3, 'Okene is the main Ebira town.', 'https://en.wikipedia.org/wiki/Ebira_people', 'live'),
  ('a2796b48-5c4a-5a61-ab73-fbb373556d90', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Itsekiri people are mainly found in which state?', '["Rivers","Edo","Delta","Ondo"]'::jsonb, 2, 3, 'Warri was the seat of the Itsekiri kingdom.', 'https://en.wikipedia.org/wiki/Itsekiri_people', 'live'),
  ('3228fd8b-edd7-50b1-8d8c-71f6f8724fe7', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Idoma people are mainly found in which state?', '["Plateau","Benue","Nasarawa","Enugu"]'::jsonb, 1, 3, 'Otukpo is the main Idoma town.', 'https://en.wikipedia.org/wiki/Idoma_people', 'live'),
  ('34dd51c3-5fea-5636-886a-f9a260697e41', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igala people are mainly found in which state?', '["Benue","Anambra","Kogi","Niger"]'::jsonb, 2, 3, 'The Attah of Igala is their traditional ruler.', 'https://en.wikipedia.org/wiki/Igala_people', 'live'),
  ('d0e43568-684f-50db-a371-67e0b11549e1', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Gbagyi (Gwari) people are among the original inhabitants of which area?', '["Kano","Lagos","The FCT (Abuja)","Calabar"]'::jsonb, 2, 3, 'Many were resettled when Abuja was built.', 'https://en.wikipedia.org/wiki/Gbagyi_people', 'live'),
  ('25e1ca53-642e-529d-be4d-0a7ee332b1f4', 'ec062750-dc53-5896-9199-43aec3f81085', 'Yoruba is widely spoken in which neighbouring country?', '["Cameroon","Niger","Chad","Benin"]'::jsonb, 3, 3, 'Yoruba is also spoken in Togo and by communities in Brazil and Cuba.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('19eefa21-b973-545b-b8c6-cf5d0afad4bd', 'ec062750-dc53-5896-9199-43aec3f81085', 'Complete the proverb: ''Until the lion learns to write, tales of the hunt will glorify the…''', '["Forest","Lion","Hunter","Village"]'::jsonb, 2, 3, 'Achebe used it to explain why Africans must tell their own stories.', 'https://en.wikipedia.org/wiki/Chinua_Achebe', 'live'),
  ('73aeb5e4-8947-585a-a37c-6fee3392b99c', 'ec062750-dc53-5896-9199-43aec3f81085', 'The proverb ''The fly that has no one to advise it follows the corpse into the grave'' warns against?', '["Travelling alone","Attending funerals","Eating carelessly","Ignoring good advice"]'::jsonb, 3, 3, 'It is a well-known Igbo proverb.', 'https://en.wikipedia.org/wiki/African_proverbs', 'live'),
  ('a8e91900-7e3b-53ff-8c33-7fdc812e2be8', 'ec062750-dc53-5896-9199-43aec3f81085', 'Complete the proverb: ''If you want to go fast, go alone; if you want to go far, go…''', '["Slowly","Early","Together","At night"]'::jsonb, 2, 3, 'It''s widely quoted as an African proverb about teamwork.', 'https://en.wikipedia.org/wiki/African_proverbs', 'live'),
  ('5154576c-df9e-56ba-91a8-cd335b766b5a', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo saying ''Onye aghala nwanne ya'' means?', '["Leave the past behind","Brothers fight","Do not abandon your brother","Every man for himself"]'::jsonb, 2, 3, 'It is a popular Igbo saying about loyalty to kin.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('f150fe53-2a57-54f3-a827-fc7ae42064cc', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''Ẹ kú ìrọ̀lẹ́'' in Yoruba?', '["Good evening","Happy new year","Well done at work","Good morning"]'::jsonb, 0, 3, 'Yoruba greetings change with the time of day.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('b13a1c64-e984-5700-b783-3f12c60482bb', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Hausa phrase ''Ba komai'' means?', '["Go away","I don''t know","There''s no food","It''s nothing / no problem"]'::jsonb, 3, 3, 'It''s a common reply to ''thank you''.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('b6cf3168-ee90-58b3-8652-d9e9b1eab3eb', 'ec062750-dc53-5896-9199-43aec3f81085', 'In Things Fall Apart, the lizard that jumped from the iroko tree said it would praise itself if no one else did. Who uses this proverb?', '["Ezinma","Unoka","Okonkwo","Obierika"]'::jsonb, 2, 4, 'Okonkwo says it when he praises himself in front of Nwakibie.', 'https://en.wikipedia.org/wiki/Things_Fall_Apart', 'in_review'),
  ('de3edffc-5435-59d4-bf98-47e2220c3017', 'ec062750-dc53-5896-9199-43aec3f81085', 'Complete Achebe''s proverb: ''A chick that will grow into a cock can be spotted the very day it…''', '["Eats","Flies","Hatches","Crows"]'::jsonb, 2, 4, 'It means greatness shows early.', 'https://en.wikipedia.org/wiki/Things_Fall_Apart', 'in_review'),
  ('4e67e71d-562e-5ce8-8ee0-879abe319c9c', 'ec062750-dc53-5896-9199-43aec3f81085', 'Hausa written in Arabic script is called?', '["Nsibidi","Tifinagh","Boko","Ajami"]'::jsonb, 3, 4, 'Ajami was used for centuries before the Latin alphabet.', 'https://en.wikipedia.org/wiki/Ajami_script', 'live'),
  ('b8db0029-5a17-576c-a635-f0eccb836b2c', 'ec062750-dc53-5896-9199-43aec3f81085', 'Hausa written in the Latin alphabet is called?', '["Nsibidi","Ajami","Romaji","Boko"]'::jsonb, 3, 4, 'Boko was introduced during colonial rule.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('0f5d2de0-cfaf-5883-a248-23909df2a7b8', 'ec062750-dc53-5896-9199-43aec3f81085', 'Nsibidi is an ancient system of symbols from which region?', '["Ile-Ife","Lake Chad","Kano","South-eastern Nigeria (Cross River area)"]'::jsonb, 3, 4, 'It was used by the Ekpe society among others.', 'https://en.wikipedia.org/wiki/Nsibidi', 'live'),
  ('76d930fb-09fd-5ba0-86f4-523d0b32b414', 'ec062750-dc53-5896-9199-43aec3f81085', 'In Yoruba naming, ''Ige'' is the name for a child born?', '["Feet first","After twins","With curly hair","On a market day"]'::jsonb, 0, 4, 'Yoruba names often describe the circumstances of birth.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('673a4094-48dc-59c8-8399-60c8f2bd350e', 'ec062750-dc53-5896-9199-43aec3f81085', 'In Yoruba naming, ''Dada'' is a name for a child born?', '["During rain","With naturally knotted or curly hair","After a long wait","Feet first"]'::jsonb, 1, 4, 'Dada is linked to a Yoruba deity.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('df89b1d5-b033-5d29-aac0-818ce3e0c80e', 'ec062750-dc53-5896-9199-43aec3f81085', 'In Yoruba naming, ''Alaba'' is the name for a child born after?', '["Idowu","Dada","Taiwo","Kehinde"]'::jsonb, 0, 4, 'The order goes Taiwo, Kehinde, Idowu, Alaba.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'live'),
  ('93a65b44-624e-5a4e-acac-516580b2f6a5', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''iri'' in Igbo?', '["Hundred","Eight","Ten","Three"]'::jsonb, 2, 4, '''Ise'' is five and ''asaa'' is seven.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('769501ea-2e2f-59d2-81fa-097cbfe02516', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''uku'' in Hausa?', '["Nine","Three","Four","Six"]'::jsonb, 1, 4, '''Hudu'' is four and ''biyar'' is five.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('354e8f89-6475-5472-8f33-5879bc179457', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''ẹ̀wá'' in Yoruba?', '["Twenty","Ten","Beans","Six"]'::jsonb, 1, 4, 'With a different tone, ''ẹ̀wà'' means beans.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('13def061-72cb-5020-967a-dee947de1b2b', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Berom people are mainly found in which state?', '["Plateau","Kaduna","Benue","Bauchi"]'::jsonb, 0, 4, 'Jos is in Berom land.', 'https://en.wikipedia.org/wiki/Berom_people', 'live'),
  ('f3ada035-8f7d-5085-95f7-9df4b7018876', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Jukun people are mainly found in which state?', '["Taraba","Borno","Gombe","Adamawa"]'::jsonb, 0, 4, 'Wukari is the seat of the Jukun kingdom.', 'https://en.wikipedia.org/wiki/Jukun_people', 'live'),
  ('33ecef64-996a-520f-bdb6-969fd96fd1c8', 'ec062750-dc53-5896-9199-43aec3f81085', 'Which Yoruba proverb is about an elder not standing by while a child''s headload tilts?', '["Àgbà kì í wà lọ́jà kí orí ọmọ títún wọ́","Ilé la ti ń kó ẹ̀ṣọ́ r''òde","Ọ̀rọ̀ púpọ̀ ò kún agbọ̀n","Ìwà l''ẹwà"]'::jsonb, 0, 4, 'It means elders must correct wrongs when they see them.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('fa93c826-2c0d-56c9-9155-78b4ad90b7b0', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Hausa proverb ''Hannu da yawa maganin kazamar miya'' is like which English saying?', '["Many hands make light work","Too many cooks spoil the broth","Clean as you go","Hunger is the best sauce"]'::jsonb, 0, 4, 'Literally: ''Many hands are the cure for a messy soup''.', 'https://en.wikipedia.org/wiki/Hausa_language', 'in_review'),
  ('6a47b6ae-9b98-558f-ab68-2c7bf55d7672', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba proverb ''Ọ̀rọ̀ púpọ̀ ò kún agbọ̀n'' means?', '["Baskets carry words","Many words don''t fill a basket (talk is cheap)","Silence is foolish","Speak loudly"]'::jsonb, 1, 4, 'It warns against empty promises.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'in_review'),
  ('a6f94ceb-178f-55f6-99c3-bc81dfe0980a', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo proverb about bringing ant-infested firewood home warns that you should not complain when what visits?', '["Rats","Snakes","Lizards","Visitors"]'::jsonb, 2, 4, 'It means accept the consequences of your choices.', 'https://en.wikipedia.org/wiki/African_proverbs', 'in_review'),
  ('1b5f1b73-8dc7-5398-9c58-628add61b32f', 'ec062750-dc53-5896-9199-43aec3f81085', 'Which Achebe novel''s title comes from a W. B. Yeats poem?', '["Arrow of God","A Man of the People","Things Fall Apart","Anthills of the Savannah"]'::jsonb, 2, 5, 'The poem is ''The Second Coming''.', 'https://en.wikipedia.org/wiki/Things_Fall_Apart', 'live'),
  ('7af34d32-8c15-54e5-bd52-85b70f33fed2', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''asaa'' in Igbo?', '["Eight","Six","Seven","Nine"]'::jsonb, 2, 5, '''Asatọ'' is eight.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('9935242c-fcae-5216-8ce4-8e0529e19106', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''bakwai'' in Hausa?', '["Six","Seven","Eight","Nine"]'::jsonb, 1, 5, '''Takwas'' is eight and ''tara'' is nine.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('15a23084-1a55-5be0-8aee-75c759e810b2', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is ''ẹ̀fà'' in Yoruba?', '["Four","Five","Eight","Six"]'::jsonb, 3, 5, '''Àrún'' is five.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('6995a077-4e6a-5e4d-883f-4bcedb0fcfc5', 'ec062750-dc53-5896-9199-43aec3f81085', 'Which Igbo market day is often considered the first of the week?', '["Afọ","Eke","Nkwọ","Orie"]'::jsonb, 1, 5, 'The order is Eke, Orie, Afọ, Nkwọ.', 'https://en.wikipedia.org/wiki/Igbo_calendar', 'in_review'),
  ('ebfb47a4-e5e9-52fb-8461-59338eaedca9', 'ec062750-dc53-5896-9199-43aec3f81085', 'In Yoruba naming, ''Ojo'' (boy) and ''Aina'' (girl) are names for a child born?', '["On a Sunday","After twins","Feet first","With the umbilical cord around the neck"]'::jsonb, 3, 5, 'Such children are believed to be special.', 'https://en.wikipedia.org/wiki/Yoruba_name', 'in_review'),
  ('017229bc-8487-503a-a01c-b61a620706d6', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Hausa proverb ''Komai nisan jifa, ƙasa za ta dawo'' means?', '["The earth is wide","Don''t travel far","However far a stone is thrown, it returns to the ground","Throw stones at enemies"]'::jsonb, 2, 5, 'It means everything returns to its origin.', 'https://en.wikipedia.org/wiki/Hausa_language', 'in_review'),
  ('62816670-5e76-5da5-8568-b6d96e4b221f', 'ec062750-dc53-5896-9199-43aec3f81085', 'Ubangiji is a Hausa word meaning?', '["Lord (God)","Teacher","Elder","King"]'::jsonb, 0, 5, 'Allah is also widely used among Hausa Muslims.', 'https://en.wikipedia.org/wiki/Hausa_language', 'in_review'),
  ('c0b19cbc-b3e8-5150-b6ae-bbff6968a26b', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Yoruba word for food?', '["Nri","Oúnjẹ","Abinci","Ẹja"]'::jsonb, 1, 2, 'In Igbo it''s ''nri'' and in Hausa ''abinci''.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('b1bb541f-0e96-5c51-b3f4-71aeb72e8575', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Igbo word for food?', '["Abinci","Nri","Ọja","Oúnjẹ"]'::jsonb, 1, 2, '''Nri'' is also a famous ancient Igbo kingdom.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('239eb421-6ae5-55e1-a447-15b08261a213', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Hausa word for food?', '["Oúnjẹ","Abinci","Nri","Kasuwa"]'::jsonb, 1, 2, '''Abinci'' is also used in Niger and Ghana''s Hausa communities.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('3e608d3d-077c-5f81-9ca1-9d7911d84098', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Yoruba word for friend?', '["Aboki","Enyi","Ẹ̀gbọ́n","Ọ̀rẹ́"]'::jsonb, 3, 2, '''Ọ̀rẹ́ mi'' means ''my friend''.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('1e721f7b-fa7a-56c2-801b-f410794a734e', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Igbo word for friend?', '["Nwanne","Aboki","Enyi","Ọ̀rẹ́"]'::jsonb, 2, 2, '''Enyi'' also means elephant, depending on tone.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('04c7b805-3ff9-588a-bc89-e3c580eb973d', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Hausa word for market?', '["Ọjà","Kasuwa","Makaranta","Ahịa"]'::jsonb, 1, 2, 'Kano''s Kurmi is one of the oldest kasuwa in West Africa.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('82769c03-3934-5774-bcdd-273001510dc9', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Yoruba word for market?', '["Ahịa","Ọjà","Kasuwa","Ilé"]'::jsonb, 1, 2, 'Many Yoruba towns hold markets on a rotating schedule.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'live'),
  ('ff7d5661-414c-5524-9d61-2bd897c0ac73', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Igbo word for market?', '["Ahịa","Ụlọ","Ọjà","Kasuwa"]'::jsonb, 0, 3, 'Igbo market days are Eke, Orie, Afọ and Nkwọ.', 'https://en.wikipedia.org/wiki/Igbo_language', 'live'),
  ('2fa2c48e-c322-5b66-a3e1-0e2531584607', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Hausa word for school?', '["Gida","Kasuwa","Makaranta","Masallaci"]'::jsonb, 2, 3, '''Gida'' means house.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('6faf9cf5-e6ba-57ee-a24d-676f569d7b3c', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Igbo saying ''Onye kwe, chi ya ekwe'' means?', '["Agree with your elders","If a person agrees, their chi agrees","God gives to everyone","The chief decides"]'::jsonb, 1, 3, 'Achebe drew on this idea in Things Fall Apart.', 'https://en.wikipedia.org/wiki/Odinani', 'live'),
  ('2ad2ac6f-9570-59d7-b358-e04c84b4702d', 'ec062750-dc53-5896-9199-43aec3f81085', 'What is the Hausa word for girl?', '["Uwa","Yaro","Yarinya","Mace"]'::jsonb, 2, 3, '''Yaro'' means boy.', 'https://en.wikipedia.org/wiki/Hausa_language', 'live'),
  ('66028cb3-44b6-56d8-95da-e58523afba12', 'ec062750-dc53-5896-9199-43aec3f81085', 'The Yoruba proverb says that when a child falls it looks forward, but when an elder falls it looks where?', '["At the ground","Up to God","At the crowd","Back (to see what caused it)"]'::jsonb, 3, 5, 'It means elders learn from the past.', 'https://en.wikipedia.org/wiki/Yoruba_language', 'in_review'),
  ('b372fcec-1a6e-5a5d-9331-7a0e7b021e05', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'The yellow commercial minibuses of Lagos are called?', '["Okada","Keke","Molue","Danfo"]'::jsonb, 3, 1, 'Danfos are usually yellow with black stripes.', 'https://en.wikipedia.org/wiki/Danfo', 'live'),
  ('db8823d7-72a2-57ae-8255-7da806f1b103', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'Motorcycle taxis in Nigeria are popularly called?', '["Okada","Danfo","Kabu kabu","Keke"]'::jsonb, 0, 1, 'The name comes from the defunct Okada Air.', 'https://en.wikipedia.org/wiki/Okada_(motorcycle_taxi)', 'live'),
  ('7b1d5c60-328e-5ac1-afe5-8cf73ec7ae99', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'Three-wheeled tricycle taxis are popularly called?', '["Keke","Molue","Okada","Danfo"]'::jsonb, 0, 1, 'They are also known as Keke NAPEP or Keke Marwa.', 'https://en.wikipedia.org/wiki/Auto_rickshaw', 'live'),
  ('ff998859-e18f-5770-af9c-b9bd17873a0e', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'In Lagos, BRT stands for?', '["Bus Route Ticket","Big Road Transport","Bus Rail Terminal","Bus Rapid Transit"]'::jsonb, 3, 1, 'BRT buses use dedicated lanes.', 'https://en.wikipedia.org/wiki/Transport_in_Lagos', 'live'),
  ('76d36fe3-2acd-5a13-b100-4c0d411073e0', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'Nigerians still shout ''Up NEPA!'' when what happens?', '["School closes","A bus arrives","Electricity is restored","A team scores"]'::jsonb, 2, 1, 'NEPA was the old name of the power company.', 'https://en.wikipedia.org/wiki/National_Electric_Power_Authority', 'live'),
  ('16890b3a-f4ba-5948-9e81-c7d5af80496e', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'In Nigerian homes, ''gen'' is short for?', '["General","Genuine","Generator","Gentleman"]'::jsonb, 2, 1, 'Small generators are common because of power cuts.', 'https://en.wikipedia.org/wiki/Culture_of_Nigeria', 'live'),
  ('a066e0cc-5a64-5c09-8d61-110d4192b611', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'What does WAEC stand for?', '["West African English Council","World African Exam Centre","West African Examinations Council","West African Education Commission"]'::jsonb, 2, 1, 'Students write the WASSCE at the end of secondary school.', 'https://en.wikipedia.org/wiki/West_African_Examinations_Council', 'live'),
  ('c61b61c0-fce7-5e47-a78a-a0ee0e78172d', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'Young graduates doing national service are popularly called?', '["Corpers","Cadets","Interns","Trainees"]'::jsonb, 0, 1, 'NYSC lasts one year.', 'https://en.wikipedia.org/wiki/National_Youth_Service_Corps', 'live'),
  ('f721f80f-33b6-584c-8e3f-019b279b2b87', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', '''Aso ebi'' is…', '["A type of soup","A Yoruba dance","Matching fabric worn by guests at an event","A wedding cake"]'::jsonb, 2, 1, 'Aso ebi means ''family cloth'' in Yoruba.', 'https://en.wikipedia.org/wiki/Aso_ebi', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('7c0db544-eef9-5a3d-881a-732ac5fdad2b', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'A ''gele'' is a…', '["Fan","Head-tie","Shoe","Necklace"]'::jsonb, 1, 1, 'Tying a gele well is considered an art.', 'https://en.wikipedia.org/wiki/Gele_(head_tie)', 'live'),
  ('943d2231-8ecf-5573-a511-bfa70a339968', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'An ''agbada'' is a…', '["Pair of trousers","Flowing wide-sleeved robe for men","Walking stick","Cap"]'::jsonb, 1, 1, 'It is worn for special occasions.', 'https://en.wikipedia.org/wiki/Agbada', 'live'),
  ('70cb6cdc-370c-5f87-8f36-b521595f6002', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', '''Spraying'' money at a party means?', '["Hiding money","Showering celebrants with cash while they dance","Paying the DJ","Donating to charity"]'::jsonb, 1, 1, 'It is a staple of owambe parties.', 'https://en.wikipedia.org/wiki/Money_spraying', 'live'),
  ('3f739203-6b75-57dc-9b15-1c88ead897df', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'A ''Ghana Must Go'' is a…', '["Travel visa","Football chant","Checked woven plastic bag","Dance step"]'::jsonb, 2, 1, 'The name dates from the 1983 expulsion of Ghanaians from Nigeria.', 'https://en.wikipedia.org/wiki/Ghana_Must_Go', 'live'),
  ('0828afbb-57a2-56d0-909c-25956c584442', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', '''Pure water'' in Nigeria refers to?', '["Sachet water","Rain water","Bottled spring water","Tap water"]'::jsonb, 0, 1, 'It is sold cheaply on streets everywhere.', 'https://en.wikipedia.org/wiki/Sachet_water', 'live'),
  ('405a0df7-8035-517e-8d1e-840b67919c78', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'Gala, sold in traffic all over Nigeria, is a…', '["Chewing gum","Biscuit","Sausage roll","Soft drink"]'::jsonb, 2, 1, 'Hawkers sell it to motorists in go-slow.', 'https://en.wikipedia.org/wiki/Culture_of_Nigeria', 'live'),
  ('0faef441-8b28-50db-9eaa-188220a52cbd', '3aa4c1e6-7ac4-5d8c-8926-6e09ec7be605', 'Lagos''s famous electronics market, Computer Village, is in which area?', '["Surulere","Ikeja","Yaba","Lekki"]'::jsonb, 1, 1, 'It is one of Africa''s biggest phone and gadget markets.', 'https://en.wikipedia.org/wiki/Computer_Village', 'live'),
