  ('934c3787-3ef6-5ffa-83e1-42eabc5da871', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Which agency regulates telecoms in Nigeria?', '["NITDA","NCC","NERC","NBC"]'::jsonb, 1, 4, 'NCC stands for Nigerian Communications Commission.', 'https://en.wikipedia.org/wiki/Nigerian_Communications_Commission', 'live'),
