  ('e099e6db-b4f7-55a2-be07-3c7e8e3738f0', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Moniepoint became a ''unicorn'' (valued at $1 billion+) in which year?', '["2019","2021","2024","2016"]'::jsonb, 2, 4, 'Google''s Africa fund was among its backers.', 'https://en.wikipedia.org/wiki/Moniepoint', 'in_review'),
  ('d639ebc8-7949-56c9-b545-3e7ec1f6ed97', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Billionaire Mike Adenuga is popularly nicknamed?', '["The Oracle","The Eagle","The Bull","The Lion"]'::jsonb, 2, 4, 'He rarely gives interviews.', 'https://en.wikipedia.org/wiki/Mike_Adenuga', 'in_review'),
  ('7786aac0-63fb-5e9d-9ac9-878f6756a55a', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Nigeria''s cashless policy was first piloted in which city in 2012?', '["Lagos","Kano","Port Harcourt","Abuja"]'::jsonb, 0, 4, 'It set daily limits on cash withdrawals.', 'https://en.wikipedia.org/wiki/Central_Bank_of_Nigeria', 'in_review'),
  ('b8a3a036-d6d1-53fa-a5a5-500f37b4df49', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'First Bank began in 1894 under which name?', '["Royal Niger Bank","Colonial Bank","Barclays DCO","Bank of British West Africa"]'::jsonb, 3, 5, 'It was founded by Alfred Jones, a Liverpool shipping magnate.', 'https://en.wikipedia.org/wiki/First_Bank_of_Nigeria', 'live'),
  ('cfb49956-fa74-51de-883d-512545ddc319', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Aliko Dangote''s great-grandfather, a famous Kano trader, was?', '["Isyaku Rabiu","Alhassan Dantata","Aminu Kano","Ado Bayero"]'::jsonb, 1, 5, 'Dantata was once the richest man in West Africa.', 'https://en.wikipedia.org/wiki/Alhassan_Dantata', 'live'),
  ('c703d50a-618a-52f1-82ec-9216261b0085', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'In which year was the Central Bank of Nigeria established?', '["1963","1960","1958","1973"]'::jsonb, 2, 5, 'It began operations in 1959.', 'https://en.wikipedia.org/wiki/Central_Bank_of_Nigeria', 'live'),
  ('1278d9b1-b586-5785-8ae3-86b2b5c7f94b', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Which American accelerator backed Paystack in 2016?', '["Techstars","500 Startups","Google for Startups","Y Combinator"]'::jsonb, 3, 5, 'It was Y Combinator''s first Nigerian company.', 'https://en.wikipedia.org/wiki/Paystack', 'live'),
  ('1d7bbf2a-1b55-5f15-88e6-2836df0c6e49', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Which company was Nigeria''s first private GSM licence holder to launch services, in August 2001?', '["Mtel","MTN","Glo","Econet Wireless"]'::jsonb, 3, 5, 'Econet''s network later became Airtel.', 'https://en.wikipedia.org/wiki/Airtel_Nigeria', 'in_review'),
  ('d4238067-0c8a-5821-837b-d55307599607', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'NIGCOMSAT-1, Nigeria''s first communications satellite, was launched from which country in 2007?', '["China","India","Russia","United States"]'::jsonb, 0, 5, 'It failed in orbit in 2008 and was replaced in 2011.', 'https://en.wikipedia.org/wiki/NigComSat-1', 'in_review'),
  ('64a54430-675e-5bab-bfc2-125369c949a6', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Which company owns DStv and GOtv?', '["MultiChoice","MTN","StarTimes","Silverbird"]'::jsonb, 0, 1, 'MultiChoice is a South African company.', 'https://en.wikipedia.org/wiki/MultiChoice', 'live'),
  ('aa12bf74-26e9-55af-89de-111075200589', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Who founded Heirs Holdings?', '["Femi Otedola","Aliko Dangote","Tony Elumelu","Jim Ovia"]'::jsonb, 2, 1, 'Heirs Holdings invests in power, oil, banking and more.', 'https://en.wikipedia.org/wiki/Heirs_Holdings', 'live'),
  ('4be56dbd-ccac-5c12-a642-168b2a6a0089', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Where is Paystack headquartered?', '["London","Abuja","Lagos","Nairobi"]'::jsonb, 2, 1, 'It now operates in several African countries.', 'https://en.wikipedia.org/wiki/Paystack', 'live'),
  ('22ffb034-37c5-5c88-bd3e-7ecd5d76705d', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Oando is mainly an…', '["Airline","Bank","Oil and gas company","Food company"]'::jsonb, 2, 2, 'It is listed on the Nigerian Exchange.', 'https://en.wikipedia.org/wiki/Oando', 'live'),
  ('b16b0482-10c8-5f00-9608-209a8a19cd95', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Nairaland is a…', '["Bank","Football club","Fuel station chain","Popular online forum"]'::jsonb, 3, 2, 'Its sections cover politics, romance, jobs and more.', 'https://en.wikipedia.org/wiki/Nairaland', 'live'),
  ('6f669b54-01c0-5414-b367-a1116d00ded5', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Jiji is best known as a…', '["Streaming service","Fashion label","Classifieds marketplace","Bank"]'::jsonb, 2, 2, 'People use it to buy and sell cars, phones and property.', 'https://en.wikipedia.org/wiki/Jiji.ng', 'live'),
  ('7a5a28c3-1ff8-5868-a428-b63083159a45', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'StarTimes, the pay-TV company, comes from which country?', '["India","Nigeria","China","South Africa"]'::jsonb, 2, 2, 'It has a joint venture with NTA.', 'https://en.wikipedia.org/wiki/StarTimes', 'live'),
  ('0a832814-5f31-5b6f-b395-f5da161e782d', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Femi Otedola first made his fortune in which business?', '["Real estate","Telecoms","Cement","Diesel and petroleum distribution"]'::jsonb, 3, 3, 'His company Zenon Petroleum was a major diesel supplier.', 'https://en.wikipedia.org/wiki/Femi_Otedola', 'live'),
  ('7e63e207-9bc6-5024-a6c8-df69d6330df2', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Cosmas Maduka founded which company?', '["Chisco","Ekene Dili Chukwu","Innoson","Coscharis Group"]'::jsonb, 3, 3, 'Coscharis is known for car sales and assembly.', 'https://en.wikipedia.org/wiki/Cosmas_Maduka', 'live')
insert into questions (id, category_id, text, options, correct_index, difficulty, fact, source_url, status) values
  ('efe4e154-a81f-5688-b324-4a8cee2635da', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Who founded the Silverbird group, known for cinemas?', '["John Momoh","Ben Murray-Bruce","Mo Abudu","Raymond Dokpesi"]'::jsonb, 1, 3, 'Silverbird Galleria opened in Victoria Island in 2004.', 'https://en.wikipedia.org/wiki/Ben_Murray-Bruce', 'live'),
  ('60cdf204-b45b-5767-ae07-9e4251550dca', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Ibukun Awosika became the first female chair of which bank?', '["First Bank","Zenith Bank","UBA","GTBank"]'::jsonb, 0, 3, 'She chaired First Bank from 2015 to 2021.', 'https://en.wikipedia.org/wiki/Ibukun_Awosika', 'live'),
  ('d3b19a38-4edd-535f-ae19-00cc28a5e475', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Where is Flutterwave headquartered?', '["San Francisco","London","Nairobi","Lagos"]'::jsonb, 0, 3, 'Most of its staff are in Africa.', 'https://en.wikipedia.org/wiki/Flutterwave', 'live'),
  ('fadda7f7-a421-578f-b6c2-bbd7f64c3b88', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'In which year was Nigeria''s Startup Act signed into law?', '["2022","2018","2024","2020"]'::jsonb, 0, 3, 'It offers incentives to tech startups.', 'https://en.wikipedia.org/wiki/Economy_of_Nigeria', 'live'),
  ('35c6ac5b-9b3a-5559-92e0-5f8c90e34fc0', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Nigerian fintech Carbon was originally called?', '["Paga","Kwik","Lidya","Paylater"]'::jsonb, 3, 3, 'It rebranded in 2019.', 'https://en.wikipedia.org/wiki/Carbon_(company)', 'live'),
  ('362eeed7-3370-5901-a102-819e252d7f1c', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Street phone-call businesses in the early 2000s were known as?', '["Sim stalls","Talk shops","Mobile kiosks","Umbrella call centres"]'::jsonb, 3, 3, 'Vendors sat under umbrellas selling calls by the minute.', 'https://en.wikipedia.org/wiki/Telecommunications_in_Nigeria', 'in_review'),
  ('4b575f0f-e51f-5c89-bb29-58b0cdd1ee0a', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'MTN Nigeria listed on the Nigerian Stock Exchange in which year?', '["2023","2010","2001","2019"]'::jsonb, 3, 4, 'It listed by introduction, without an IPO.', 'https://en.wikipedia.org/wiki/MTN_Nigeria', 'live'),
  ('cb916b7c-dab5-5d1a-ae6b-2b98bacded60', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'The main index of the Nigerian Exchange is called?', '["Lagos Composite","NGX 100","All-Share Index","Naira Index"]'::jsonb, 2, 4, 'It tracks all listed equities.', 'https://en.wikipedia.org/wiki/Nigerian_Exchange_Group', 'live'),
  ('dcf88f80-7704-515b-a439-e767f1b4d7b3', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Which two telecoms got Payment Service Bank licences in 2022 for mobile money?', '["MTN and Airtel","Airtel and 9mobile","Glo and 9mobile","MTN and Glo"]'::jsonb, 0, 4, 'MTN''s service is MoMo PSB and Airtel''s is SmartCash.', 'https://en.wikipedia.org/wiki/Mobile_payment', 'live'),
  ('9a2938c3-f108-5de3-bfc7-8d1b239f6163', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'The Treasury Single Account (TSA) for federal revenues was fully enforced in which year?', '["2019","2015","2005","2010"]'::jsonb, 1, 4, 'It moved government money from commercial banks into the CBN.', 'https://en.wikipedia.org/wiki/Economy_of_Nigeria', 'in_review'),
  ('80f2b2f1-902c-5f5b-a788-6b64991a95bd', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Kobo360 is a Nigerian startup in which industry?', '["Education","Health","Banking","Haulage and logistics"]'::jsonb, 3, 4, 'It connects truck owners with cargo.', 'https://en.wikipedia.org/wiki/Kobo360', 'in_review'),
  ('0c1b1b88-55c7-5180-808e-b38fb33ab784', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Airtel Africa listed on which two stock exchanges in 2019?', '["New York and Lagos","Johannesburg and Nairobi","London and Johannesburg","London and Lagos"]'::jsonb, 3, 5, 'Its biggest market is Nigeria.', 'https://en.wikipedia.org/wiki/Airtel_Africa', 'in_review'),
  ('abfe788b-f2fa-558a-a40e-0158f743c5bf', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Which Nigerian bank is known for its orange branding?', '["Access Bank","Zenith Bank","First Bank","GTBank"]'::jsonb, 3, 2, 'GTBank''s orange is one of Nigeria''s most recognisable brand colours.', 'https://en.wikipedia.org/wiki/Guaranty_Trust_Bank', 'live'),
  ('cee34241-17e2-5cf5-82f0-baea70242cc9', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Which network launched in 2003 and popularised per-second billing in Nigeria?', '["MTN","9mobile","Airtel","Glo"]'::jsonb, 3, 3, 'Before Glo, calls were billed per minute.', 'https://en.wikipedia.org/wiki/Globacom', 'live'),
  ('ece383f9-6a7e-5e2c-b4d1-d3f531480376', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Ecobank Transnational is headquartered in which city?', '["Lagos","Lomé","Accra","Abidjan"]'::jsonb, 1, 3, 'Ecobank operates in over 30 African countries.', 'https://en.wikipedia.org/wiki/Ecobank', 'live'),
  ('7398ebc2-2a6e-51fe-9409-5759c98e1083', '18161701-c98a-5a73-a7e9-079c46f8cb1d', 'Dangote Cement''s largest plant is at which town?', '["Gboko","Ewekoro","Obajana","Ibese"]'::jsonb, 2, 4, 'Obajana is in Kogi State.', 'https://en.wikipedia.org/wiki/Obajana_Cement_Plant', 'live')
